        // Update AcadamicInfo ...
        public JsonResult EditAcadamicInfo()
        {
            string sStudentID = (Session[Common.SESSION_VARIABLES.STUDENT_ID] != null) ? Session[Common.SESSION_VARIABLES.STUDENT_ID].ToString() : string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var str = Request.Form["str"];
            string filePath = string.Empty;
            string sImagePath = string.Empty;
            string _sDirectorypath = string.Empty;

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.STUDENT_IMGAE_PATH;

                    if (!Directory.Exists(_sDirectorypath))
                    {
                        Directory.CreateDirectory(_sDirectorypath);
                    }


                    var Result = JsonConvert.DeserializeObject<AcademicDetails>(str);
                    //string sRegisterDate = CommonMethods.ConvertdatetoyearFromat(Result.sRegisterDate);
                    string sAdmissionDate = CommonMethods.ConvertdatetoyearFromat(Result.AdmissionDate);
                    var FetchProgramGroupId = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(Result,
                        SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchShiftAndProgrameGroupByClassId), sAcademicYear).DataSource.Data;
                    if (FetchProgramGroupId != null && FetchProgramGroupId.Count > 0)
                    {
                        Result.PROGRAMME_GROUP_ID = FetchProgramGroupId.FirstOrDefault().PROGRAMME_GROUP_ID;
                        Result.PROGRAMME_MODE = FetchProgramGroupId.FirstOrDefault().PROGRAMME_MODE;
                        Result.Shift = FetchProgramGroupId.FirstOrDefault().SHIFT;
                        Result.Department = FetchProgramGroupId.FirstOrDefault().DEPARTMENT;
                    }

                    // Check Update For Student Log ...
                    var liAcademicInfo = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new STU_PERSONAL_INFO() { STUDENT_ID = sStudentID },
                        StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAcadamicInfo), sAcademicYear).DataSource.Data;

                    dv.Clear();
                    dv.Add(Common.STU_PERSONAL_INFO.REGISTER_NO, Result.RegisterNo, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.FIRST_NAME, Result.FIRST_NAME, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.LAST_NAME, Result.LAST_NAME, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.ROLL_NO, Result.RollNo, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.UNIVERSITY_ROLLNO, Result.URollNo, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.ADMISSION_DATE, sAdmissionDate, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.ADMISSION_NO, Result.AdmissionNo, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.ADMITTED_CLASS, Result.AdmittedClass, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.STUDENT_REGISTERDED_DATE, "0000-00-00", EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.REMARKS, Result.Remarks, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.TC_SERIAL_NO, Result.TCSerialNo, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.CLASS_ID, Result.CLASS_ID, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.PROGRAM_ID, Result.PROGRAMME_GROUP_ID, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.BATCH, Result.Batch, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.CURRENT_BATCH, Result.CurrentBatch, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.DEPT_ID, Result.Department, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.SHIFT_ID, Result.Shift, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.STU_EMAILID, Result.Stu_Email, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.IS_LEFT, Result.IsLeft, EnumCommand.DataType.String);
                    dv.Add(Common.STU_PERSONAL_INFO.STUDENT_ID, sStudentID, EnumCommand.DataType.String);
                    dv.Add(Common.USER_ACCOUNT.ROLE, Common.USER_TYPE.STUDENT, EnumCommand.DataType.String);
                    dv.Add(Common.USER_ACCOUNT.USER_TYPE, Common.USER_TYPE.STUDENT, EnumCommand.DataType.String);

                    using (StudentViewModel objViewModel = new StudentViewModel())
                    {
                        resultArgs = objViewModel.UpdateAcadamic(dv);
                        // Image Updation ....
                        var Rollno = Request.Form["RollNo"];
                        if (Request.Files.Count > 0)
                        {
                            var File = Request.Files[0];
                            string ImgName = File.FileName;
                            var Img = ImgName.Split('.');
                            string fileName = ImgName.Replace(Img[0], Result.RollNo);

                            if (!string.IsNullOrEmpty(fileName))
                            {
                                filePath = _sDirectorypath + fileName;
                                sImagePath = "\\" + Common.URLPages.STUDENT_IMGAE_PATH + fileName;
                                File.SaveAs(filePath);
                                Result.PHOTO = sImagePath;

                            }
                            string sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStudentimage).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sStudentID);
                            var UpdatePhoto = CMSHandler.SaveOrUpdate(Result, sSql);
                        }

                        if (resultArgs.Success)
                        {
                            if (liAcademicInfo != null && liAcademicInfo.Count > 0)
                            {
