                                }
                                if (liAcademicInfo.FirstOrDefault().ADMITTED_CLASS != Result.AdmittedClass)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','ADMITTED_CLASS','" + liAcademicInfo.FirstOrDefault().ADMITTED_CLASS + "','" + Result.AdmittedClass + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().REMARKS != Result.Remarks)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','REMARKS','" + liAcademicInfo.FirstOrDefault().REMARKS + "','" + Result.Remarks + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().CLASS_ID != Result.CLASS_ID)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','CLASS_ID','" + liAcademicInfo.FirstOrDefault().CLASS_ID + "','" + Result.CLASS_ID + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().PROGRAM_ID != Result.PROGRAMME_GROUP_ID)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','PROGRAM_ID','" + liAcademicInfo.FirstOrDefault().PROGRAM_ID + "','" + Result.PROGRAMME_GROUP_ID + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().BATCH != Result.Batch)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','BATCH','" + liAcademicInfo.FirstOrDefault().BATCH + "','" + Result.Batch + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().CURRENT_BATCH != Result.CurrentBatch)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','CURRENT_BATCH','" + liAcademicInfo.FirstOrDefault().CURRENT_BATCH + "','" + Result.CurrentBatch + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().DEPT_ID != Result.Department)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','DEPT_ID','" + liAcademicInfo.FirstOrDefault().DEPT_ID + "','" + Result.Department + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().SHIFT_ID != Result.Shift)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','SHIFT_ID','" + liAcademicInfo.FirstOrDefault().SHIFT_ID + "','" + Result.Shift + "','" + sUserId + "',unix_timestamp()),";
                                }
                                if (liAcademicInfo.FirstOrDefault().STU_EMAILID != Result.Stu_Email)
                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','STU_EMAILID','" + liAcademicInfo.FirstOrDefault().STU_EMAILID + "','" + Result.Stu_Email + "','" + sUserId + "',unix_timestamp()),";
                                }
