                                {
                                    sQuery += "('" + sStudentID + "','UPDATE','IS_LEFT','" + liAcademicInfo.FirstOrDefault().IS_LEFT + "','" + Result.IsLeft + "','" + sUserId + "',unix_timestamp()),";
                                }
                                sQuery = sQuery.TrimEnd(',');
                                sQuery = sQuery + ";";
                                using (MySQLHandler ObjLog = new MySQLHandler())
                                {
                                    var sResultArg = ObjLog.ExecuteAsScripts(sQuery);
                                }
                            }


                            var objAccountInfo = new USER_ACCOUNT_INFO();
                            var liAccountInfo = new List<USER_ACCOUNT_INFO>();

