                        //BANK_NAME = dtPersonalInfo.Rows[0][Common.STU_PERSONAL_INFO.BANK_NAME].ToString(),
                        //BRANCH_NAME = dtPersonalInfo.Rows[0][Common.STU_PERSONAL_INFO.BRANCH_NAME].ToString(),
                        IFSC_CODE = dtPersonalInfo.Rows[0][Common.STU_PERSONAL_INFO.IFSC_CODE].ToString(),
                    };
                    return Json(objPersonal);
                }
                else
                {
                    sResult = "No Records Available ...!";
                    return Json(sResult);
                }
            }
            else
            {

                sResult = "Session Has Expired Please Login And Try Again ...!";
                return Json(sResult);
            }
        }


        // Edit PersoanlInfo UI ...
        public ActionResult EditStuPersonalInfo()
        {
            StuPersonalInfo objStuPersonalInfo = new StuPersonalInfo();
            string sAcademicyear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicyear))
            {
                try
                {
                    // Gender ....
                    var liGender = (List<SupGender>)CMSHandler.FetchData<SupGender>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchGender)).DataSource.Data;
                    if (liGender != null && liGender.Count > 0)
                        objStuPersonalInfo.GENDERID = new SelectList(liGender, Common.SUP_GENDER.GENDER_ID, Common.SUP_GENDER.GENDER_NAME);

                    // Community ....
                    var liCommunity = (List<SupCommunity>)CMSHandler.FetchData<SupCommunity>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCommunity)).DataSource.Data;
                    if (liCommunity != null && liCommunity.Count > 0)
                        objStuPersonalInfo.COMMUNITY = new SelectList(liCommunity, Common.SUP_COMMUNITY.COMMUNITYID, Common.SUP_COMMUNITY.COMMUNITY);

                    // MotherTongue ....
                    var liMotherTongue = (List<SupMotherTongue>)CMSHandler.FetchData<SupMotherTongue>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchMotherTongue)).DataSource.Data;
                    if (liMotherTongue != null && liMotherTongue.Count > 0)
                        objStuPersonalInfo.MOTHERTONGUE = new SelectList(liMotherTongue, Common.SUP_MOTHER_TONGUE.MOTHER_TONGUE_ID, Common.SUP_MOTHER_TONGUE.MOTHER_TONGUE_NAME);

                    // Language ....
                    var liLanguage = (List<Sup_Language>)CMSHandler.FetchData<Sup_Language>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchLanguage)).DataSource.Data;
                    if (liLanguage != null && liLanguage.Count > 0)
                    {
                        objStuPersonalInfo.FIRSTLANGUAGE = new SelectList(liLanguage, Common.SUP_LANGUAGE.LANGUAGE_ID, Common.SUP_LANGUAGE.LANGUAGE_NAME);
                        objStuPersonalInfo.SECONDLANGUAGE = new SelectList(liLanguage, Common.SUP_LANGUAGE.LANGUAGE_ID, Common.SUP_LANGUAGE.LANGUAGE_NAME);
                    }
                    // Boold Group ...
                    var liBloodGroup = (List<SupBloodGroup>)CMSHandler.FetchData<SupBloodGroup>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchBloodGroup)).DataSource.Data;
                    if (liBloodGroup != null && liBloodGroup.Count > 0)
                    {
                        objStuPersonalInfo.BLOODGROUP = new SelectList(liBloodGroup, Common.SUP_BLOOD_GROUP.BLOOD_GROUP_ID, Common.SUP_BLOOD_GROUP.BLOOD_GROUP_NAME);
                    }

                    // Religion ...
                    var liReligion = (List<SUP_RELIGION>)CMSHandler.FetchData<SUP_RELIGION>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchReligion)).DataSource.Data;
                    if (liReligion != null && liReligion.Count > 0)
                    {
                        objStuPersonalInfo.RELIGION = new SelectList(liReligion, Common.SUP_RELIGION.RELIGIONID, Common.SUP_RELIGION.RELIGION);
                    }

                    //Nationality ...
                    var liNationality = (List<SupNationality>)CMSHandler.FetchData<SupNationality>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchNationality)).DataSource.Data;
                    if (liNationality != null && liNationality.Count > 0)
                    {
                        objStuPersonalInfo.NATIONALITY = new SelectList(liNationality, Common.SUP_NATIONALITY.NATIONALITY_ID, Common.SUP_NATIONALITY.NATIONALITY_NAME);
                    }

                    //SpeciallyAbled ...
                    var liSpeciallyAbled = (List<Sup_Specially_Abled>)CMSHandler.FetchData<Sup_Specially_Abled>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSpeciallyAbled)).DataSource.Data;
                    if (liSpeciallyAbled != null && liSpeciallyAbled.Count > 0)
                    {
                        objStuPersonalInfo.SPECIALLYABLED = new SelectList(liSpeciallyAbled, Common.SUP_SPECIALLY_ABLED.SPECIALLY_ABLED_ID, Common.SUP_SPECIALLY_ABLED.SPECIALLY_ABLED_NAME);
                    }

                    //liResidencyType ...
                    var liResidencyType = (List<Sup_ResidencyType>)CMSHandler.FetchData<Sup_ResidencyType>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchResidencyType)).DataSource.Data;
                    if (liResidencyType != null && liResidencyType.Count > 0)
                    {
                        objStuPersonalInfo.RESIDENCYTYPE = new SelectList(liResidencyType, Common.SUP_RESIDENCY_TYPE.RESIDENCY_TYPE_ID, Common.SUP_RESIDENCY_TYPE.RESIDENCY_TYPE_NAME);
                    }
                    //Marital Status ..
                    var liMaritalStatus = (List<SupMaritalStatus>)CMSHandler.FetchData<SupMaritalStatus>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchMarritalStatus)).DataSource.Data;
                    if (liMaritalStatus != null && liMaritalStatus.Count > 0)
                    {
                        objStuPersonalInfo.MARITALSTATUS = new SelectList(liMaritalStatus, Common.SUP_MARRITAL_STATUS.MARITAL_STAUS_ID, Common.SUP_MARRITAL_STATUS.MARITAL_STATUS_NAME);
                    }

                    // Sup_Role ...
                    var liRole = new List<SUP_ROLE>();
                    liRole = (List<SUP_ROLE>)CMSHandler.FetchData<SUP_ROLE>(null, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchSupRole)).DataSource.Data;
                    objStuPersonalInfo.Role = new SelectList(liRole, Common.SUP_ROLE.ROLE_ID, Common.SUP_ROLE.ROLE_NAME);

                    // UserType ...
                    var liUserType = new List<SUP_USER_TYPE>();
                    liUserType = (List<SUP_USER_TYPE>)CMSHandler.FetchData<SUP_USER_TYPE>(null, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchUserType)).DataSource.Data;
                    objStuPersonalInfo.UserType = new SelectList(liUserType, Common.SUP_USER_TYPE.USER_TYPE_ID, Common.SUP_USER_TYPE.USER_TYPE_NAME);
                    return View(objStuPersonalInfo);
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjHandler = new ErrorLog())
                    {
                        ObjHandler.WriteError("StudentController", "EditStuPersonalInfo", "Err MSg: " + ex.Message, "Query is empty!");
                        ObjHandler.WriteError("StudentController", "EditStuPersonalInfo", ex.Message);
                    }
                    return View(objStuPersonalInfo);
                }
            }
            else
            {
                sResult = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                return Json(sResult, JsonRequestBehavior.AllowGet);
            }
        }

