        // Insert Parents Details ..
        public JsonResult SaveParentsDetails(string JsonParents)
        {
            string sStudentID = (Session[Common.SESSION_VARIABLES.LAST_INSERT_ID] != null) ? Session[Common.SESSION_VARIABLES.LAST_INSERT_ID].ToString() : string.Empty;
            if (string.IsNullOrEmpty(sStudentID))
                sStudentID = (Session[Common.SESSION_VARIABLES.STUDENT_ID] != null) ? Session[Common.SESSION_VARIABLES.STUDENT_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sStudentID))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<STU_PERSONAL_INFO>(JsonParents);
                    //Result.FR_DATE_OF_EXPIRY = CommonMethods.ConvertdatetoyearFromat(Result.FR_DATE_OF_EXPIRY);
                    //Result.MO_DATE_OF_EXPIRY = CommonMethods.ConvertdatetoyearFromat(Result.MO_DATE_OF_EXPIRY);
                    Result.F_DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.F_DATE_OF_BIRTH);
                    Result.M_DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.M_DATE_OF_BIRTH);
                    Result.STUDENT_ID = sStudentID;
                    var UpdateParentsDetails = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateParentsInfo));
                    ObjJsonData.Message = (UpdateParentsDetails.Success) ? Common.ErrorCode.Ok : Common.Messages.FailedToSaveRecords;
                }
                catch (Exception ex)
                {
