        // Insert Address Details ..
        public JsonResult InsertStuAddress(string JsonAddress)
        {
            string sStudentID = (Session[Common.SESSION_VARIABLES.LAST_INSERT_ID] != null) ? Session[Common.SESSION_VARIABLES.LAST_INSERT_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sStudentID))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<STU_ADDRESS>(JsonAddress);
                    Result.STUDENT_ID = sStudentID;
                    sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.IfStudentExitsByMultiTable);
                    sSql = sSql.Replace(Common.Delimiter.QUS + "TABLE_NAME", "STU_ADDRESS");
                    Exits = (List<IF_STUDENT_EXITS>)CMSHandler.FetchData<IF_STUDENT_EXITS>(new IF_STUDENT_EXITS() { STUDENT_ID = sStudentID }, sSql).DataSource.Data;
                    if (Exits != null && Exits.Count > 0)
                    {
                        var UpdateAddress = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateAddress));
                        ObjJsonData.Message = (UpdateAddress.Success) ? Common.ErrorCode.Ok : Common.Messages.RecordsSavedSuccessfully;
                    }
                    else
                    {
                        var InsertAddress = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.InsertStudentAddressDetails));
                        ObjJsonData.Message = (InsertAddress.Success) ? Common.ErrorCode.Ok : Common.Messages.RecordsSavedSuccessfully;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjHandler = new ErrorLog())
                    {
                        ObjHandler.WriteError("StudentController", "SavePersonalInfo", "Err MSg: " + ex.Message, "Query is empty!");
                        ObjHandler.WriteError("StudentController", "SavePersonalInfo", ex.Message);
                    }
                    ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

