        public JsonResult FetchProgrammeGroupByProgrammeIdAndProgrammeMode(string sProgrammeGroupId)
        {
            string sClass = string.Empty;
            string sProgrammeGroup = string.Empty;
            string JsonData = string.Empty;
            JsonResultData objResult = new JsonResultData();
            try
            {
                if (Session[Common.SESSION_VARIABLES.USER_ID] != null)
                {
                    string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
                    var FetchProgrammeGroup = (List<SUP_APPTYPE_PROG_GROUPS>)CMSHandler.FetchData<SUP_APPTYPE_PROG_GROUPS>(new SUP_APPTYPE_PROG_GROUPS() { PROGRAMME_GROUP_ID = sProgrammeGroupId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchProgrammeGroupById)).DataSource.Data;
                    if (FetchProgrammeGroup != null && FetchProgrammeGroup.Count > 0)
                    {
                        var FetchClass = (List<cp_Classes_2017>)CMSHandler.FetchData<cp_Classes_2017>(new cp_Classes_2017() { PROGRAMME_GROUP_ID = sProgrammeGroupId, SHIFT = FetchProgrammeGroup.FirstOrDefault().SHIFT }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchClassByShiftAndProgrammeGroupId), sAcademicYear).DataSource.Data;
                        var FetchProgramme = (List<SUP_APPTYPE_PROG_GROUPS>)CMSHandler.FetchData<SUP_APPTYPE_PROG_GROUPS>(new SUP_APPTYPE_PROG_GROUPS() { PROGRAMME_ID = FetchProgrammeGroup.FirstOrDefault().PROGRAMME_ID, PROGRAMME_MODE = FetchProgrammeGroup.FirstOrDefault().PROGRAMME_MODE }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchProgrammeGroupByShiftAndProgrammeId)).DataSource.Data;
                        if (FetchClass != null && FetchClass.Count > 0)
                        {
                            foreach (var item in FetchClass)
                                sClass += "<option value='" + item.CLASS_ID + "'>" + item.CLASS_NAME + "</option>";
                        }
                        if (FetchProgramme != null && FetchProgramme.Count > 0)
                        {
                            foreach (var item in FetchProgramme)
                                sProgrammeGroup += "<option value='" + item.PROGRAMME_GROUP_ID + "'>" + item.PROGRAMME_NAME + "</option>";
                        }
                    }
                }
                else
                {
                    objResult.ErrorCode = Common.ErrorCode.RequestTimeout;
                    objResult.Message = Common.ErrorMessage.RequestTimeout;
                    return Json(objResult, JsonRequestBehavior.AllowGet);
                }
                var objJsonData = new cp_Classes_2017() { PROGRAMME = sProgrammeGroup, CLASS_ID = sClass };
                JsonData = JsonConvert.SerializeObject(objJsonData);
                return Json(JsonData, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {

                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "FetchProgrammeGroupByProgrammeIdAndProgrammeMode", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("StudentController", "FetchProgrammeGroupByProgrammeIdAndProgrammeMode", ex.Message);
                    return Json(JsonData, JsonRequestBehavior.AllowGet);
                }
            }
        }
