            {

                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "BindStudentToPromote", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("StudentController", "BindStudentToPromote", ex.Message);
                }
            }
            return View(objViewModel);
        }
