        public JsonResult UpdateStuCourseInfo(string sStuCourseInfo)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            var ObjJsonData = new JsonResultData();
            Stu_Course_Info objModel = new Stu_Course_Info();
            ResultArgs ResultArg = new ResultArgs();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                string sOption = string.Empty;
                try
                {
                    StudentViewModel objViewModel = new StudentViewModel();
                    var objJson = JsonConvert.DeserializeObject<JsonStuCourseInfo>(sStuCourseInfo);
                    if (objJson.SelectedStudentList != null && objJson.SelectedStudentList.Count > 0)
                    {
                        foreach (var item in objJson.SelectedStudentList)
                        {
                            if (item.STUDENT_ID == "undefined")
                            {
                                continue;
                            }

                            // Check CIA Mark Entered ....
                            var IsCIAMarkExist = (List<StudentPromotionList>)CMSHandler.FetchData<StudentPromotionList>(objModel,
                                   StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentCIAMarksByStudentIdAndCourseId), sAcademicYear).DataSource.Data;
                            if (IsCIAMarkExist != null && IsCIAMarkExist.Count > 0)
                            {
                                ObjJsonData.Message += item.ROLL_NO + " - CIA Mark is entered so Failed To Save.!!! \n";

                            }
                            else
                            {
                                // Check Stu Course Info Exist ....
                                var IsStuCourseInfoExist = (List<Stu_Course_Info>)CMSHandler.FetchData<Stu_Course_Info>(item,
                                          StudentSQL.GetStudentSQL(StudentSQLCommads.IsStuCourseInfoExist), sAcademicYear).DataSource.Data;
                                if (IsStuCourseInfoExist != null && IsStuCourseInfoExist.Count > 0)
                                {
                                    item.COURSE_INFO_ID = IsStuCourseInfoExist.FirstOrDefault().COURSE_INFO_ID;
                                    // Update Method ....
                                    ResultArg = CMSHandler.SaveOrUpdate(item, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuCourseInfo), sAcademicYear);
                                }
                                else
                                {
                                    // Save Method ...
                                    ResultArg = CMSHandler.SaveOrUpdate(item, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveStuCourseInfo), sAcademicYear);
                                }

                                // Retrun String Result  Append  ...
                                ObjJsonData.Message += (ResultArg.Success) ? item.ROLL_NO + "-" + Common.Messages.RecordsSavedSuccessfully + "\n" : item.ROLL_NO + "-" + Common.Messages.FailedToSaveRecords + "\n";
                            }


                            //var CheckClassCourse = (List<ClassCourse>)CMSHandler.FetchData<ClassCourse>(item, StudentSQL.GetStudentSQL(StudentSQLCommads.CheckClassCourse), sAcademicYear).DataSource.Data;
                            //if (CheckClassCourse != null && CheckClassCourse.Count > 0)
                            //{
                            //    sOption += item.ROLL_NO + " - This is not an Optional Paper...!!!\n";
                            //}
                            //else
                            //{
                            //    var FetchShiftByClassId = (List<cp_Classes_2017>)CMSHandler.FetchData<cp_Classes_2017>(item, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchShiftByClassId), sAcademicYear).DataSource.Data;
                            //    if (FetchShiftByClassId != null && FetchShiftByClassId.Count > 0)
                            //        item.SHIFT = FetchShiftByClassId.SingleOrDefault().SHIFT;
                            //    var FetchSemesterByShiftId = (List<cp_Course_Root_2017>)CMSHandler.FetchData<cp_Course_Root_2017>(item, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSemesterByCourseId), sAcademicYear).DataSource.Data;
