        public ActionResult BindIndividualSemesterMarkSheet(string sStudentId, string sExamSettingId, string sBatch, string sApplicationType)
        {
            StudentViewModel objViewModel = new StudentViewModel();
            SEMESTER_MARKS objModel = new SEMESTER_MARKS();
            ACADEMIC_YEAR aObjModel = new ACADEMIC_YEAR();
            string sSql = string.Empty;
            string Sql = string.Empty;
            string AcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            if (!string.IsNullOrEmpty(AcademicYear))
            {
                objModel.STUDENT_ID = sStudentId;
                objModel.BATCH_ID = sBatch;
                objModel.APPLICATION_TYPE_ID = sApplicationType;
                objModel.STUDENT_ID = sStudentId;
                objModel.EXAM_SETTING_ID = sExamSettingId;
                try
                {
                    if (sApplicationType == "6")
                    {
                        Sql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMphillProjectByStudentId).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.STUDENT_ID, sStudentId);
                        objViewModel.LiMphillStudentProject = (List<MPHILL_STUDENT_PROJECT>)CMSHandler.FetchData<MPHILL_STUDENT_PROJECT>(objModel, Sql).DataSource.Data;
                    }
                    var ExamSetting = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(objModel, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSettingBySettingId), AcademicYear).DataSource.Data;
                    if (ExamSetting != null && ExamSetting.Count > 0)
                    {
                        objModel.ACADEMIC_YEAR = ExamSetting.FirstOrDefault().ACADEMIC_YEAR;
                        sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchIndividualSemesterMarks).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.STUDENT_ID, sStudentId);
                        objViewModel.liSemestermark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, sSql, objModel.ACADEMIC_YEAR).DataSource.Data;
                        if (objViewModel.liSemestermark != null && objViewModel.liSemestermark.Count > 0)
                        {
                            objModel.START_DATE = objViewModel.liSemestermark.FirstOrDefault().START_DATE;
                        }
                    }
                    var BatchExpiredYear = (List<SUP_BATCH_DURATION>)CMSHandler.FetchData<SUP_BATCH_DURATION>(objModel, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchBatchExpiredYear)).DataSource.Data;
                    if (BatchExpiredYear != null && BatchExpiredYear.Count > 0)
                    {
                        for (int i = Convert.ToInt16(BatchExpiredYear.FirstOrDefault().BEGIN_YEAR); i < Convert.ToInt16(BatchExpiredYear.FirstOrDefault().EXPIRED_YEAR); i++)
                        {
                            objModel.ACADEMIC_YEAR = i.ToString();
                            objModel.STUDENT_ID = sStudentId;
                            sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchOverAllSemesterMarks).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.STUDENT_ID, sStudentId);
                            var SemMark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, sSql, i.ToString()).DataSource.Data;
                            if (SemMark != null && SemMark.Count > 0)
                            {
                                objViewModel.liOverAllSemestermark = (objViewModel.liOverAllSemestermark != null && objViewModel.liOverAllSemestermark.Count > 0) ? objViewModel.liOverAllSemestermark.Concat(SemMark).ToList() : SemMark;
                            }
                        }
                    }
                    if (objViewModel.liOverAllSemestermark != null && objViewModel.liOverAllSemestermark.Count > 0)
                    {
                        objViewModel.liOverAllSemestermark.RemoveAll(x => DateTime.Parse(x.START_DATE) > DateTime.Parse(objViewModel.liSemestermark.FirstOrDefault().START_DATE));
                    }
                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("BindIndividualSemesterMarkSheet", "StudentController", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("BindIndividualSemesterMarkSheet", "StudentController", Ex.Message);
                    }

                }
            }
            else
                return RedirectToAction("ErrorMessage", "Error");

            return View(objViewModel);
        }
