        public ActionResult BindCumulativegradeCertificate(string sStudentId, string sApplicationType, string sBatch, string sBatchyear)
        {
            StudentViewModel objViewModel = new StudentViewModel();
            SEMESTER_MARKS objModel = new SEMESTER_MARKS();
            SUP_BATCH_DURATION objbatchduartion = new SUP_BATCH_DURATION();

            string sSql = string.Empty;
            string Sql = string.Empty;
            string AcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            if (!string.IsNullOrEmpty(AcademicYear))
            {
                objViewModel.sAcademicyear = sBatchyear;
                objModel.STUDENT_ID = sStudentId;
                objbatchduartion.BATCH_ID = sBatch;
                objbatchduartion.APPLICATION_TYPE_ID = sApplicationType;
                try
                {
                    var BatchExpiredYear = (List<SUP_BATCH_DURATION>)CMSHandler.FetchData<SUP_BATCH_DURATION>(objbatchduartion, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchBatchExpiredYear)).DataSource.Data;


                    if (BatchExpiredYear != null && BatchExpiredYear.Count > 0)
                    {

                        for (int i = Convert.ToInt16(BatchExpiredYear.FirstOrDefault().BEGIN_YEAR); i <= Convert.ToInt16(BatchExpiredYear.FirstOrDefault().EXPIRED_YEAR); i++)
                        {
                            objModel.STUDENT_ID = sStudentId;
                            objModel.ACADEMIC_YEAR = i.ToString();
                            sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchConsolidateSemesterMarksforauxclg).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.STUDENT_ID, sStudentId);
                            var SemMark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, sSql, Convert.ToString(i)).DataSource.Data;
                            if (SemMark != null && SemMark.Count > 0)
                            {
                                SemMark.FirstOrDefault().BEGIN_YEAR = BatchExpiredYear.FirstOrDefault().BEGIN_YEAR;
                                SemMark.FirstOrDefault().EXPIRED_YEAR = BatchExpiredYear.FirstOrDefault().EXPIRED_YEAR;
                                objViewModel.sBeginyear = BatchExpiredYear.FirstOrDefault().BEGIN_YEAR;
                                objViewModel.sExpiredyear = BatchExpiredYear.FirstOrDefault().EXPIRED_YEAR;

                                objViewModel.liSemestermark = (objViewModel.liSemestermark != null && objViewModel.liSemestermark.Count > 0) ? objViewModel.liSemestermark.Concat(SemMark).ToList() : SemMark;
                            }

                        }
                        objViewModel.liSemestermark = objViewModel.liSemestermark.OrderBy(x => Convert.ToInt16(x.STUDENT_ID)).ThenBy(x => Convert.ToInt16(x.COURSE_ORDER)).ThenBy(x => Convert.ToInt16(x.SEMESTER)).ToList();
                        if (objViewModel.liSemestermark != null && objViewModel.liSemestermark.Count > 0 && objbatchduartion.APPLICATION_TYPE_ID == "1" || objbatchduartion.APPLICATION_TYPE_ID == "3")
                        {
                            var groupstudent = objViewModel.liSemestermark.ToList();
                            foreach (var student in groupstudent)
                            {
                                var valueEducation = objViewModel.liSemestermark.Where(s => s.UGC_COURSE_TYPE == "48" && s.STUDENT_ID == student.STUDENT_ID).ToList();
                                var valtotal = valueEducation.Sum(s => Convert.ToDouble(s.TOTAL) / valueEducation.Count());
                                var total = (List<SUP_GRADE_POINTS>)CMSHandler.FetchData<SUP_GRADE_POINTS>(new SUP_GRADE_POINTS { MIN_MARK = Math.Round(valtotal).ToString() }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchUGgradeByMark)).DataSource.Data;
                                objViewModel.liSemestermark.RemoveAll(s => s.UGC_COURSE_TYPE == "48" && s.SEMESTER != "6" && s.STUDENT_ID == student.STUDENT_ID);
                                objViewModel.liSemestermark.Where(S => S.UGC_COURSE_TYPE == "48" && S.STUDENT_ID == student.STUDENT_ID).Select(s => { s.TOTAL = Math.Round(valtotal).ToString(); s.CREDIT = "2"; s.GRADE_POINT = total.FirstOrDefault().GRADE_POINT; s.GRADE = total.FirstOrDefault().GRADE; ; return s; }).ToList();
                            }

                        }
                    }
                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("BindCumulativegradeCertificate", "StudentController", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("BindCumulativegradeCertificate", "StudentController", Ex.Message);
                    }

                }
            }
            else
                return RedirectToAction("ErrorMessage", "Error");

            return View(objViewModel);
        }

