        public ActionResult BindIndividualCIAReport(string sStudentId, string sComponentId, string sClassId)
        {
            StudentViewModel objViewModel = new StudentViewModel();
            CLASS_INCHARGE objModel = new CLASS_INCHARGE();
            CIA_MARKS_INFO objCIAMarks = new CIA_MARKS_INFO();
            List<CIA_MARKS_INFO> LiCIAMarks = new List<CIA_MARKS_INFO>();
            List<CIA_MARKS_INFO> LiCIAMarks2 = new List<CIA_MARKS_INFO>();
            string sSql = string.Empty;
            string Sql = string.Empty;
            int count = 0;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    objViewModel.liCollgeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), sAcademicYear).DataSource.Data;
                    sSql = SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentDetailsForCIAIndidualReport).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sStudentId);
                    objViewModel.liStudentList = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(null, sSql, sAcademicYear).DataSource.Data;
                    var sStudent = sStudentId.Split(',').ToList();
                    foreach (var item in sStudent)
                    {
                        objCIAMarks.STUDENT_ID = item;
                        objCIAMarks.CLASS_ID = sClassId;
                        objCIAMarks.COMPONENT_ID = sComponentId;
                        //var select = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(objCIAMarks, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCoursesByStudent), sAcademicYear).DataSource.Data;
                        //var sCourseId = string.Join(",", select.Select(o => o.COURSE_ID).ToArray());
                        //Sql = SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCIAMarkByStudentandCourse).Replace(Common.Delimiter.QUS + Common.CP_CLASS_COURSE_2017.COURSE_ID, sCourseId);
                        Sql = SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCIAMarkByStudentandCourse).Replace(Common.Delimiter.QUS + "COMPONENT_ID", sComponentId);
                        LiCIAMarks = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(objCIAMarks, Sql, sAcademicYear).DataSource.Data;
                        if (LiCIAMarks != null && LiCIAMarks.Count > 0)
                        {
                            if (count == 0)
                            {
                                LiCIAMarks2 = LiCIAMarks;
                                objViewModel.liCIA_Marks_Info = LiCIAMarks2;
                            }
                            else
                            {
                                objViewModel.liCIA_Marks_Info = objViewModel.liCIA_Marks_Info.Concat(LiCIAMarks).ToList();
                            }
                        }
                        count++;
                    }
                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("BindIndividualCIAReport", "StudentController", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("BindIndividualCIAReport", "StudentController", Ex.Message);
                    }
                }
            }
            else
                return RedirectToAction("ErrorMessage", "Error");

            return View(objViewModel);
        }
