        #region Student Semester Mark And Course
        public ActionResult StudentSemesterMarkAndCourse()
        {
            StudentViewModel objViewModel = new StudentViewModel();
            StudentCourse objModel = new StudentCourse();
            List<StudentCourse> liStudentCourse = new List<StudentCourse>();
            List<StudentCourse> liStudentCourse2 = new List<StudentCourse>();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                string sStudentId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty; ;
                try
                {
                    objViewModel.liStudentList = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new STU_CLASS { STUDENT_ID = sStudentId }, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAcademicYearByStudent)).DataSource.Data;
                    foreach (var items in objViewModel.liStudentList)
                    {
                        objModel.STUDENT_ID = sStudentId;
                        objModel.ACADEMIC_YEAR = items.ACADEMIC_YEAR.ToString();
                        var Studentlist = (List<StudentCourse>)CMSHandler.FetchData<StudentCourse>(objModel, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentAllCoursesByStudentIdAndAcademicYear)).DataSource.Data;
                        var SemesterMark = (from s in Studentlist where s.TOTAL != null && s.TOTAL != "" select s).ToList();
                        if (Studentlist != null && Studentlist.Count > 0)
                        {
                            if (SemesterMark != null && SemesterMark.Count > 0)
                            {
                                liStudentCourse = (liStudentCourse != null && liStudentCourse.Count > 0) ? liStudentCourse.Concat(SemesterMark).ToList() : SemesterMark;
                            }
                            Studentlist.RemoveAll(o => o.IS_COMPULSORY == "0");
                            if (liStudentCourse2 != null && liStudentCourse2.Count > 0)
                            {
                                foreach (var dataitems in liStudentCourse2)
                                {
                                    Studentlist.RemoveAll(O => O.COURSE_ID == dataitems.COURSE_ID);
                                }
                            }
                            liStudentCourse2 = (liStudentCourse2 != null && liStudentCourse2.Count > 0) ? liStudentCourse2.Concat(Studentlist).ToList() : Studentlist;
                        }
                    }
                    foreach (var item in liStudentCourse)
                    {
                        liStudentCourse2.RemoveAll(O => O.COURSE_ID == item.COURSE_ID);
                    }

                    objViewModel.LiStudentCourseInfo = liStudentCourse.Concat(liStudentCourse2).ToList();
                    objViewModel.LiStudentCourseInfo.OrderBy(o => o.SEMESTER_ID).ThenBy(o => o.ACADEMIC_YEAR).ThenBy(o => o.COURSE_ID);
                    //objViewModel.LiStudentCourseInfo.OrderBy(o => o.ACADEMIC_YEAR);
                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("StudentCourseInfo", "StudentController", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("StudentCourseInfo", "StudentController", Ex.Message);
                    }
                }
            }
            else
                return RedirectToAction("ErrorMessage", "Error");

            return View(objViewModel);
        }
