        [HttpPost]
        public JsonResult GetCoursesForCertWithSem(string sAcademicYear, string sSemesterTypeId)
        {
            var ObjJsonData = new JsonResultData();
            try
            {
                string userId = Session[Common.SESSION_VARIABLES.USER_ID]?.ToString() ?? "";
                if (!string.IsNullOrEmpty(userId))
                {
                    string sSemesterId = string.Empty;
                    if (sSemesterTypeId == "1")
                    {
                        sSemesterId = "1,3,5";
                    }
                    else if (sSemesterTypeId == "2")
                    {
                        sSemesterId = "2,4,6";
                    }
                    else if (sSemesterTypeId == "3")
                    {
                        sSemesterId = "1";
                    }

                    var ObjModel = new CourseWiseStaffList();
                    ObjModel.STUDENT_ID = userId;
                    string sSQL1 = SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchClassIDByStudentId).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemesterId);
                    var fetchClass = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, sSQL1, sAcademicYear).DataSource.Data;
                    if (fetchClass != null && fetchClass.Count > 0)
                    {

                        ObjModel.CLASS_ID = fetchClass.FirstOrDefault().CLASS_ID;
                    }

                    ObjModel.SEMESTER_TYPE_ID = sSemesterTypeId;
                    ObjModel.SEMESTER_ID = sSemesterId;

                    // Fetch Regular Courses
                    string sSQL = SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourseByClassIdAndSemesterId).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemesterId);
                    ObjJsonData.sResult = "<option value='0'> -- Select -- </option>";
                    // Fetch Optional Courses
                    var optionalCourses = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCourseByOptionalClassId), sAcademicYear).DataSource.Data;
                    if (optionalCourses != null && optionalCourses.Count > 0)
                    {
                        foreach (var item in optionalCourses)
                        {
                            ObjJsonData.sResult += "<option value='" + item.COURSE_ROOT_ID + "' cms-sSemesterId='" + item.SEMESTER_ID + "'>( " + item.COURSE_CODE + " ) - " + item.COURSE_TITLE + "</option>";
                        }
                        ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                    }
                    var liCourseInfo = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, sSQL, sAcademicYear).DataSource.Data;

                    if (liCourseInfo != null && liCourseInfo.Count > 0)
                    {
                        foreach (var item in liCourseInfo)
                        {
                            ObjJsonData.sResult += "<option value='" + item.COURSE_ROOT_ID + "' cms-sSemesterId='" + item.SEMESTER_ID + "'>( " + item.COURSE_CODE + " ) - " + item.COURSE_TITLE + "</option>";
                        }
                        ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                        ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                    }
                    else
                    {
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotFound;
                        ObjJsonData.Message = "Session expired. Please login again.";
                    }
                    if (optionalCourses == null && liCourseInfo == null)
                    {
                        ObjJsonData.Message = Common.ErrorMessage.NotFound;
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                    }
                }
            }
            catch (Exception ex)
            {
                ObjJsonData.ErrorCode = Common.ErrorCode.InternalServerError;
                ObjJsonData.Message = ex.Message;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

