        public ActionResult ViewCertificate(string sSettingId, string sAcademicYear, string sCourseId, string sMark, string sTotal)
        {
            try
            {
                string sStudentId = Session[Common.SESSION_VARIABLES.USER_ID]?.ToString() ?? "";
                string sClassId = Session[Common.SESSION_VARIABLES.CLASS_ID]?.ToString() ?? "";

                // Fetch Student Info
                var dtStudent = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new ListStudents { STUDENT_ID = sStudentId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentInfoForReport), sAcademicYear).DataSource.Data;
                if (dtStudent != null && dtStudent.Count > 0)
                {
                    ViewBag.StudentName = dtStudent[0].FIRST_NAME;
                    ViewBag.RollNo = dtStudent[0].ROLL_NO;
                    ViewBag.ClassName = dtStudent[0].CLASS_NAME;
                    ViewBag.Department = dtStudent[0].DEPARTMENT;
                    ViewBag.Photo = (Common.URLPages.STUDENT_IMGAE_PATH + dtStudent[0].STUDENT_ID + ".jpg").Replace("\\", "/");
                }
                var ObjModel = new CourseWiseStaffList();
                ObjModel.STUDENT_ID = sStudentId;
                string sSQL1 = SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchClassIDByStudentId);
                var fetchClass = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(ObjModel, sSQL1, sAcademicYear).DataSource.Data;
                if (fetchClass != null && fetchClass.Count > 0)
                {

                    ObjModel.CLASS_ID = fetchClass.FirstOrDefault().CLASS_ID;
                }
                // Fetch Course Info
                var dtCourse = (List<CIA_COURSE_AND_CLASS_INFO>)CMSHandler.FetchData<CIA_COURSE_AND_CLASS_INFO>(new CIA_COURSE_AND_CLASS_INFO { COURSE_ID = sCourseId, CLASS_ID = ObjModel.CLASS_ID }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseInfoByCourseId), sAcademicYear).DataSource.Data;
                if (dtCourse != null && dtCourse.Count > 0)
                {
                    ViewBag.CourseTitle = dtCourse[0].COURSE_TITLE;
                    ViewBag.CourseCode = dtCourse[0].COURSE_CODE;
                }

                ViewBag.Marks = sMark;
                ViewBag.TotalMarks = sTotal;

                // Fetch Quiz Setting Name
                var dtSetting = (List<QUIZ_SETTING>)CMSHandler.FetchData<QUIZ_SETTING>(new QUIZ_SETTING { SETTING_ID = sSettingId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchQuizSettingById)).DataSource.Data;
                if (dtSetting != null && dtSetting.Count > 0)
                {
                    ViewBag.QuizName = dtSetting[0].SETTING_NAME;
                }

                ViewBag.Date = DateTime.Now.ToString("dd-MM-yyyy");

                return View();
            }
            catch (Exception ex)
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
        }
