            string sSql = string.Empty;
            string Sql = string.Empty;
            string sFieldalias = string.Empty;
            string AcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            if (!string.IsNullOrEmpty(AcademicYear))
            {
                try
                {
                    sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentReportByFields).Replace(Common.Delimiter.QUS + Common.STU_REPORT_FIELDS.FIELD_ID, sFields);
                    var StudentReportFields = (List<STU_REPORT_FIELDS>)CMSHandler.FetchData<STU_REPORT_FIELDS>(null, sSql).DataSource.Data;
                    if (StudentReportFields != null && StudentReportFields.Count > 0)
                    {
                        sFieldalias = string.Join(",", StudentReportFields.Select(s => s.FIELD_ALIAS).ToArray());
                        Sql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentReportByForOffice).Replace(Common.Delimiter.QUS + Common.STU_REPORT_FIELDS.FIELD_ID, sFields);
                        objViewModel.LiStudentReportForOffice = (List<STU_REPORT_FOR_OFFICE>)CMSHandler.FetchData<STU_REPORT_FOR_OFFICE>(null, Sql, AcademicYear).DataSource.Data;
                    }
