        public JsonResult SaveAdmissionRegister(string sJsonsave)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<STU_TRANSFER_CERTIFICATE>(sJsonsave);
                    Result.ADMISSION_DATE = CommonMethods.ConvertdatetoyearFromat(Result.ADMISSION_DATE);
                    Result.DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.DATE_OF_BIRTH);
                    Result.TC_APPLIED_DATE = CommonMethods.ConvertdatetoyearFromat(Result.TC_APPLIED_DATE);
                    Result.TC_GIVEN_DATE = CommonMethods.ConvertdatetoyearFromat(Result.TC_GIVEN_DATE);
                    Result.LEAVING_DATE = CommonMethods.ConvertdatetoyearFromat(Result.LEAVING_DATE);

