                    //if (IsExist!=null && IsExist.Count>0)
                    if (!string.IsNullOrEmpty(Result.CERTIFICATE_ID))
                    {
                        //Result.CERTIFICATE_ID = IsExist.FirstOrDefault().CERTIFICATE_ID;
                        var sUpdateTransferCertificate = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateAdmissionRegister), sAcademicYear);
