                        dv.Clear();
                        dv.Add(Common.STU_PERSONAL_INFO.STUDENT_ID, Result.STUDENT_ID, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.FIRST_NAME, Result.FIRST_NAME, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.FATHER_NAME, Result.FATHER_NAME, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.GUARDIAN_NAME, Result.GUARDIAN_NAME, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.NATIONALITY, Result.NATIONALITY_ID, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.RELIGION, Result.RELIGION_ID, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.CASTE, Result.CASTE, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.COMMUNITY, Result.COMMUNITY_ID, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.GENDER, Result.GENDER_ID, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.DATE_OF_BIRTH, Result.DATE_OF_BIRTH, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.IDENTIFICATION_MARK1, Result.IDENTIFICATION_MARK1, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.IDENTIFICATION_MARK2, Result.IDENTIFICATION_MARK2, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.ADMISSION_DATE, Result.ADMISSION_DATE, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.ADMITTED_CLASS, Result.ADMITTED_CLASS, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.LEAVING_CLASS, Result.LEAVING_CLASS, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.LEAVIN_GDATE, Result.LEAVING_DATE, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.TC_APPLIED_DATE, Result.TC_APPLIED_DATE, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.TC_GIVEN_DATE, Result.TC_GIVEN_DATE, EnumCommand.DataType.String);
                        dv.Add(Common.STU_PERSONAL_INFO.CONDUCT, Result.CONDUCT, EnumCommand.DataType.String);
                        using (StudentViewModel objViewModel = new StudentViewModel())
                        {
                            resultArgs = objViewModel.UpdatepersonalInfoForTC(dv);
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("StudentController", "SaveAdmissionRegister", ex.Message);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            ObjJsonData.Message = (ObjJsonData.Message != null) ? ObjJsonData.Message : "No Changes Made !";
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

