        // Fetch Answer By Question Id ...
        public JsonResult FetchAnswerByQuestionId(string sExamQuestionsId, string sStudentId, string sAcademicYear)
        {
            var ObjJsonData = new JsonResultData();
            try
            {
                var liFetchAnswer = (List<ONLINE_EXAM_ANSWERS>)CMSHandler.FetchData<ONLINE_EXAM_ANSWERS>(new ONLINE_EXAM_ANSWERS() { QUESTION_ID = sExamQuestionsId, STUDENT_ID = sStudentId },
                        SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAnswersByQuestionId), sAcademicYear).DataSource.Data;
                if (liFetchAnswer != null && liFetchAnswer.Count > 0)
                {
                    string Answer = liFetchAnswer.FirstOrDefault().ANSWER;
                    byte[] bytes = Convert.FromBase64String(Answer);
                    ObjJsonData.sResult = Encoding.UTF8.GetString(bytes);
                    ObjJsonData.ErrorCode = liFetchAnswer.FirstOrDefault().EXAM_ANSWER_ID;
                    return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("StudentController", "FetchAnswerByQuestionId", ex.Message);
                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        // Save Online Exam Answers ,..
        public JsonResult SaveOnlineExamAnswers(string sJsonSaveExamAnswers)
        {
            var ObjJsonData = new JsonResultData();
            try
            {
                var Result = JsonConvert.DeserializeObject<ONLINE_EXAM_ANSWERS>(sJsonSaveExamAnswers);
                if (!string.IsNullOrEmpty(Result.ANSWER))
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteSemesterMark(Result.ANSWER, Result.STUDENT_ID, Result.QUESTION_ID, Result.EXAM_SETTING_ID);
                    }
                    if (!string.IsNullOrEmpty(Result.EXAM_ANSWER_ID))
                    {
                        var sUpdate = CMSHandler.SaveOrUpdate(Result, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.UpdateOnlineExamAnswers));
                        ObjJsonData.Message = (sUpdate.Success) ? "Your Answers Are Submitted Successfully !" : "Failed To Submit Answers !";
                    }
                    else
                    {
                        var sInsert = CMSHandler.SaveOrUpdate(Result, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOnlineExamAnswers), "", true);
                        ObjJsonData.Message = (sInsert.Success) ? "Your Answers Are Submitted Successfully !" : "Failed To Submit Answers !";
                        ObjJsonData.ErrorCode = "1";
                        ObjJsonData.sResult = sInsert.RowUniqueId.ToString();
                    }
                }
                else
                {
                    ObjJsonData.Message = "No Changes Made ! Please Check Your Input !";
                }

            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("StudentController", "SaveOnlineExamAnswers", ex.Message);
                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        // Submit Online Exam When Finish ,,..
        public JsonResult SubmitOnlineExam(string sJsonSubmitExam)
        {
            var ObjJsonData = new JsonResultData();
            try
            {
                var Result = JsonConvert.DeserializeObject<ONLINE_EXAM_SUBMITTED>(sJsonSubmitExam);
                var sSaveExamDone = CMSHandler.SaveOrUpdate(Result, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.SaveOnlineExamSubmittion));
                ObjJsonData.Message = (sSaveExamDone.Success) ? "You Are Completed ToDay Exam ! \n All The Best For Next Exam !" : "Sorry Something Went Wrong ! Please Meet Incharge !";
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("Student", "SubmitOnlineExam", ex.Message);
                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
