        /// <summary>
        /// Bind Programme Wise caste Report
        /// </summary>
        /// <param name="sAcademic"></param>
        /// <param name="sShift"></param>
        /// <param name="sProgrammeMode"></param>
        /// <param name="sProgramme"></param>
        /// <param name="sCaste"></param>
        /// <returns></returns>
        public ActionResult BindProgrammeWiseCasteReportDetails(string sAcademic, string sShift, string sProgrammeMode, string sProgramme, string sCaste)
        {
            StudentViewModel stuViewModel = new StudentViewModel();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null && sAcademic != null && sShift != null && sProgrammeMode != null && sProgramme != null && sCaste != null)
            {
                stuViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;

                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                //FETCH PROGRAMME BY PROGRAMME MODE AND SHIFT
                string sSql = SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchProgrammeByProgrammeGroupId);
                var liProgramme = (List<REPORT_FIELDS_FORCASTEWISE>)CMSHandler.FetchData<REPORT_FIELDS_FORCASTEWISE>(null, sSql.Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.SHIFT, sShift).Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.PROGRAMME_MODE, sProgrammeMode)
                .Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.ACADEMIC_YEAR, sAcademic).Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.PROGRAMME_GROUP_ID, sProgramme)).DataSource.Data;
                stuViewModel.liProgramme = liProgramme;

                //FETCH CASTE BY PROGRAMME WISE 
                string sSqlCaste = SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCasteByProgrammeGroup);
                var liCaste = (List<REPORT_FIELDS_FORCASTEWISE>)CMSHandler.FetchData<REPORT_FIELDS_FORCASTEWISE>(null, sSqlCaste.Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.SHIFT, sShift).Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.PROGRAMME_MODE, sProgrammeMode)
                .Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.ACADEMIC_YEAR, sAcademic).Replace(Common.Delimiter.QUS + Common.REPORT_FIELDS_FORCASTEWISE.COMMUNITY, sCaste)).DataSource.Data;
                stuViewModel.liCaste = liCaste;

                //TOTAL CASTE
                string sSqlCom = SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCasteByCasteId);
