        #region BatchWise Cp Report
        public ActionResult BatchWiseCpReport()
        {
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var objModel = new STU_CLASS() { STUDENT_ID = sUserId };

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                var liSemsterids = (List<ACADEMIC_SEMESTER>)CMSHandler.FetchData<ACADEMIC_SEMESTER>(new STU_CLASS() { STUDENT_ID = sUserId },
                            StudentSQL.GetStudentSQL(StudentSQLCommads.FetchSemesteridsByStudentId), sAcademicYear).DataSource.Data;
                if (liSemsterids != null && liSemsterids.Count > 0)
                {
                    string sSemsterids = liSemsterids.FirstOrDefault().SEMESTER;
                    string sSQLRegularCourse = string.Empty;
                    string sSQLOptionalCourse = string.Empty;
                    sSQLRegularCourse = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAllCourseFromCoursePatternByStudentId).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemsterids);
                    sSQLOptionalCourse = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchOptionCourseByStudentId).Replace(Common.Delimiter.QUS + Common.CP_COURSE_ROOT_2017.SEMESTER_ID, sSemsterids);
                    int nBeginYear = Convert.ToInt32(liSemsterids.FirstOrDefault().BEGIN_YEAR);
                    int nEndYear = Convert.ToInt32(liSemsterids.FirstOrDefault().EXPIRED_YEAR);
                    var liCourse = new List<EXAM_REGISTRATION>();
                    for (int i = nBeginYear; i < nEndYear; i++)
                    {
                        string year = i.ToString();
                        var liRegularCourse = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objModel, sSQLRegularCourse, year).DataSource.Data;
                        var liOptionalCourse = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objModel, sSQLOptionalCourse, year).DataSource.Data;
                        if (liRegularCourse != null && liRegularCourse.Count > 0)
                        {
                            liCourse = (liCourse != null && liCourse.Count > 0) ? liCourse.Concat(liRegularCourse).ToList() : liRegularCourse;
                        }
                        if (liOptionalCourse != null && liOptionalCourse.Count > 0)
                        {

                            foreach (var courseitem in liOptionalCourse)
                            {
                                var isExists = liRegularCourse.Where(o => o.COURSE_ID == courseitem.COURSE_ID).ToList();
                                if (isExists != null && isExists.Count > 0)
                                {
                                    liRegularCourse.RemoveAll(o => o.COURSE_STRUCTURE_ID == isExists.FirstOrDefault().COURSE_STRUCTURE_ID);
                                    courseitem.COURSE_STRUCTURE_ID = isExists.FirstOrDefault().COURSE_STRUCTURE_ID;
                                    liCourse.Add(courseitem);
                                }
                            }
                        }
                    }

                    objViewModel.liExamRegistrationList = liCourse.OrderBy(o => o.SEMESTER_ID).ToList();
                }
            }
            else
                return RedirectToAction("ErrorMessage", "Error");
            return View(objViewModel);
        }
