        public JsonResult SaveConvocationApplication(string ConvocationApplication, string sBaseImage, string sExtension, string sRollno)
        {
            StudentViewModel objViewModel = new StudentViewModel();
            FEE_STUDENT_ACCOUNT Objmodel = new FEE_STUDENT_ACCOUNT();
            string sSql = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<CONVOCATION_APPLICATION_REGISTER>(ConvocationApplication);
                    Result.STUDENT_ID = sUserId;
                    var IsExist = (List<CONVOCATION_APPLICATION_REGISTER>)CMSHandler.FetchData<CONVOCATION_APPLICATION_REGISTER>(new StudentInfo() { STUDENTID = sUserId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.CheckIsConvacationRegisterExist)).DataSource.Data;
                    if (IsExist == null)
                    {
                        if (!string.IsNullOrEmpty(Result.STUDENT_ID))
                        {
                            Result.DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.DATE_OF_BIRTH);
                            var InsertConcocation = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.InsertConvocationApplication), sAcademicYear);
                            var Dep = (List<cp_Department_2017>)CMSHandler.FetchData<cp_Department_2017>(new StudentInfo() { STUDENTID = sUserId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchDepartmentBySudentId)).DataSource.Data;
                            if (Dep != null && Dep.Count > 0)
                                saveImages(sBaseImage, sExtension, Dep.FirstOrDefault().DEPARTMENT, sRollno);
                            if (InsertConcocation.Success)
                            {
                                var FetchFrequency = (List<SUP_FEE_FREQUENCY>)CMSHandler.FetchData<SUP_FEE_FREQUENCY>(new SUP_FEE_FREQUENCY { FEE_MODE = Common.FrequencyType.ConvocationFee }, SQL.Fee.FeeSQL.GetFeeSQL(FeeSQLCommands.FetchFrequencyIdByFeeModeAndActiveSemester), sAcademicYear).DataSource.Data;
                                var Academicyear = (List<AcademicBatches>)CMSHandler.FetchData<AcademicBatches>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = sUserId }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAcademicYearstudentId)).DataSource.Data;
                                var FetchStudentProgrammeandclassyear = (List<FEE_STRUCTURE>)CMSHandler.FetchData<FEE_STRUCTURE>(new StudentInfo() { STUDENTID = sUserId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchProgrammeandClassyear), Academicyear.FirstOrDefault().ACADEMIC_YEAR_ID).DataSource.Data;
                                sSql = SQL.Fee.FeeSQL.GetFeeSQL(FeeSQLCommands.SelectInsertForFeeStudentAccountByFrequencyAndProgrammeAndClassyear).Replace(Common.Delimiter.QUS + Common.STU_CLASS.STUDENT_ID, sUserId);
                                var SaveStudentAccount = CMSHandler.SaveOrUpdate(new FEE_STRUCTURE { CLASS_YEAR_ID = FetchStudentProgrammeandclassyear.FirstOrDefault().CLASS_YEAR_ID, PROGRAMME = FetchStudentProgrammeandclassyear.FirstOrDefault().PROGRAMME, FREQUENCY = FetchFrequency.FirstOrDefault().FREQUENCY_ID }, sSql, sAcademicYear);
                                var UnSafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.UnSafeUpdateMode), sAcademicYear);
                                var SaveUpdateStuAddress = CMSHandler.SaveOrUpdate(Result, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuAddressByConvocationDetails), sAcademicYear);
                                var SafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.SafeUpdateMode), sAcademicYear);
                                var SaveStuPersonl = CMSHandler.SaveOrUpdate(Result, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuPersonalByConvocationDetails), sAcademicYear);
                            }
                            ObjJsonData.Message = (InsertConcocation.Success) ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                        }
                        else
                        {
                            var InsertUgcCourseType = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateConvocationApplication), sAcademicYear);
                            if (InsertUgcCourseType.Success)
                            {

                            }
                            ObjJsonData.Message = (InsertUgcCourseType.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        }
                    }
                    else
                    {

                        Result.CONVOC_APP_REGISTER_ID = IsExist.FirstOrDefault().CONVOC_APP_REGISTER_ID;
                        Result.DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.DATE_OF_BIRTH);
                        var Dep = (List<cp_Department_2017>)CMSHandler.FetchData<cp_Department_2017>(new StudentInfo() { STUDENTID = sUserId }, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchDepartmentBySudentId)).DataSource.Data;
                        if (Dep != null && Dep.Count > 0)
                            saveImages(sBaseImage, sExtension, Dep.FirstOrDefault().DEPARTMENT, sRollno);
                        var InsertUgcCourseType = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateConvocationApplication), sAcademicYear);
                        var UnSafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.UnSafeUpdateMode), sAcademicYear);
                        var SaveUpdateStuAddress = CMSHandler.SaveOrUpdate(Result, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuAddressByConvocationDetails), sAcademicYear);
                        var SafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.SafeUpdateMode), sAcademicYear);
                        var SaveStuPersonl = CMSHandler.SaveOrUpdate(Result, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuPersonalByConvocationDetails), sAcademicYear);
                        ObjJsonData.Message = (InsertUgcCourseType.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                    }
                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("SaveConvocationApplication", "StudentController", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("SaveConvocationApplication", "StudentController", Ex.Message);
                    }
                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
