        /// <summary>
        /// student registration card 
        /// </summary>
        /// <returns></returns>
        public ActionResult StudentRegistrationCard()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            StudentViewModel objViewModel = new StudentViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    string _sDirectorypath = string.Empty;
                    //fetch 
                    GET_ACTIVE_SEMESTER_BATCH objActiveSemester = new GET_ACTIVE_SEMESTER_BATCH();
                    objActiveSemester.STUDENT_ID = sUserId;

                    var liRegularCourses = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                         StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCurrentSemRegularPaperByStudentId), sAcademicYear).DataSource.Data;
                    var liOptionalCourses = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(objActiveSemester,
                          StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCurrentSemOptionalPaperByStudentId), sAcademicYear).DataSource.Data;


                    //GET class inchrage staff
                    var liClassIncharge = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_PERSONAL_INFO() { STUDENT_ID = sUserId },
                         StudentSQL.GetStudentSQL(StudentSQLCommads.FetchClassTeacherByStudentId), sAcademicYear).DataSource.Data;


                    //GET hod
                    var liHod = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_PERSONAL_INFO() { STUDENT_ID = sUserId },
                         StudentSQL.GetStudentSQL(StudentSQLCommads.FetchHodByStudentId), sAcademicYear).DataSource.Data;



                    // Fetch College Details ....
                    objViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null,
                        ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), sAcademicYear).DataSource.Data;


                    //GET current date
                    var liCurDate = (List<CALENDER_2017>)CMSHandler.FetchData<CALENDER_2017>(null,
                         StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCurrentDate), sAcademicYear).DataSource.Data;



                    // var liTemp = liRegularCourses.Where(o => o.COURSE_STRUCTURE_ID == "579").ToList();
                    // Loop Optional Papers  To Remove Unnecessary Courses...
                    if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                    {
                        foreach (var item in liOptionalCourses)
                        {
                            var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                            if (IsExist != null && IsExist.Count > 0)
                            {
                                liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                liRegularCourses.Add(item);
                            }
                        }

                        //this is regular courses and optional courses 
                        if (liRegularCourses != null && liRegularCourses.Count > 0)
                        {
                            //getting the staff signs from this folder
                            _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.STAFF_SIGN_PATH;

                            DirectoryInfo d = new DirectoryInfo(_sDirectorypath);//Assuming Test is your Folder
                            FileInfo[] Files = d.GetFiles(); //Getting sign files
                            foreach (var item in liRegularCourses)
                            {
                                // get Image By staff_code
                                if (!string.IsNullOrEmpty(item.STAFF_CODE))
                                {
                                    var IsExist = Files.Where(o => o.Name.Split('.').FirstOrDefault() == item.STAFF_CODE).ToList();
                                    if (IsExist != null && IsExist.Count > 0)
                                    {
                                        var img = IsExist.FirstOrDefault().Name.Split('.');
                                        string sSavePath = "\\" + Common.URLPages.STAFF_SIGN_PATH + "\\" + img[0] + "." + img[1];

                                        liRegularCourses.Where(x => x.STAFF_CODE == item.STAFF_CODE).ToList().ForEach(x => x.SIGN_PATH = sSavePath);
                                    }

                                }

                            }
                        }
                    }
                    else
                    {
                        //this is only for regular courses

                        if (liRegularCourses != null && liRegularCourses.Count > 0)
                        {

                            //getting the staff signs from this folder
                            _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.STAFF_SIGN_PATH;
                            DirectoryInfo d = new DirectoryInfo(_sDirectorypath);//Assuming Test is your Folder
                            FileInfo[] Files = d.GetFiles(); //Getting Text files
                            foreach (var item in liRegularCourses)
                            {
                                if (!string.IsNullOrEmpty(item.STAFF_CODE))
                                {

                                    // var sImage = file.Name.Split('.');
                                    // get Image By staff_code
                                    var IsExist = Files.Where(o => o.Name.Split('.').FirstOrDefault() == item.STAFF_CODE).ToList();
                                    if (IsExist != null && IsExist.Count > 0)
                                    {
                                        var img = IsExist.FirstOrDefault().Name.Split('.');
                                        string sSavePath = "\\" + Common.URLPages.STAFF_SIGN_PATH + "\\" + img[0] + "." + img[1];
                                        liRegularCourses.Where(x => x.STAFF_CODE == item.STAFF_CODE).ToList().ForEach(x => x.SIGN_PATH = sSavePath);
                                    }

                                }

                            }
                        }
                    }
                    objViewModel.liExamRegistrationList = liRegularCourses;


                    if (liClassIncharge != null && liClassIncharge.Count > 0)
                    {
                        //getting the staff signs from this folder
                        _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.STAFF_SIGN_PATH;
                        DirectoryInfo d = new DirectoryInfo(_sDirectorypath);//Assuming Test is your Folder
                        FileInfo[] Files = d.GetFiles(); //Getting sign files

                        // var sImage = file.Name.Split('.');
                        // get Image By staff_code
                        var IsExist = Files.Where(o => o.Name.Split('.').FirstOrDefault() == liClassIncharge.FirstOrDefault().STAFF_CODE).ToList();

                        if (IsExist != null && IsExist.Count > 0)
                        {
                            var img = IsExist.FirstOrDefault().Name.Split('.');
                            string sSavePath = "\\" + Common.URLPages.STAFF_SIGN_PATH + "\\" + img[0] + "." + img[1];
                            //liRegularCourses.Where(x => x.STAFF_CODE == liClassIncharge.FirstOrDefault().STAFF_CODE).ToList().ForEach(x => x.CS_SIGN_PATH = sSavePath);
                            objViewModel.liExamRegistrationList.FirstOrDefault().CS_SIGN_PATH = sSavePath;
                        }


                    }
                    if (liHod != null && liHod.Count > 0)
                    {
                        //getting the staff signs from this folder
                        _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.STAFF_SIGN_PATH;
                        DirectoryInfo d = new DirectoryInfo(_sDirectorypath);//Assuming Test is your Folder
                        FileInfo[] Files = d.GetFiles(); //Getting sign files

                        // var sImage = file.Name.Split('.');
                        // get Image By staff_code
                        var IsExist = Files.Where(o => o.Name.Split('.').FirstOrDefault() == liHod.FirstOrDefault().STAFF_CODE).ToList();

                        if (IsExist != null && IsExist.Count > 0)
                        {
                            var img = IsExist.FirstOrDefault().Name.Split('.');
                            string sSavePath = "\\" + Common.URLPages.STAFF_SIGN_PATH + "\\" + img[0] + "." + img[1];
                            // liRegularCourses.Where(x => x.STAFF_CODE == liHod.FirstOrDefault().STAFF_CODE).ToList().ForEach(x => x.HOD_SIGN_PATH = sSavePath);
                            objViewModel.liExamRegistrationList.FirstOrDefault().HOD_SIGN_PATH = sSavePath;
                        }
                    }


                    if (liCurDate != null && liCurDate.Count > 0)
                    {
                        objViewModel.liExamRegistrationList.FirstOrDefault().CUR_DATE = liCurDate.FirstOrDefault().DAY_ORDER_DATE;
                    }


                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("StudentController", "StudentRegistrationCard", ex.Message);
                    }
                }


            }
            return View(objViewModel);
        }
