        #region Certificate Apply
        public ActionResult ListStudentCertificateApplied()
        {
            string sOption = string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            StudentViewModel objViewModel = new StudentViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    //Fetch Certificate Applied
                    objViewModel.licertificateapply = (List<STU_CERTIFICATE_APPLY>)CMSHandler.FetchData<STU_CERTIFICATE_APPLY>(new STU_PERSONAL_INFO() { STUDENT_ID = sUserId },
                         StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCertificateApplied), sAcademicYear).DataSource.Data;
                    //Fetch Progammemode and shift
                    var Studentinfo = (List<CP_PROGRAMME_GROUP>)CMSHandler.FetchData<CP_PROGRAMME_GROUP>(new STU_PERSONAL_INFO() { STUDENT_ID = sUserId },
                       SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchProgrammmodeandShift), sAcademicYear).DataSource.Data;
                    if (Studentinfo != null && Studentinfo.Count > 0)
                    {
                        var liCertificate = (List<SUP_HEAD>)CMSHandler.FetchData<SUP_HEAD>(new FEE_FREQUENCY_FEE_MODE() { FEE_MODE = Common.FrequencyType.Certificate, PROGRAMME_MODE = Studentinfo.FirstOrDefault().PROGRAMME_MODE, SHIFT = Studentinfo.FirstOrDefault().SHIFT },
                             StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCertificateForDDL), sAcademicYear).DataSource.Data;

                        if (liCertificate != null && liCertificate.Count > 0)
                        {
                            foreach (var item in liCertificate)
                            {
                                sOption += "<option value=" + item.HEAD_ID + " mainheadid=" + item.FEE_MAIN_HEAD_ID + ">" + item.HEAD + "</option>";
                            }
                            //objViewModel.LeaveType = new SelectList(liCertificate, Common.SUP_HEAD.HEAD_ID, Common.SUP_LEAVE_TYPE.LEAVE_TYPE);
                        }
                        objViewModel.sOption = sOption;
                    }

                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("StudentController", "ListStudentCertificateApplied", ex.Message);
                    }
                }


            }
            return View(objViewModel);
        }
        public JsonResult SaveorUpdateCertificateApply(string sJsonData)
        {
            string sSQL = string.Empty;
            if (!string.IsNullOrEmpty(sJsonData))
            {
                try
                {
                    string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                    string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
                    var Studnetcertificateapply = JsonConvert.DeserializeObject<STU_CERTIFICATE_APPLY>(sJsonData);
                    if (Studnetcertificateapply != null)
                    {
                        Studnetcertificateapply.STUDENT_ID = sUserId;
                        Studnetcertificateapply.ACADEMIC_YEAR = sAcademicYear;

                        // check if exist 
                        var isExist = (List<STU_CERTIFICATE_APPLY>)CMSHandler.FetchData<STU_CERTIFICATE_APPLY>(new STU_CERTIFICATE_APPLY() { STUDENT_ID = sUserId, FEE_MAINHEAD_ID = Studnetcertificateapply.FEE_MAINHEAD_ID },
                         StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCertificateByStudentHead), sAcademicYear).DataSource.Data;

                        if (isExist != null && isExist.Count > 0)
                        {
                            ObjJsonData.Message = Common.Messages.RecordsExistAlready;
                            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                        }

                        var ResultArg = CMSHandler.SaveOrUpdate(Studnetcertificateapply, StudentSQL.GetStudentSQL((!string.IsNullOrEmpty(Studnetcertificateapply.APPLY_ID) ? StudentSQLCommads.UpdateCertificateapply : StudentSQLCommads.SaveCertificateapply)));
                        if (ResultArg.Success)
                        {

                            ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                        }

                        else
                            ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Student", "SaveorUpdateCertificateApply", ex.Message);
                    }

                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

