        public ActionResult BindCertificateRequestedStudent(string sProgrammeIds)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sSQL = string.Empty;
            var ObjViewModel = new StudentViewModel();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    sSQL = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCertificateRequestedList).Replace(Common.Delimiter.QUS + Common.CP_PROGRAMME_2017.PROGRAMME_GROUP_ID, sProgrammeIds);
                    ObjViewModel.licertificateapply = (List<STU_CERTIFICATE_APPLY>)CMSHandler.FetchData<STU_CERTIFICATE_APPLY>(null, sSQL, sAcademicYear).DataSource.Data;

                    var listatus = (List<SUP_STATUS>)CMSHandler.FetchData<SUP_STATUS>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupStatus), sAcademicYear).DataSource.Data;
                    if (listatus != null && listatus.Count > 0)
                    {
                        ObjViewModel.Status = new SelectList(listatus, Common.SUP_STATUS.STATUS_ID, Common.SUP_STATUS.STATUS_NAME);
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("ExaminationController", "BindRequestedStudent", ex.Message);
                    }
                }
            }
            else
            {
                return RedirectToAction("ErrorMessage", "Error");
            }
            return View(ObjViewModel);
        }
        public JsonResult SaveorUpdateCertificaterequestedStatus(string sJsonData)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            int sSuccessCount = 0;
            int sFailedMessageCount = 0;
            if (!string.IsNullOrEmpty(sJsonData) && !string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var Result = JsonConvert.DeserializeObject<STU_JSON_FIELD>(sJsonData);
                    if (Result != null)
                    {
                        foreach (var item in Result.LiCertificateApply)
                        {
                            item.APPROVER = Session[Common.SESSION_VARIABLES.USER_ID].ToString();

                            item.APPROVED_DATE = DateTime.Now.ToString("yyyy-MM-dd");
                            var ResultArg = CMSHandler.SaveOrUpdate(item, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateCertificateRequestedStatus));
                            if (ResultArg.Success)
                            {
                                sSuccessCount++;
                                ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;

                                //Fetch Fees Structure
                                // sSQL = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCertificatefeestructure).Replace(Common.Delimiter.QUS + Common.FEE_MAIN_HEADS.FEE_MAIN_HEAD_ID, Studnetcertificateapply.FEE_MAINHEAD_ID);
                                var Feesstructure = (List<FEE_STRUCTURE>)CMSHandler.FetchData<FEE_STRUCTURE>(new STU_CERTIFICATE_APPLY() { STUDENT_ID = item.STUDENT_ID, FEE_MAINHEAD_ID = item.FEE_MAINHEAD_ID }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCertificatefeestructure), sAcademicYear).DataSource.Data;
                                if (Feesstructure != null && Feesstructure.Count > 0)
                                {
                                    foreach (var item1 in Feesstructure)
                                    {
                                        item1.STUDENT_ID = item.STUDENT_ID;
                                        item1.ACADEMIC_YEAR = sAcademicYear;
                                        resultArgs = CMSHandler.SaveOrUpdate(item1, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveFeeStudentAc), sAcademicYear);
                                    }
                                }
                            }

                            else
                            {
                                sFailedMessageCount++;
                                ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("StudentController", "SaveorUpdateCertificaterequestedStatus", ex.Message);
                    }

                }
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

        public ActionResult StudentCertificateDownload(string sApplyId)
        {
            StudentViewModel objViewModel = new StudentViewModel();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

            if (!string.IsNullOrEmpty(sApplyId))
            {
                //Fetch Certificate Applied
                var liCertificate = (List<STU_CERTIFICATE_APPLY>)CMSHandler.FetchData<STU_CERTIFICATE_APPLY>(new STU_CERTIFICATE_APPLY() { APPLY_ID = sApplyId },
                     StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCertificateAppliedById), sAcademicYear).DataSource.Data;

                if (liCertificate != null && liCertificate.Count > 0)
                {

                    switch (liCertificate.FirstOrDefault().HEAD_ID)
                    {
                        case Common.SUP_CERTIFICATE.Bonafide:

                            //
                            var liBonafideDetails = (List<STU_CERTIFICATE_APPLY>)CMSHandler.FetchData<STU_CERTIFICATE_APPLY>(new STU_CERTIFICATE_APPLY() { APPLY_ID = sApplyId },
                                StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentInfoByStudentId), sAcademicYear).DataSource.Data;
                            if (liBonafideDetails != null && liBonafideDetails.Count > 0)
                            {
                                PrintBonafideCertificate(liBonafideDetails.FirstOrDefault().FIRST_NAME,

                                    liBonafideDetails.FirstOrDefault().ACADEMIC_NAME,
                                    liBonafideDetails.FirstOrDefault().CLASS_NAME,
                                    liBonafideDetails.FirstOrDefault().FATHER_NAME,
                                    liBonafideDetails.FirstOrDefault().STUDENT_ID
                                    );
                                objViewModel.objStudent.STUDENT_ID = liBonafideDetails.FirstOrDefault().STUDENT_ID;

                            }

                            break;
                        case Common.SUP_CERTIFICATE.Attendance:

                            //



                            break;
                        case Common.SUP_CERTIFICATE.Course:

                            //



                            break;
                        case Common.SUP_CERTIFICATE.Conduct:

                            //
                            var liConductDetails = (List<STU_CERTIFICATE_APPLY>)CMSHandler.FetchData<STU_CERTIFICATE_APPLY>(new STU_CERTIFICATE_APPLY() { APPLY_ID = sApplyId },
                               StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentInfoByStudentId), sAcademicYear).DataSource.Data;
                            if (liConductDetails != null && liConductDetails.Count > 0)
                            {
                                PrintConductCertificate(liConductDetails.FirstOrDefault().FIRST_NAME,
                                    liConductDetails.FirstOrDefault().ACADEMIC_NAME,
                                    liConductDetails.FirstOrDefault().PROGRAMME_NAME,
                                    liConductDetails.FirstOrDefault().BEGIN_YEAR,
                                    liConductDetails.FirstOrDefault().END_YEAR,
                                    "GOOD",
                                    liConductDetails.FirstOrDefault().ROLL_NO,
                                    liConductDetails.FirstOrDefault().STUDENT_ID
                                    );
                                objViewModel.objStudent.STUDENT_ID = liConductDetails.FirstOrDefault().STUDENT_ID;
                            }

                            break;
                    }

                }
            }





            return View(objViewModel);
        }

