        public static void DrawDotLine(XGraphics g, int x1, int y1, int x2, int y2)
        {

            for (int i = x1; i < x2; i = i + 5)
            {
                g.DrawString(".", new XFont("Arial", 11, XFontStyle.Regular), XBrushes.Black, new XPoint(i, y1));
            }

        }

