        public ActionResult StudentMarkSheet()
        {
            StudentViewModel objViewModel = new StudentViewModel();
            SEMESTER_MARKS objModel = new SEMESTER_MARKS();
            ACADEMIC_YEAR aObjModel = new ACADEMIC_YEAR();
            string sSql = string.Empty;
            string Sql = string.Empty;
            string AcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : "";
            var lisemestermark = new List<SEMESTER_MARKS>();
            var lioverallsemestermark = new List<SEMESTER_MARKS>();
