            if (!string.IsNullOrEmpty(AcademicYear))
            {
                try
                {
                    objViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), AcademicYear).DataSource.Data;
                    var StudentInfo = (List<GET_PROGRAMME_AND_BATCH>)CMSHandler.FetchData<GET_PROGRAMME_AND_BATCH>(new GET_PROGRAMME_AND_BATCH() { STUDENT_ID = Session[Common.SESSION_VARIABLES.USER_ID].ToString() }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchAcademicInfoBystudentId), AcademicYear).DataSource.Data;
                    if (StudentInfo != null && StudentInfo.Count > 0)
                    {



                        objModel.STUDENT_ID = StudentInfo.FirstOrDefault().STUDENT_ID;
                        objModel.BATCH_ID = StudentInfo.FirstOrDefault().BATCH;
                        objModel.APPLICATION_TYPE_ID = StudentInfo.FirstOrDefault().APPTYPE_ID;
                        AcademicYear = StudentInfo.FirstOrDefault().ACADEMIC_YEAR;



                        var limarksheetapporved = (List<CEO_MARKSHEET_DISTRIBUTION>)CMSHandler.FetchData<CEO_MARKSHEET_DISTRIBUTION>(new CEO_MARKSHEET_DISTRIBUTION() { STUDENT_ID = Session[Common.SESSION_VARIABLES.USER_ID].ToString(), STATUS = Common.status.Approved }, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMarkSheetrequestapprovedByStudentId), AcademicYear).DataSource.Data;
                        if (limarksheetapporved != null && limarksheetapporved.Count > 0)
                        {
                            foreach (var item in limarksheetapporved)
                            {
                                objModel.EXAM_SETTING_ID = item.EXAM_SETTING_ID;

                                if (objModel.APPLICATION_TYPE_ID == "6")
                                {
                                    Sql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchMphillProjectByStudentId).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.STUDENT_ID, objModel.STUDENT_ID);
                                    objViewModel.LiMphillStudentProject = (List<MPHILL_STUDENT_PROJECT>)CMSHandler.FetchData<MPHILL_STUDENT_PROJECT>(objModel, Sql).DataSource.Data;
                                }
                                var ExamSetting = (List<EXAM_SETTING>)CMSHandler.FetchData<EXAM_SETTING>(objModel, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchExamSettingBySettingId), AcademicYear).DataSource.Data;
                                if (ExamSetting != null && ExamSetting.Count > 0)
                                {
                                    objModel.ACADEMIC_YEAR = ExamSetting.FirstOrDefault().ACADEMIC_YEAR;
                                    sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchIndividualSemesterMarks).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.STUDENT_ID, objModel.STUDENT_ID);
                                    var lisememark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, sSql, objModel.ACADEMIC_YEAR).DataSource.Data;
                                    //  objViewModel.liSemestermark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, sSql, objModel.ACADEMIC_YEAR).DataSource.Data;
                                    if (lisememark != null && lisememark.Count > 0)
                                    {

                                        objModel.START_DATE = lisememark.FirstOrDefault().START_DATE;
                                        lisemestermark = lisemestermark.Concat(lisememark).ToList();
                                    }
                                    //if (objViewModel.liSemestermark != null && objViewModel.liSemestermark.Count > 0)
                                    //{
                                    //    objModel.START_DATE = objViewModel.liSemestermark.FirstOrDefault().START_DATE;

                                    //}
                                }
                                var BatchExpiredYear = (List<SUP_BATCH_DURATION>)CMSHandler.FetchData<SUP_BATCH_DURATION>(objModel, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchBatchExpiredYear)).DataSource.Data;
                                if (BatchExpiredYear != null && BatchExpiredYear.Count > 0)
                                {
                                    for (int i = Convert.ToInt16(BatchExpiredYear.FirstOrDefault().BEGIN_YEAR); i < Convert.ToInt16(BatchExpiredYear.FirstOrDefault().EXPIRED_YEAR); i++)
                                    {
                                        objModel.ACADEMIC_YEAR = i.ToString();
                                        objModel.STUDENT_ID = objModel.STUDENT_ID;
                                        sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchOverAllSemesterMarks).Replace(Common.Delimiter.QUS + Common.SEMESTER_MARKS_2017.STUDENT_ID, objModel.STUDENT_ID);
                                        var SemMark = (List<SEMESTER_MARKS>)CMSHandler.FetchData<SEMESTER_MARKS>(objModel, sSql, i.ToString()).DataSource.Data;
                                        if (SemMark != null && SemMark.Count > 0)
                                        {
                                            //objViewModel.liOverAllSemestermark = (objViewModel.liOverAllSemestermark != null && objViewModel.liOverAllSemestermark.Count > 0) ? objViewModel.liOverAllSemestermark.Concat(SemMark).ToList() : SemMark;
                                            lioverallsemestermark = (SemMark != null && SemMark.Count > 0) ? lioverallsemestermark.Concat(SemMark).ToList() : SemMark;
                                        }
                                    }
                                }
                                if (lioverallsemestermark != null && lioverallsemestermark.Count > 0)
                                {
                                    lioverallsemestermark.RemoveAll(x => DateTime.Parse(x.START_DATE) > DateTime.Parse(lisemestermark.FirstOrDefault().START_DATE));
                                }
                                foreach (var values in lioverallsemestermark)
                                {
                                    values.EXAM_SETTING_ID = item.EXAM_SETTING_ID;
                                }
                                listoverallfinalsemester = (lioverallsemestermark != null && lioverallsemestermark.Count > 0) ? listoverallfinalsemester.Concat(lioverallsemestermark).ToList() : lioverallsemestermark;


                                //if (objViewModel.liOverAllSemestermark != null && objViewModel.liOverAllSemestermark.Count > 0)
                                //{
                                //    objViewModel.liOverAllSemestermark.RemoveAll(x => DateTime.Parse(x.START_DATE) > DateTime.Parse(objViewModel.liSemestermark.FirstOrDefault().START_DATE));
                                //}

                            }
                            objViewModel.liSemestermark = lisemestermark;
                            objViewModel.liOverAllSemestermark = listoverallfinalsemester;

                        }

                    }

                }
                catch (Exception Ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("StudentMarkSheet", "StudentController", "Err MSg: " + Ex.Message, "Query is empty!");
                        objHandler.WriteError("StudentMarkSheet", "StudentController", Ex.Message);
                    }

                }
            }
            else
                return RedirectToAction("ErrorMessage", "Error");

            return View(objViewModel);
        }
