                    // fetch major
                    var liMajor = (List<MAJOR_WISE_ALLIED_COURSES>)CMSHandler.FetchData<MAJOR_WISE_ALLIED_COURSES>(null,
                       StudentSQL.GetStudentSQL(StudentSQLCommads.FetchMajorWiseAlliedCourses), sAcademicYear).DataSource.Data;

