        public async Task<JsonResult> UpdateStuPersonalInfoForAdmissioncorrectoin(string sJsonData)
        {
            STU_PERSONAL_INFO objStuPersonalInfo = new STU_PERSONAL_INFO();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] == null) ? string.Empty : Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
            try
            {

                if (sJsonData != null)
                {

                    var Result = JsonConvert.DeserializeObject<STU_PERSONAL_INFO>(sJsonData);
                    if (!string.IsNullOrEmpty(Result.STUDENT_ID))
                    {

                        if (!string.IsNullOrEmpty(Result.DATE_OF_BIRTH))
                        {
                            Result.DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.DATE_OF_BIRTH);
                        }

                        if (!string.IsNullOrEmpty(Result.ADMISSION_DATE))
                        {
                            Result.ADMISSION_DATE = CommonMethods.ConvertdatetoyearFromat(Result.ADMISSION_DATE);
                        }


                        //update
                        var resultArgs1 = CMSHandler.SaveOrUpdate(Result,
                       StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuPersonalInfoForAdmissionCorrection), sAcademicYear);




                        //update address
                        STU_ADDRESS objAddress = new STU_ADDRESS()
                        {
                            STUDENT_ID = Result.STUDENT_ID,
                            P_DOOR_DETAIL = Result.C_DOOR_DETAIL,
                            P_STREET = Result.C_STREET,
                            P_TALUK = Result.C_TALUK,
                            P_CITY = Result.C_CITY,
                            P_DISTRICT = Result.C_DISTRICT,
                            P_PINCODE = Result.C_PINCODE

                        };

                        // fetch stu address by student id

                        var liStuAddress = (List<STU_ADDRESS>)CMSHandler.FetchData<STU_ADDRESS>(new STU_ADDRESS() { STUDENT_ID = Result.STUDENT_ID },
                        StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuAddressByStudentId), sAcademicYear).DataSource.Data;

                        if (liStuAddress != null && liStuAddress.Count > 0)
                        {
                            objAddress.ADDRESS_ID = liStuAddress.FirstOrDefault().ADDRESS_ID;

                            resultArgs = CMSHandler.SaveOrUpdate(objAddress,
                       StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuAddressForAdmissionCorrection), sAcademicYear);
                        }

                        if (resultArgs.Success && resultArgs1.Success)
                        {
                            sResult = Common.Messages.RecordsSavedSuccessfully;
                        }
                        else
                        {
                            sResult = Common.Messages.FailedToSaveRecords;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "UpdateStuPersonalInfoForAdmissioncorrectoin", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("StudentController", "UpdateStuPersonalInfoForAdmissioncorrectoin", ex.Message);
                }
                sResult = "Fail To Fetch Record(s) ...!";
            }

            return Json(sResult, JsonRequestBehavior.AllowGet);
        }


