        public JsonResult GetTransferProgrammesByClass(string sClassId)
        {
            try
            {
                if (string.IsNullOrEmpty(sClassId))
                {
                    return Json(new { success = false, message = "Class ID is required" }, JsonRequestBehavior.AllowGet);
                }

                // 1. Get student's current class shift and programme level
                string sClassSql = @"SELECT 
                                        C.CLASS_ID,
                                        C.CLASS_NAME,
                                        C.CLASS_YEAR,
                                        C.SHIFT,
                                        IFNULL(C.CLASS_LEVEL, IFNULL(PG.APPTYPE_ID, 0)) AS CLASS_LEVEL,
                                        IFNULL(PG.APPTYPE_ID, 0) AS APPTYPE_ID,
                                        IFNULL(SAT.APPLICATION_TYPE, '') AS APPLICATION_TYPE,
                                        IFNULL(SH.SHIFT_NAME, C.SHIFT) AS SHIFT_NAME
                                    FROM CP_CLASSES C
                                    LEFT JOIN CP_PROGRAMME_GROUP PG ON PG.PROGRAMME_GROUP_ID = C.PROGRAMME_GROUP_ID
                                    LEFT JOIN SUP_APPLICATION_TYPE SAT ON SAT.APPLICATION_TYPE_ID = IFNULL(C.CLASS_LEVEL, PG.APPTYPE_ID)
                                    LEFT JOIN SUP_SHIFT SH ON SH.SHIFT_ID = C.SHIFT
                                    WHERE C.CLASS_ID = ?CLASS_ID
                                    LIMIT 1;";

                var currentClassDetails = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new { CLASS_ID = sClassId }, sClassSql).DataSource.Data;

                string shiftId = "";
                string appTypeId = "";
                string shiftName = "";
                string levelName = "";
                string classYear = "";

                if (currentClassDetails != null && currentClassDetails.Count > 0)
                {
                    var cd = currentClassDetails.FirstOrDefault();
                    shiftId = cd.SHIFT ?? "";
                    appTypeId = cd.CLASS_LEVEL ?? "";
                    shiftName = cd.SHIFT_NAME ?? cd.SHIFT ?? "";
                    levelName = cd.APPLICATION_TYPE ?? "";
                    classYear = cd.CLASS_YEAR ?? "";
                }

                // 2. Query CP_PROGRAMME_GROUP filtered strictly by SHIFT and APPTYPE_ID (UG/PG)
                string sProgSql = @"SELECT 
                                        AP.PROGRAMME_GROUP_ID,
                                        P.PROGRAMME_ID,
                                        CONCAT(IFNULL(P.PROGRAMME_NAME, ''),
                                                ' (SHIFT - ',
                                                IFNULL(SH.SHIFT_NAME, ''),
                                                ') ',
                                                IFNULL(SPM.PROGRAMME_MODE, '')) AS PROGRAMME_NAME
                                    FROM
                                        CP_PROGRAMME_GROUP AS AP
                                            INNER JOIN
                                        CP_PROGRAMME AS P ON P.PROGRAMME_ID = AP.PROGRAMME_ID
                                            AND P.IS_DELETED != 1
                                            INNER JOIN
                                        SUP_SHIFT SH ON SH.SHIFT_ID = AP.SHIFT
                                            INNER JOIN
                                        SUP_PROGRAMME_MODE AS SPM ON SPM.PROGRAMME_MODE_ID = AP.PROGRAMME_MODE
                                    WHERE
                                        AP.IS_DELETED != 1
                                        AND (?SHIFT = '' OR AP.SHIFT = ?SHIFT)
                                        AND (?APPTYPE_ID = '' OR ?APPTYPE_ID = '0' OR AP.APPTYPE_ID = ?APPTYPE_ID)
                                    ORDER BY P.PROGRAMME_NAME;";

                var param = new { SHIFT = shiftId, APPTYPE_ID = appTypeId };
                var progList = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(param, sProgSql).DataSource.Data;

                string sOptions = "<option value=''>-- Select Target Programme --</option>";
                if (progList != null && progList.Count > 0)
                {
                    foreach (var p in progList)
                    {
                        sOptions += "<option value='" + p.PROGRAMME_GROUP_ID + "'>" + p.PROGRAMME_NAME + "</option>";
                    }
                }

                return Json(new
                {
                    success = true,
                    options = sOptions,
                    shiftId = shiftId,
                    shiftName = shiftName,
                    appTypeId = appTypeId,
                    levelName = levelName,
                    classYear = classYear,
                    count = (progList != null ? progList.Count : 0)
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

