        public JsonResult GetLastRollNoByClass(string sClassId, string sAcYear = "")
        {
            try
            {
                string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                if (string.IsNullOrEmpty(sAcYear) || sAcYear.Contains("--select--"))
                {
                    sAcYear = sAcademicYear;
                }

                if (string.IsNullOrEmpty(sClassId))
                {
                    return Json(new { success = false, message = "Class ID is empty" }, JsonRequestBehavior.AllowGet);
                }

                string sSql = @"SELECT 
                                    ROLL_NO
                                FROM
                                    STU_PERSONAL_INFO AS spi
                                        INNER JOIN
                                    STU_CLASS AS SC ON SC.STUDENT_ID = SPI.STUDENT_ID
                                WHERE
                                    SC.CLASS_ID = ?CLASS_ID
                                        AND SC.ACADEMIC_YEAR = ?AC_YEAR
                                        AND SC.IS_DELETED != 1
                                        AND SPI.IS_DELETED != 1
                                        AND SPI.ROLL_NO IS NOT NULL
                                        AND TRIM(ROLL_NO) != '' GROUP BY spi.ROLL_NO;";

                var objParam = new { CLASS_ID = sClassId, AC_YEAR = sAcYear };
                var list = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(objParam, sSql).DataSource.Data;

                string lastRollNo = "";
                string nextRollNo = "";
                int totalStudents = 0;

                if (list != null && list.Count > 0)
                {
                    var validRolls = list.Select(x => x.ROLL_NO).Where(r => !string.IsNullOrWhiteSpace(r)).ToList();
                    totalStudents = validRolls.Count;

                    lastRollNo = validRolls
                        .OrderByDescending(r => ExtractRollNoPrefix(r))
                        .ThenByDescending(r => ExtractRollNoNumber(r))
                        .FirstOrDefault() ?? "";

                    if (!string.IsNullOrEmpty(lastRollNo))
                    {
                        nextRollNo = ComputeNextRollNo(lastRollNo);
                    }
                }

                return Json(new
                {
                    success = true,
                    lastRollNo = lastRollNo,
                    nextRollNo = nextRollNo,
                    totalStudents = totalStudents
                }, JsonRequestBehavior.AllowGet);
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }

        private static string ExtractRollNoPrefix(string rollNo)
        {
            if (string.IsNullOrWhiteSpace(rollNo)) return "";
            string trimmed = rollNo.Trim();
            int i = trimmed.Length - 1;
            while (i >= 0 && char.IsDigit(trimmed[i])) i--;
            return trimmed.Substring(0, i + 1);
        }

        private static long ExtractRollNoNumber(string rollNo)
        {
            if (string.IsNullOrWhiteSpace(rollNo)) return 0;
            string trimmed = rollNo.Trim();
            int i = trimmed.Length - 1;
            while (i >= 0 && char.IsDigit(trimmed[i])) i--;
            string digits = trimmed.Substring(i + 1);
            long val;
            long.TryParse(digits, out val);
            return val;
        }

        private static string ComputeNextRollNo(string lastRollNo)
        {
            if (string.IsNullOrWhiteSpace(lastRollNo)) return "";
            string trimmed = lastRollNo.Trim();
            int i = trimmed.Length - 1;
            while (i >= 0 && char.IsDigit(trimmed[i])) i--;

            string prefix = trimmed.Substring(0, i + 1);
            string digits = trimmed.Substring(i + 1);

            if (string.IsNullOrEmpty(digits))
            {
                return trimmed + "01";
            }

            long num;
            if (long.TryParse(digits, out num))
            {
                long next = num + 1;
                string nextDigits = next.ToString().PadLeft(digits.Length, '0');
                return prefix + nextDigits;
            }

            return trimmed;
        }

        public JsonResult VerifyRollNumber(string sRollNo, string sCurrentStudentId = "")
        {
            var result = new RollNoVerificationResult();
            try
            {
                if (string.IsNullOrWhiteSpace(sRollNo))
                {
                    result.IsAssigned = false;
                    result.Message = "Please enter a roll number.";
                    return Json(result, JsonRequestBehavior.AllowGet);
                }

                sRollNo = sRollNo.Trim();
                var objParam = new { ROLL_NO = sRollNo };
                var liStudent = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(objParam, StudentSQL.GetStudentSQL(StudentSQLCommads.CheckStudentRollNoExists)).DataSource.Data;

                if (liStudent != null && liStudent.Count > 0)
                {
                    var stu = liStudent.FirstOrDefault();
                    result.StudentId = stu.STUDENT_ID;
                    result.RollNo = stu.ROLL_NO;
                    result.StudentName = stu.FIRST_NAME;
                    result.ClassId = stu.CLASS_ID;
                    result.ClassName = stu.CLASS_NAME;
                    result.ProgrammeGroupId = stu.PROGRAMME_GROUP_ID;
                    result.ProgrammeName = stu.PROGRAMME_NAME;

                    if (!string.IsNullOrEmpty(sCurrentStudentId) && stu.STUDENT_ID == sCurrentStudentId)
                    {
                        result.IsAssigned = false;
                        result.Message = "This is the student's current roll number.";
                    }
                    else
                    {
                        result.IsAssigned = true;
                        result.Message = "Roll number is already assigned to " + stu.FIRST_NAME + " (" + stu.CLASS_NAME + ").";
                    }
                }
                else
                {
                    result.IsAssigned = false;
                    result.RollNo = sRollNo;
                    result.Message = "Roll number is available.";
                }
            }
            catch (Exception ex)
            {
                result.IsAssigned = false;
                result.Message = "Error verifying roll number: " + ex.Message;
            }
            return Json(result, JsonRequestBehavior.AllowGet);
        }

        [HttpPost]
        public JsonResult SubmitProgrammeTransfer(ProgrammeTransferDTO model)
        {
            JsonResultData ObjJson = new JsonResultData();
            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = Session[Common.SESSION_VARIABLES.USER_ID] != null ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : "Admin";

            if (model == null || string.IsNullOrEmpty(model.StudentId) || string.IsNullOrEmpty(model.NewRollNo) || string.IsNullOrEmpty(model.TransferProgrammeGroupId) || string.IsNullOrEmpty(model.TransferClassId))
            {
                ObjJson.ErrorCode = Common.ErrorCode.NotAcceptable;
                ObjJson.Message = "Please fill all required transfer details (Target Programme, Target Class, and New Roll No).";
                return Json(ObjJson);
            }

            model.NewRollNo = model.NewRollNo.Trim();
            if (string.IsNullOrEmpty(model.AcademicYear) || model.AcademicYear== "--select--")
            {
                model.AcademicYear = sAcademicYear;
            }

            try
            {
                // Verify if New Roll No is assigned to another student
                var objParam = new { ROLL_NO = model.NewRollNo };
                var existingStudent = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(objParam, StudentSQL.GetStudentSQL(StudentSQLCommads.CheckStudentRollNoExists)).DataSource.Data;
                if (existingStudent != null && existingStudent.Count > 0)
                {
                    var existing = existingStudent.FirstOrDefault();
                    if (existing.STUDENT_ID != model.StudentId)
                    {
                        ObjJson.ErrorCode = Common.ErrorCode.NotAcceptable;
                        ObjJson.Message = "Cannot transfer: The Roll Number '" + model.NewRollNo + "' is already assigned to " + existing.FIRST_NAME + " (" + existing.CLASS_NAME + ").";
                        return Json(ObjJson);
                    }
                }

                // Fetch target class details (Shift, Department, Class Name)
                string sClassSql = "SELECT CLASS_ID, CLASS_NAME, SHIFT, DEPARTMENT, PROGRAMME_GROUP_ID FROM CP_CLASSES WHERE CLASS_ID = ?CLASS_ID LIMIT 1;";
                var targetClassList = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(new { CLASS_ID = model.TransferClassId }, sClassSql).DataSource.Data;
                string sShiftId = "1";
                string sDeptId = "1";
                if (targetClassList != null && targetClassList.Count > 0)
                {
                    var tc = targetClassList.FirstOrDefault();
                    sShiftId = tc.SHIFT;
                    sDeptId = tc.DEPARTMENT;
                    model.TransferClassName = tc.CLASS_NAME;
                }

                // Fetch target programme name
                string sProgSql = "SELECT CONCAT(IFNULL(P.PROGRAMME_NAME, ''), ' (SHIFT - ', IFNULL(SH.SHIFT_NAME, ''), ') ', IFNULL(SPM.PROGRAMME_MODE, '')) AS PROGRAMME_NAME FROM CP_PROGRAMME_GROUP AP INNER JOIN CP_PROGRAMME P ON P.PROGRAMME_ID = AP.PROGRAMME_ID INNER JOIN SUP_SHIFT SH ON SH.SHIFT_ID = AP.SHIFT INNER JOIN SUP_PROGRAMME_MODE SPM ON SPM.PROGRAMME_MODE_ID = AP.PROGRAMME_MODE WHERE AP.PROGRAMME_GROUP_ID = ?PROGRAMME_GROUP_ID LIMIT 1;";
                var targetProgList = (List<ListStudents>)CMSHandler.FetchData<ListStudents>(new { PROGRAMME_GROUP_ID = model.TransferProgrammeGroupId }, sProgSql).DataSource.Data;
                if (targetProgList != null && targetProgList.Count > 0)
                {
                    model.TransferProgrammeName = targetProgList.FirstOrDefault().PROGRAMME_NAME;
                }

                // 1. Update STU_PERSONAL_INFO
                var personalUpdateParam = new
                {
                    ROLL_NO = model.NewRollNo,
                    PROGRAM_ID = model.TransferProgrammeGroupId,
                    CLASS_ID = model.TransferClassId,
                    DEPT_ID = sDeptId,
                    SHIFT_ID = sShiftId,
                    STUDENT_ID = model.StudentId
                };
                CMSHandler.SaveOrUpdate(personalUpdateParam, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStudentPersonalInfoForProgrammeTransfer));

                // 2. Update STU_CLASS
                var classUpdateParam = new
                {
                    CLASS_ID = model.TransferClassId,
                    ROLL_NO = model.NewRollNo,
                    PROGRAMME_GROUP_ID = model.TransferProgrammeGroupId,
                    STUDENT_ID = model.StudentId
                };
                CMSHandler.SaveOrUpdate(classUpdateParam, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStudentClassForProgrammeTransfer), model.AcademicYear);

                // 3. Update USER_ACCOUNT (if student user account exists)
                var userAccountParam = new
                {
                    USERNAME = model.NewRollNo,
                    USER_ID = model.StudentId
                };
                CMSHandler.SaveOrUpdate(userAccountParam, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateUserAccountRollNo));

                // 4. Insert into STU_PROGRAMME_TRANSFER_LOG (IDs only as requested)
                var logParam = new
                {
                    STUDENT_ID = model.StudentId,
                    CURRENT_ROLL_NO = model.CurrentRollNo,
                    NEW_ROLL_NO = model.NewRollNo,
                    CURRENT_PROGRAMME_GROUP_ID = model.CurrentProgrammeGroupId,
                    CURRENT_CLASS_ID = model.CurrentClassId,
                    TRANSFER_PROGRAMME_GROUP_ID = model.TransferProgrammeGroupId,
                    TRANSFER_CLASS_ID = model.TransferClassId,
                    ACADEMIC_YEAR = model.AcademicYear,
                    REMARKS = model.Remarks,
                    TRANSFERRED_BY = sUserId
                };
                CMSHandler.SaveOrUpdate(logParam, StudentSQL.GetStudentSQL(StudentSQLCommads.InsertProgrammeTransferLog));

                ObjJson.ErrorCode = Common.ErrorCode.Ok;
                ObjJson.Message = "Student '" + model.StudentName + "' successfully transferred to " + model.TransferProgrammeName + " with New Roll No: " + model.NewRollNo;
            }
            catch (Exception ex)
            {
                ObjJson.ErrorCode = Common.ErrorCode.InternalServerError;
                ObjJson.Message = "An error occurred during transfer: " + ex.Message;
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "SubmitProgrammeTransfer", ex.Message);
                }
            }
            return Json(ObjJson);
        }

