        public async Task<ActionResult> BindAcYearWiseStudentList(string sAcYear)
        {
            string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sStaffId = Session[Common.SESSION_VARIABLES.USER_ID] != null ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            StudentViewModel ObjViewModel = new StudentViewModel();

            if (!string.IsNullOrEmpty(sAcYear))
            {

                ObjViewModel.liStudentList = await Task.Run(() => (List<ListStudents>)CMSHandler.FetchData<ListStudents>(null, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentListbyAcademicYearWise), sAcYear).DataSource.Data);


                // fetch project type

                var liAcademicYear = (List<ACADEMIC_YEAR>)CMSHandler.FetchData<ACADEMIC_YEAR>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchAcademicYearList), sAcademicYear).DataSource.Data;
                if (liAcademicYear != null)
                {
                    ObjViewModel.AcademicYear = new SelectList(liAcademicYear, Common.ACADEMIC_YEAR.ACADEMIC_YEAR_ID, Common.ACADEMIC_YEAR.AC_YEAR);
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return View(ObjViewModel);
        }
        public ActionResult AddStudentDetailsInfo()
        {

            StuAcadamicInfo objAcademicInfo = new StuAcadamicInfo();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    // Batch ...
                    var liBatch = (List<sup_Batch>)CMSHandler.FetchData<sup_Batch>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchBatch), sAcademicYear).DataSource.Data;
                    if (liBatch != null && liBatch.Count > 0)
                    {
                        objAcademicInfo.BATCH = new SelectList(liBatch, Common.SUP_BATCHES.BATCH_ID, Common.SUP_BATCHES.BATCH);
                    }


                    // Class ....
                    var liClasses = (List<cp_Classes_2017>)CMSHandler.FetchData<cp_Classes_2017>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchClasses), sAcademicYear).DataSource.Data;
                    if (liClasses != null && liClasses.Count > 0)
                    {
                        objAcademicInfo.CLASS_ID = new SelectList(liClasses, Common.CP_CLASSES_2017.CLASS_ID, Common.CP_CLASSES_2017.CLASS_NAME);
                        objAcademicInfo.ADMITTED_CLASS = new SelectList(liClasses, Common.CP_CLASSES_2017.CLASS_ID, Common.CP_CLASSES_2017.CLASS_NAME);
                    }
                    Session[Common.SESSION_VARIABLES.STUDENT_ID] = null;
                    // Gender ....
                    var liGender = (List<SupGender>)CMSHandler.FetchData<SupGender>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchGender)).DataSource.Data;
                    if (liGender != null && liGender.Count > 0)
                        objAcademicInfo.GENDERID = new SelectList(liGender, Common.SUP_GENDER.GENDER_ID, Common.SUP_GENDER.GENDER_NAME);

                    // Community ....
                    var liCommunity = (List<SupCommunity>)CMSHandler.FetchData<SupCommunity>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchCommunity)).DataSource.Data;
                    if (liCommunity != null && liCommunity.Count > 0)
                        objAcademicInfo.COMMUNITY = new SelectList(liCommunity, Common.SUP_COMMUNITY.COMMUNITYID, Common.SUP_COMMUNITY.COMMUNITY);

                    // MotherTongue ....
                    var liMotherTongue = (List<SupMotherTongue>)CMSHandler.FetchData<SupMotherTongue>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchMotherTongue)).DataSource.Data;
                    if (liMotherTongue != null && liMotherTongue.Count > 0)
                        objAcademicInfo.MOTHERTONGUE = new SelectList(liMotherTongue, Common.SUP_MOTHER_TONGUE.MOTHER_TONGUE_ID, Common.SUP_MOTHER_TONGUE.MOTHER_TONGUE_NAME);

                    // Language ....
                    var liLanguage = (List<Sup_Language>)CMSHandler.FetchData<Sup_Language>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchLanguage)).DataSource.Data;
                    if (liLanguage != null && liLanguage.Count > 0)
                    {
                        objAcademicInfo.FIRSTLANGUAGE = new SelectList(liLanguage, Common.SUP_LANGUAGE.LANGUAGE_ID, Common.SUP_LANGUAGE.LANGUAGE_NAME);
                        objAcademicInfo.SECONDLANGUAGE = new SelectList(liLanguage, Common.SUP_LANGUAGE.LANGUAGE_ID, Common.SUP_LANGUAGE.LANGUAGE_NAME);
                    }
                    // Boold Group ...
                    var liBloodGroup = (List<SupBloodGroup>)CMSHandler.FetchData<SupBloodGroup>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchBloodGroup)).DataSource.Data;
                    if (liBloodGroup != null && liBloodGroup.Count > 0)
                    {
                        objAcademicInfo.BLOODGROUP = new SelectList(liBloodGroup, Common.SUP_BLOOD_GROUP.BLOOD_GROUP_ID, Common.SUP_BLOOD_GROUP.BLOOD_GROUP_NAME);
                    }

                    // Religion ...
                    var liReligion = (List<SUP_RELIGION>)CMSHandler.FetchData<SUP_RELIGION>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchReligion)).DataSource.Data;
                    if (liReligion != null && liReligion.Count > 0)
                    {
                        objAcademicInfo.RELIGION = new SelectList(liReligion, Common.SUP_RELIGION.RELIGIONID, Common.SUP_RELIGION.RELIGION);
                    }

                    //Nationality ...
                    var liNationality = (List<SupNationality>)CMSHandler.FetchData<SupNationality>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchNationality)).DataSource.Data;
                    if (liNationality != null && liNationality.Count > 0)
                    {
                        objAcademicInfo.NATIONALITY = new SelectList(liNationality, Common.SUP_NATIONALITY.NATIONALITY_ID, Common.SUP_NATIONALITY.NATIONALITY_NAME);
                    }

                    //SpeciallyAbled ...
                    var liSpeciallyAbled = (List<Sup_Specially_Abled>)CMSHandler.FetchData<Sup_Specially_Abled>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSpeciallyAbled)).DataSource.Data;
                    if (liSpeciallyAbled != null && liSpeciallyAbled.Count > 0)
                    {
                        objAcademicInfo.SPECIALLYABLED = new SelectList(liSpeciallyAbled, Common.SUP_SPECIALLY_ABLED.SPECIALLY_ABLED_ID, Common.SUP_SPECIALLY_ABLED.SPECIALLY_ABLED_NAME);
                    }

                    //liResidencyType ...
                    var liResidencyType = (List<Sup_ResidencyType>)CMSHandler.FetchData<Sup_ResidencyType>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchResidencyType)).DataSource.Data;
                    if (liResidencyType != null && liResidencyType.Count > 0)
                    {
                        objAcademicInfo.RESIDENCYTYPE = new SelectList(liResidencyType, Common.SUP_RESIDENCY_TYPE.RESIDENCY_TYPE_ID, Common.SUP_RESIDENCY_TYPE.RESIDENCY_TYPE_NAME);
                    }
                    //Marital Status ..
                    var liMaritalStatus = (List<SupMaritalStatus>)CMSHandler.FetchData<SupMaritalStatus>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchMarritalStatus)).DataSource.Data;
                    if (liMaritalStatus != null && liMaritalStatus.Count > 0)
                    {
                        objAcademicInfo.MARITALSTATUS = new SelectList(liMaritalStatus, Common.SUP_MARRITAL_STATUS.MARITAL_STAUS_ID, Common.SUP_MARRITAL_STATUS.MARITAL_STATUS_NAME);
                    }
                    var liOccupation = (List<Sup_Occupation>)CMSHandler.FetchData<Sup_Occupation>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchOccupation)).DataSource.Data;
                    if (liOccupation != null && liOccupation.Count > 0)
                    {
                        //objAcademicInfo.FR_OCCUPATION = new SelectList(liOccupation, Common.SUP_OCCUPATION.OCCUPATION_ID, Common.SUP_OCCUPATION.OCCUPATION_NAME);
                        //objAcademicInfo.MO_OCCUPATION = new SelectList(liOccupation, Common.SUP_OCCUPATION.OCCUPATION_ID, Common.SUP_OCCUPATION.OCCUPATION_NAME);
                    }
                    var liState = (List<SUP_STATE>)CMSHandler.FetchData<SUP_STATE>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupState)).DataSource.Data;
                    if (liState != null && liState.Count > 0)
                    {
                        objAcademicInfo.STATE = new SelectList(liState, Common.SUP_STATE.STATE_ID, Common.SUP_STATE.STATE_NAME);
                    }
                    var specialabeld = (List<Sup_Specially_Abled>)CMSHandler.FetchData<Sup_Specially_Abled>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSpeciallyAbled)).DataSource.Data;
                    if (specialabeld != null && specialabeld.Count > 0)
                    {
                        objAcademicInfo.SPECIAL_ABLED = new SelectList(specialabeld, Common.SUP_SPECIALLY_ABLED.SPECIALLY_ABLED_ID, Common.SUP_SPECIALLY_ABLED.SPECIALLY_ABLED_NAME);
                    }
                    var EducationBoard = (List<Sup_Education_board>)CMSHandler.FetchData<Sup_Education_board>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupEducationBoard)).DataSource.Data;
                    if (EducationBoard != null && EducationBoard.Count > 0)
                    {
                        objAcademicInfo.STUDY_BOARD = new SelectList(EducationBoard, Common.SUP_EDUCATION_BOARD.EDUCATION_BOARD_ID, Common.SUP_EDUCATION_BOARD.EDUCATION_BOARD);
                    }
                    var Extra_curiculam = (List<Sup_Extra_curriculam>)CMSHandler.FetchData<Sup_Extra_curriculam>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupExtraCuriculam)).DataSource.Data;
                    if (Extra_curiculam != null && Extra_curiculam.Count > 0)
                    {
                        objAcademicInfo.EXTRA_CURRRICULAR = new SelectList(Extra_curiculam, Common.SUP_EXTRA_CURRICULAM.CURUCULAR_ID, Common.SUP_EXTRA_CURRICULAM.CURUCULAR_NAME);
                    }
                    var mediumstudy = (List<Sup_MediyumofStudy>)CMSHandler.FetchData<Sup_MediyumofStudy>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchmediyumofStudy)).DataSource.Data;
                    if (mediumstudy != null && mediumstudy.Count > 0)
                    {
                        objAcademicInfo.MEDIUM_STUDY = new SelectList(mediumstudy, Common.SUP_MEDIUMSTUDY.MEDIUM_ID, Common.SUP_MEDIUMSTUDY.MEDIUM_NAME);
                    }
                    var studyUniversity = (List<SUP_UNIVERSITY>)CMSHandler.FetchData<SUP_UNIVERSITY>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchUniversity)).DataSource.Data;
                    if (studyUniversity != null && studyUniversity.Count > 0)
                    {
                        objAcademicInfo.LAST_STUDIED_UNIVERSITY = new SelectList(studyUniversity, Common.SUP_UNIVERSITY_TYPE.UNIVERSITY_ID, Common.SUP_UNIVERSITY_TYPE.UNIVERSITY);
                    }

                    // Sup_Role ...
                    var liRole = new List<SUP_ROLE>();
                    liRole = (List<SUP_ROLE>)CMSHandler.FetchData<SUP_ROLE>(null, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchSupRole)).DataSource.Data;
                    objAcademicInfo.Role = new SelectList(liRole, Common.SUP_ROLE.ROLE_ID, Common.SUP_ROLE.ROLE_NAME);

                    // UserType ...
                    var liUserType = new List<SUP_USER_TYPE>();
                    liUserType = (List<SUP_USER_TYPE>)CMSHandler.FetchData<SUP_USER_TYPE>(null, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchUserType)).DataSource.Data;
                    objAcademicInfo.UserType = new SelectList(liUserType, Common.SUP_USER_TYPE.USER_TYPE_ID, Common.SUP_USER_TYPE.USER_TYPE_NAME);
                    return View(objAcademicInfo);
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjHandler = new ErrorLog())
                    {
                        ObjHandler.WriteError("StudentController", "AddStuAcademicInfo", "Err MSg: " + ex.Message, "Query is empty!");
                        ObjHandler.WriteError("StudentController", "AddStuAcademicInfo", ex.Message);
                    }
                    return View(objAcademicInfo);
                }
            }
            else
            {
                sResult = Common.ErrorCode.RequestTimeout;
                return Json(sResult, JsonRequestBehavior.AllowGet);
            }
        }
        public JsonResult InsertStuPersonalInfo(string str, string sBaseImage, string sExtension)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            string sUserRole = (Session[Common.SESSION_VARIABLES.USER_ROLE_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ROLE_ID].ToString() : string.Empty;

            try
            {
                var ObjStuClass = new STU_CLASS();
                var objAccountInfo = new USER_ACCOUNT_INFO();
                var Result = JsonConvert.DeserializeObject<STU_PERSONAL_INFO>(str);
                Result.DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.DATE_OF_BIRTH);
                Result.ADMISSION_DATE = CommonMethods.ConvertdatetoyearFromat(Result.ADMISSION_DATE);

                var FetchProgramGroupId = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(Result,
                        SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchShiftAndProgrameGroupByClassId), sAcademicYear).DataSource.Data;
                if (FetchProgramGroupId != null && FetchProgramGroupId.Count > 0)
                {
                    Result.PROGRAM_ID = FetchProgramGroupId.FirstOrDefault().PROGRAMME_GROUP_ID;
                    Result.DEPT_ID = FetchProgramGroupId.FirstOrDefault().DEPARTMENT;
                    Result.SHIFT_ID = FetchProgramGroupId.FirstOrDefault().SHIFT;
                }
                if (!string.IsNullOrEmpty(Result.ROLL_NO))
                {

                    ObjStuClass.PROGRAMME_GROUP_ID = Result.PROGRAM_ID;
                    ObjStuClass.CLASS_ID = Result.CLASS_ID;
                    ObjStuClass.BATCH = Result.BATCH;
                    Result.CURRENT_BATCH = Result.BATCH;
                    ObjStuClass.ACADEMIC_YEAR = sAcademicYear;
                    Result.ENTRY_ID = sUserId;
                    Result.ENTRY_ROLE = sUserRole;
                    Result.ENTRY_DATE = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                    Result.ROLL_NO = Result.ROLL_NO.ToUpper();
                    Result.RFID = Result.ROLL_NO.ToUpper();
                    Result.BAR_CODE = Result.ROLL_NO.ToUpper();
                    Result.BIOD_NUMBER = Result.ROLL_NO.ToUpper();
                    Session[Common.SESSION_VARIABLES.USER_NAME] = Result.ROLL_NO;
                    // Assign Values For User Account ...

                    objAccountInfo.ACADEMIC_YEAR = sAcademicYear;
                    objAccountInfo.EMAIL = Result.STU_EMAILID;
                    objAccountInfo.USERNAME = Result.ROLL_NO.ToUpper();
                    objAccountInfo.PASSWORD = CommonMethods.GetSha256FromString(Result.ROLL_NO.ToUpper());
                    objAccountInfo.ROLE = Common.USER_TYPE.STUDENT;
                    objAccountInfo.USER_TYPE = Common.USER_TYPE.STUDENT;
                    objAccountInfo.ROLE_ID = Common.USER_TYPE.STUDENT;

                    objAccountInfo.NAME = Result.FIRST_NAME + " " + Result.LAST_NAME;
                    objAccountInfo.ENTRY_ID = sUserId;
                    if (!string.IsNullOrEmpty(sBaseImage) && (!string.IsNullOrEmpty(sExtension)))
                    {
                        Result.PHOTO = SaveImage(sBaseImage, sExtension, Result.ROLL_NO);
                        objAccountInfo.PHOTO = SaveImage(sBaseImage, sExtension, Result.ROLL_NO);
                    }
                    else
                        Result.PHOTO = "";
                    objAccountInfo.PHOTO = "";
                    var liAccountInfo = (List<USER_ACCOUNT_INFO>)CMSHandler.FetchData<USER_ACCOUNT_INFO>(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchUserAccountByRoleAndId)).DataSource.Data;
                    if (liAccountInfo != null && liAccountInfo.Count > 0)
                    {
                        objAccountInfo.USER_ACCOUNT_ID = liAccountInfo.FirstOrDefault().USER_ACCOUNT_ID;
                        objAccountInfo.MOBILE = liAccountInfo.FirstOrDefault().MOBILE;
                        objAccountInfo.NAME = liAccountInfo.FirstOrDefault().NAME;
                    }

                    //Result.STUDENT_REGISTERDED_DATE = CommonMethods.ConvertdatetoyearFromat(Result.STUDENT_REGISTERDED_DATE);
                    Result.ADMISSION_DATE = CommonMethods.ConvertdatetoyearFromat(Result.ADMISSION_DATE);
                    var liExits = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.AcadamicIfExits)).DataSource.Data;
                    if (liExits != null && liExits.Count > 0)
                    {
                        //var UpdateAcademicInfo = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateAcadamicInfo));
                        //if (UpdateAcademicInfo.Success)
                        //{
                        //    Session[Common.SESSION_VARIABLES.LAST_INSERT_ID] = liExits.FirstOrDefault().STUDENT_ID;
                        //    // update Stu_Class ...
                        //    var result = (List<STU_CLASS>)CMSHandler.FetchData<STU_CLASS>(new STU_CLASS() { STUDENT_ID = sStudentID, ACADEMIC_YEAR = sAcademicYear }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuclassByStudentIdAndAcademicYear)).DataSource.Data;
                        //    if (result != null && result.Count > 0)
                        //    {
                        //        ObjStuClass.STU_CLASS_ID = result.FirstOrDefault().STU_CLASS_ID;
                        //    }
                        //    var UpdateStuClass = CMSHandler.SaveOrUpdate(ObjStuClass, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuclass));
                        //    if (UpdateStuClass.Success)
                        //    {
                        //        resultArgs = CMSHandler.SaveOrUpdate(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.UpdateUserAccount));
                        //        ObjJsonData.Message = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.NotAcceptable;
                        //    }
                        //}
                        //else
                        //{
                        //    ObjJsonData.Message = Common.ErrorCode.NotAcceptable;
                        //}
                        ObjJsonData.Message = Common.ErrorCode.Conflict;
                        return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
                    }
                    else
                    {
                        var InsertAcademicInfo = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveStuPersonalinfo), "", true);
                        if (InsertAcademicInfo.Success)
                        {
                            string sStudentId = InsertAcademicInfo.RowUniqueId.ToString();
                            Session[Common.SESSION_VARIABLES.LAST_INSERT_ID] = sStudentId;
                            objAccountInfo.USER_ID = sStudentId;
                            ObjStuClass.STUDENT_ID = sStudentId;

                            // Insert Stu Class ...
                            var InsertStuClass = CMSHandler.SaveOrUpdate(ObjStuClass, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveStuClass));
                            // Insert User Account ...
                            if (InsertStuClass.Success)
                            {
                                var InsertUserAccount = CMSHandler.SaveOrUpdate(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.SaveUserAccount));
                                if (InsertUserAccount.Success)
                                {
                                    var InsertUserRolebyAcYear = CMSHandler.SaveOrUpdate(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.SaveUserRoleByAcademicYear));

                                }
                                ObjJsonData.Message = (InsertUserAccount.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.NotAcceptable;
                            }
                            else
                            {
                                var DeleteAcademicInfo = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.DeleteStudent));
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "InsertAcadamicInfo", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("StudentController", "InsertAcadamicInfo", ex.Message);
                }
                ObjJsonData.Message = Common.ErrorMessage.InternalServerError;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
