                    var Extra_curiculam = (List<Sup_Extra_curriculam>)CMSHandler.FetchData<Sup_Extra_curriculam>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSupExtraCuriculam)).DataSource.Data;
                    if (Extra_curiculam != null && Extra_curiculam.Count > 0)
                    {
                        objAcademicInfo.EXTRA_CURRRICULAR = new SelectList(Extra_curiculam, Common.SUP_EXTRA_CURRICULAM.CURUCULAR_ID, Common.SUP_EXTRA_CURRICULAM.CURUCULAR_NAME);
