                    if (liLeftReason != null && liLeftReason.Count > 0)
                    {
                        objAcademicInfo.LEFT_REASON = new SelectList(liLeftReason, Common.SUP_LEFT_REASON.REASON_ID, Common.SUP_LEFT_REASON.REASON);
                    }
                    // Sup_Role ...
                    var liRole = new List<SUP_ROLE>();
                    liRole = (List<SUP_ROLE>)CMSHandler.FetchData<SUP_ROLE>(null, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchSupRole)).DataSource.Data;
                    objAcademicInfo.Role = new SelectList(liRole, Common.SUP_ROLE.ROLE_ID, Common.SUP_ROLE.ROLE_NAME);

                    // UserType ...
                    var liUserType = new List<SUP_USER_TYPE>();
                    liUserType = (List<SUP_USER_TYPE>)CMSHandler.FetchData<SUP_USER_TYPE>(null, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchUserType)).DataSource.Data;
                    objAcademicInfo.UserType = new SelectList(liUserType, Common.SUP_USER_TYPE.USER_TYPE_ID, Common.SUP_USER_TYPE.USER_TYPE_NAME);
                    return View(objAcademicInfo);
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjHandler = new ErrorLog())
                    {
                        ObjHandler.WriteError("StudentController", "EditStuAcademicInfo", "Err MSg: " + ex.Message, "Query is empty!");
                        ObjHandler.WriteError("StudentController", "EditStuAcademicInfo", ex.Message);
                    }
                    return View(objAcademicInfo);
                }
            }
            else
            {
                sResult = Common.ErrorCode.RequestTimeout;
                return Json(sResult, JsonRequestBehavior.AllowGet);
            }
        }
        public JsonResult UpdateStupersonalInfo()
        {
            string sStudentID = (Session[Common.SESSION_VARIABLES.STUDENT_ID] != null) ? Session[Common.SESSION_VARIABLES.STUDENT_ID].ToString() : string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            string sUserRole = (Session[Common.SESSION_VARIABLES.USER_ROLE_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ROLE_ID].ToString() : string.Empty;
            var str = Request.Form["str"];
            var AcademicYear = Request.Form["AcademicYear"];
            string filePath = string.Empty;
            string sImagePath = string.Empty;
            string _sDirectorypath = string.Empty;

            try
            {
                _sDirectorypath = AppDomain.CurrentDomain.BaseDirectory + "\\" + Common.URLPages.STUDENT_IMGAE_PATH;

                if (!Directory.Exists(_sDirectorypath))
                {
                    Directory.CreateDirectory(_sDirectorypath);
                }
                var Result = JsonConvert.DeserializeObject<STU_PERSONAL_INFO>(str);
                //string sRegisterDate = CommonMethods.ConvertdatetoyearFromat(Result.sRegisterDate);
                Result.ADMISSION_DATE = CommonMethods.ConvertdatetoyearFromat(Result.ADMISSION_DATE);
                Result.DATE_OF_BIRTH = CommonMethods.ConvertdatetoyearFromat(Result.DATE_OF_BIRTH);
                var FetchProgramGroupId = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(Result,
                    SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchShiftAndProgrameGroupByClassId), sAcademicYear).DataSource.Data;
                if (FetchProgramGroupId != null && FetchProgramGroupId.Count > 0)
                {
                    Result.PROGRAMME_GROUP_ID = FetchProgramGroupId.FirstOrDefault().PROGRAMME_GROUP_ID;
                    Result.PROGRAM_ID = FetchProgramGroupId.FirstOrDefault().PROGRAMME_GROUP_ID;
                    Result.PROGRAMME_MODE = FetchProgramGroupId.FirstOrDefault().PROGRAMME_MODE;
                    Result.SHIFT = FetchProgramGroupId.FirstOrDefault().SHIFT;
                    Result.SHIFT_ID = FetchProgramGroupId.FirstOrDefault().SHIFT;
                    Result.DEPT_ID = FetchProgramGroupId.FirstOrDefault().DEPARTMENT;
                }
                Result.ROLE = Common.USER_TYPE.STUDENT;
                Result.USER_TYPE = Common.USER_TYPE.STUDENT;
                Result.STUDENT_ID = sStudentID;
                Result.ENTRY_ID = sUserId;
                Result.ENTRY_ROLE = sUserRole;
                Result.ENTRY_DATE = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
                Result.ROLL_NO = Result.ROLL_NO.ToUpper();
                Result.RFID = Result.ROLL_NO.ToUpper();
                Result.BIOD_NUMBER = Result.ROLL_NO.ToUpper();
                Result.BAR_CODE = Result.ROLL_NO.ToUpper();
                Result.NAME_IN_NATIVE = Convert.ToBase64String(Encoding.UTF8.GetBytes(Result.TAMIL_NAME));
                // Check Update For Student Log ...
                var liAcademicInfo = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new STU_PERSONAL_INFO() { STUDENT_ID = sStudentID },
                    StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAcadamicInfo), sAcademicYear).DataSource.Data;
                if (liAcademicInfo != null)
                {
                    Result.APPLICATION_TYPE = liAcademicInfo.FirstOrDefault().APPTYPE_ID;
                }

                resultArgs = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStupersonalInfoDetails).Replace("?TAMIL_NAME", Result.TAMIL_NAME));
                if (resultArgs.Success)
                {
                    using (StudentViewModel objViewModel = new StudentViewModel())
                    {
                        // Image Updation ....
                        var Rollno = Result.ROLL_NO;
                        if (Request.Files.Count > 0)
                        {
                            var File = Request.Files[0];
                            string ImgName = File.FileName;
                            var Img = ImgName.Split('.');
                            string fileName = ImgName.Replace(Img[0], Result.ROLL_NO);

                            if (!string.IsNullOrEmpty(fileName))
                            {
                                filePath = _sDirectorypath + fileName;
                                sImagePath = "\\" + Common.URLPages.STUDENT_IMGAE_PATH + fileName;
                                File.SaveAs(filePath);
                                Result.PHOTO = sImagePath;

                            }
                            string sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStudentimage).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sStudentID);
                            var UpdatePhoto = CMSHandler.SaveOrUpdate(Result, sSql);
                        }
                        if (resultArgs.Success)
                        {
                            bool updateStuClass = false;
                            var objAccountInfo = new USER_ACCOUNT_INFO();
                            var liAccountInfo = new List<USER_ACCOUNT_INFO>();
                            if (!string.IsNullOrEmpty(AcademicYear))
                            {
                                if (AcademicYear == sAcademicYear)
                                {
                                    updateStuClass = true;
                                }
                                else
                                {
                                    updateStuClass = false;
                                }
                            }
                            else
                            {
                                updateStuClass = true;
                            }
                            if (updateStuClass)
                            {
                                // update Stu_Class ...
                                Result.CLASS_ID = Result.CLASS_ID;
                                Result.ACADEMIC_YEAR = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
                                Result.STUDENT_ID = sStudentID;
                                var result = (List<AcademicDetails>)CMSHandler.FetchData<AcademicDetails>(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuclassByStudentIdAndAcademicYear)).DataSource.Data;
                                if (result != null && result.Count > 0)
                                {
                                    Result.STU_CLASS_ID = result.FirstOrDefault().STU_CLASS_ID;
                                    resultArgs = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuclass));
                                }
                                else
                                {
                                    resultArgs = CMSHandler.SaveOrUpdate(Result, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveStuClass), sAcademicYear);
                                }
                                // Update User  Account ...
                                objAccountInfo.USER_ID = sStudentID;
                                objAccountInfo.EMAIL = Result.STU_EMAILID;
                                objAccountInfo.ACADEMIC_YEAR = sAcademicYear;
                                objAccountInfo.USERNAME = Result.ROLL_NO.ToUpper();
                                objAccountInfo.PASSWORD = CommonMethods.GetSha256FromString(Result.ROLL_NO.ToUpper());
                                objAccountInfo.ROLE = Common.USER_TYPE.STUDENT;
                                objAccountInfo.USER_TYPE = Common.USER_TYPE.STUDENT;
                                objAccountInfo.ROLE_ID = Common.USER_TYPE.STUDENT;
                                objAccountInfo.MOBILE = Result.STU_MOBILENO;
                                objAccountInfo.IS_ACTIVE = Common.IsActiveFalg.IsActive;
                                objAccountInfo.NAME = Result.FIRST_NAME;
                                liAccountInfo = (List<USER_ACCOUNT_INFO>)CMSHandler.FetchData<USER_ACCOUNT_INFO>(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchUserAccountByRoleAndUserId)).DataSource.Data;
                                if (liAccountInfo != null && liAccountInfo.Count > 0)
                                {
                                    objAccountInfo.USER_ACCOUNT_ID = liAccountInfo.FirstOrDefault().USER_ACCOUNT_ID;

                                    resultArgs = CMSHandler.SaveOrUpdate(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.UpdateUserAccountWithoutPassword));
                                }
                                else
                                {
                                    resultArgs = CMSHandler.SaveOrUpdate(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.SaveUserAccount));

                                }
                                var userRoleByACYear = (List<USER_ACCOUNT_INFO>)CMSHandler.FetchData<USER_ACCOUNT_INFO>(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchUserRolebyAcYearRoleAndUserIdAndAcYear)).DataSource.Data;
                                if (userRoleByACYear != null && userRoleByACYear.Count > 0)
                                {
                                }
                                else
                                {
                                    resultArgs = CMSHandler.SaveOrUpdate(objAccountInfo, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.SaveUserRoleByAcademicYear));

                                }
                                sResult = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.NotAcceptable;
                            }
                            else
                            {
                                sResult = (resultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.NotAcceptable;
                            }
                        }
                        else
                        {
                            sResult = Common.ErrorCode.NotAcceptable;
                        }
                        return Json(sResult);
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "EditAcadamicInfo", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("StudentController", "EditAcadamicInfo", ex.Message);
                }
                sResult = Common.ErrorCode.NotAcceptable;
                return Json(sResult);
            }

            return Json(sResult);
        }
        public string DeleteStudentPersonalInfo(string sStudentId, string UserName, string deleteRemark)
        {
            dv.Clear();
            dv.Add(Common.STU_PERSONAL_INFO.STUDENT_ID, sStudentId, EnumCommand.DataType.String);
            dv.Add(Common.STU_PERSONAL_INFO.REMARKS, deleteRemark, EnumCommand.DataType.String);
            dv.Add(Common.STU_PERSONAL_INFO.IS_DELETED, "1", EnumCommand.DataType.String);
            var ObjUserAccount = new USER_ACCOUNT_INFO();
            var liUserAccount = new List<USER_ACCOUNT_INFO>();
            ObjUserAccount.USERNAME = UserName;
            ObjUserAccount.USER_ID = sStudentId;
            liUserAccount = (List<USER_ACCOUNT_INFO>)CMSHandler.FetchData<USER_ACCOUNT_INFO>(ObjUserAccount, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.FetchUserAccountuserUIdAndRole)).DataSource.Data;
            if (liUserAccount != null)
            {
                ObjUserAccount.USER_ACCOUNT_ID = liUserAccount.FirstOrDefault().USER_ACCOUNT_ID;
                resultArgs = CMSHandler.SaveOrUpdate(ObjUserAccount, SQL.UserAccount.UserAccountSQL.GetSupportDataSQL(UserAccountSQLCommands.DeleteUserAccount));
            }

            using (StudentViewModel objViewModel = new StudentViewModel())
            {
                resultArgs = objViewModel.DeleteStudent(dv);
                if (resultArgs.Success)
                {

                    sResult = "Record deleted successfully ...!";
                }
                else
                {
                    sResult = "Record not deleted try again ...!";
                }
            }
            return sResult;
        }
