        public ActionResult ExportStudentDetails(string sAcYear, string sClassID)
        {

            var studentDetails = CMSHandler.FetchData<STU_PERSONAL_INFO>(null, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentDetailsForExport).Replace("?CLASS_ID", sClassID), sAcYear).DataSource.Data as List<STU_PERSONAL_INFO>;
            var csv = new StringBuilder();
            if (studentDetails != null)
            {
                // Add headers
                // CSV header based on the provided database fields
                csv.AppendLine("ROLL_NO,FIRST_NAME,UMIS_NO,ENROLLMENT_NO,DATE_OF_BIRTH,DEPARTMENT,CLASS_NAME,CLASS_LEVEL,PROGRAMME_NAME,ADMISSION_NO,ADMISSION_DATE,BATCH,AADHAR_NUMBER,FR_MOBILE,STU_MOBILENO,GENDER,RELIGION,COMMUNITY,CASTE,BLOOD_GROUP,SPECIALLY_ABLED,FATHER_NAME,MOTHER_NAME,FR_OCCUPATION,MO_OCCUPATION,FR_INCOME,MO_INCOME,ANNUAL_INCOME,IDENTIFICATION_MARK1,IDENTIFICATION_MARK2,STATE_NAME,DISTRICT,CITY,PINCODE,ADDRESS_LINE1,HSS_NO,EX_SERVICE_MAN,HSS_GROUP_CODE,EMIS_NO,STUDY_BOARD,HSS_TOTAL,LAST_SCHOOL_OR_COLLEGE,MEDIUM_STUDY,EXTRA_CURRICULAR,SPORTS,FIRSTGRADUATE,PART_1_LANGUAGE,LAST_STUDIED_UNIVERSITY,YEAR_OF_PASSING,PERCENTAGE,ALLIED_1,ALLIED_2,MAIN_SUBJECT,ACCOUNT_NO,BANK_NAME,BRANCH_NAME,IFSC_CODE");

                // Add data rows
                foreach (var student in studentDetails)
                {
                    csv.AppendLine($"\"{student.ROLL_NO}\",\"{student.FIRST_NAME}\",\"{student.UMIS_NO}\",\"{student.ENROLLMENT_NO}\",\"{student.DATE_OF_BIRTH}\",\"{student.DEPARTMENT}\",\"{student.CLASS_NAME}\",\"{student.CLASS_LEVEL}\",\"{student.PROGRAMME_NAME}\",\"{student.ADMISSION_NO}\",\"{student.ADMISSION_DATE}\",\"{student.BATCH}\",\"{student.AADHAR_NUMBER}\",\"{student.FR_MOBILE}\",\"{student.STU_MOBILENO}\",\"{student.GENDER}\",\"{student.RELIGION}\",\"{student.COMMUNITY}\",\"{student.CASTE}\",\"{student.BLOOD_GROUP}\",\"{student.SPECIALLY_ABLED}\",\"{student.FATHER_NAME}\",\"{student.MOTHER_NAME}\",\"{student.FR_OCCUPATION}\",\"{student.MO_OCCUPATION}\",\"{student.FR_INCOME}\",\"{student.MO_INCOME}\",\"{student.ANNUAL_INCOME}\",\"{student.IDENTIFICATION_MARK1}\",\"{student.IDENTIFICATION_MARK2}\",\"{student.STATE_NAME}\",\"{student.DISTRICT}\",\"{student.CITY}\",\"{student.PINCODE}\",\"{student.ADDRESS_LINE1}\",\"{student.HSS_NO}\",\"{student.EX_SERVICE_MAN}\",\"{student.HSS_GROUP_CODE}\",\"{student.EMIS_NO}\",\"{student.STUDY_BOARD}\",\"{student.HSS_TOTAL}\",\"{student.LAST_SCHOOL_OR_COLLEGE}\",\"{student.MEDIUM_STUDY}\",\"{student.EXTRA_CURRRICULAR}\",\"{student.SPORTS}\",\"{student.FIRSTGRADUATE}\",\"{student.PART_1_LANGUAGE}\",\"{student.LAST_STUDIED_UNIVERSITY}\",\"{student.YEAR_OF_PASSING}\",\"{student.PERCENTAGE}\",\"{student.ALLIED_1}\",\"{student.ALLIED_2}\",\"{student.MAIN_SUBJECT}\",\"{student.ACCOUNT_NO}\",\"{student.BANK_NAME}\",\"{student.BRANCH_NAME}\",\"{student.IFSC_CODE}\"");
                }
                byte[] byteOrderMarkUtf8 = new byte[] { 0xEF, 0xBB, 0xBF };
                byte[] csvBytes = Encoding.UTF8.GetBytes(csv.ToString());
                byte[] csvWithBom = byteOrderMarkUtf8.Concat(csvBytes).ToArray();
            }
            return File(new UTF8Encoding().GetBytes(csv.ToString()), "text/csv", "StudentList.csv");
        }

        [HttpPost]
        public JsonResult GetStudentDetailsForDynamicReport(string sAcYear, string sClassIDs)
        {
            var ObjJsoneData = new JsonResultData();
            try
            {
                if (string.IsNullOrEmpty(sAcYear) || string.IsNullOrEmpty(sClassIDs))
                {
                    ObjJsoneData.ErrorCode = Common.ErrorCode.BadRequest;
                    ObjJsoneData.Message = "Required parameters are missing.";
                    var r = Json(ObjJsoneData, JsonRequestBehavior.AllowGet);
                    r.MaxJsonLength = int.MaxValue;
                    return r;
                }

                var liStudent = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(
                    null,
                    StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentDetailsForExport).Replace("?CLASS_ID", sClassIDs),
                    sAcYear
                ).DataSource.Data;

                if (liStudent != null && liStudent.Count > 0)
                {
                    var r = Json(new { ErrorCode = "Ok", Data = liStudent }, JsonRequestBehavior.AllowGet);
                    r.MaxJsonLength = int.MaxValue;
                    return r;
                }
                else
                {
                    ObjJsoneData.ErrorCode = Common.ErrorCode.NotFound;
                    ObjJsoneData.Message = "No student details found for the selected classes.";
                    var r = Json(ObjJsoneData, JsonRequestBehavior.AllowGet);
                    r.MaxJsonLength = int.MaxValue;
                    return r;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("StudentController", "GetStudentDetailsForDynamicReport", ex.Message);
                }
                ObjJsoneData.ErrorCode = Common.ErrorCode.InternalServerError;
                ObjJsoneData.Message = "Error fetching details: " + ex.Message;
                var r = Json(ObjJsoneData, JsonRequestBehavior.AllowGet);
                r.MaxJsonLength = int.MaxValue;
                return r;
            }
        }

        [HttpPost]
        public ActionResult ExportClassWiseDetails(string sAcYear, string sClassIDs, string sFields, string sHeaders)
        {
            var ObjJsoneData = new JsonResultData();
            try
            {
                if (string.IsNullOrEmpty(sAcYear) || string.IsNullOrEmpty(sClassIDs) || string.IsNullOrEmpty(sFields))
                {
                    ObjJsoneData.ErrorCode = Common.ErrorCode.BadRequest;
                    ObjJsoneData.Message = "Required parameters are missing.";
                    return Json(ObjJsoneData, JsonRequestBehavior.AllowGet);
                }

                string[] classIds = sClassIDs.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                string[] selectedFields = sFields.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);

                if (classIds.Length == 0 || selectedFields.Length == 0)
                {
                    ObjJsoneData.ErrorCode = Common.ErrorCode.BadRequest;
                    ObjJsoneData.Message = "Please select at least one class and one field.";
                    return Json(ObjJsoneData, JsonRequestBehavior.AllowGet);
                }

                // Get Desktop Path
                string desktopPath = Environment.GetFolderPath(Environment.SpecialFolder.Desktop);
                string folderName = "StudentDetails_ClassWise_" + DateTime.Now.ToString("yyyyMMdd_HHmmss");
                string folderPath = Path.Combine(desktopPath, folderName);

                Directory.CreateDirectory(folderPath);

                // Map column display names (headers)
                var fieldHeaders = new Dictionary<string, string>
                {
                    { "ROLL_NO", "Roll No" },
                    { "FIRST_NAME", "First Name" },
                    { "UMIS_NO", "UMIS No" },
                    { "ENROLLMENT_NO", "Enrollment No" },
                    { "DATE_OF_BIRTH", "Date Of Birth" },
                    { "DEPARTMENT", "Department" },
                    { "CLASS_NAME", "Class Name" },
                    { "CLASS_LEVEL", "Class Level" },
                    { "PROGRAMME_NAME", "Programme Name" },
                    { "ADMISSION_NO", "Admission No" },
                    { "ADMISSION_DATE", "Admission Date" },
                    { "BATCH", "Batch" },
                    { "AADHAR_NUMBER", "Aadhar Number" },
                    { "FR_MOBILE", "Father Mobile" },
                    { "STU_MOBILENO", "Student Mobile No" },
                    { "GENDER", "Gender" },
                    { "RELIGION", "Religion" },
                    { "COMMUNITY", "Community" },
                    { "CASTE", "Caste" },
                    { "BLOOD_GROUP", "Blood Group" },
                    { "SPECIALLY_ABLED", "Specially Abled" },
                    { "FATHER_NAME", "Father Name" },
                    { "MOTHER_NAME", "Mother Name" },
                    { "FR_OCCUPATION", "Father Occupation" },
                    { "MO_OCCUPATION", "Mother Occupation" },
                    { "FR_INCOME", "Father Income" },
                    { "MO_INCOME", "Mother Income" },
                    { "ANNUAL_INCOME", "Annual Income" },
                    { "IDENTIFICATION_MARK1", "Identification Mark 1" },
                    { "IDENTIFICATION_MARK2", "Identification Mark 2" },
                    { "STATE_NAME", "State Name" },
                    { "DISTRICT", "District" },
                    { "CITY", "City" },
                    { "PINCODE", "Pincode" },
                    { "ADDRESS_LINE1", "Address" },
                    { "HSS_NO", "HSS No" },
                    { "EX_SERVICE_MAN", "Ex Service Man" },
                    { "HSS_GROUP_CODE", "HSS Group Code" },
                    { "EMIS_NO", "EMIS No" },
                    { "STUDY_BOARD", "Study Board" },
                    { "HSS_TOTAL", "HSS Total" },
                    { "LAST_SCHOOL_OR_COLLEGE", "Last School/College" },
                    { "MEDIUM_STUDY", "Medium of Study" },
                    { "EXTRA_CURRRICULAR", "Extra Curricular" },
                    { "SPORTS", "Sports" },
                    { "FIRSTGRADUATE", "First Graduate" },
                    { "PART_1_LANGUAGE", "Part 1 Language" },
                    { "LAST_STUDIED_UNIVERSITY", "Last Studied University" },
                    { "YEAR_OF_PASSING", "Year of Passing" },
                    { "PERCENTAGE", "Percentage" },
                    { "ALLIED_1", "Allied 1" },
                    { "ALLIED_2", "Allied 2" },
                    { "MAIN_SUBJECT", "Main Subject" },
                    { "ACCOUNT_NO", "Account No" },
                    { "BANK_NAME", "Bank Name" },
                    { "BRANCH_NAME", "Branch Name" },
                    { "IFSC_CODE", "IFSC Code" },
                    { "GSUITE_MAIL_ID", "College Email" },
                    { "STU_EMAILID", "Student Email" }
                };

                int exportCount = 0;

                foreach (var classId in classIds)
                {
                    var studentDetails = CMSHandler.FetchData<STU_PERSONAL_INFO>(
                        null,
                        StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentDetailsForExport).Replace("?CLASS_ID", classId),
                        sAcYear
                    ).DataSource.Data as List<STU_PERSONAL_INFO>;

                    if (studentDetails != null && studentDetails.Count > 0)
                    {
                        // Determine sanitized class name for filename
                        string rawClassName = studentDetails.First().CLASS_NAME ?? ("Class_" + classId);
                        string fileName = rawClassName;
                        foreach (char c in Path.GetInvalidFileNameChars())
                        {
                            fileName = fileName.Replace(c, '_');
                        }

                        var csv = new StringBuilder();

                        // Add header row
                        var headerRow = new List<string>();
                        string[] customHeaders = !string.IsNullOrEmpty(sHeaders) ? sHeaders.Split('|') : null;

                        for (int i = 0; i < selectedFields.Length; i++)
                        {
                            if (customHeaders != null && i < customHeaders.Length)
                            {
                                headerRow.Add(customHeaders[i]);
                            }
                            else
                            {
                                string field = selectedFields[i];
                                if (field.StartsWith("EMPTY_COLUMN_"))
                                {
                                    headerRow.Add("Empty Column");
                                }
                                else
                                {
                                    headerRow.Add(fieldHeaders.ContainsKey(field) ? fieldHeaders[field] : field);
                                }
                            }
                        }
                        csv.AppendLine(string.Join(",", headerRow.Select(h => $"\"{h.Replace("\"", "\"\"")}\"")));

                        // Add data rows
                        foreach (var student in studentDetails)
                        {
                            var dataRow = new List<string>();
                            foreach (var field in selectedFields)
                            {
                                if (field.StartsWith("EMPTY_COLUMN_"))
                                {
                                    dataRow.Add("\"\"");
                                }
                                else
                                {
                                    var prop = typeof(STU_PERSONAL_INFO).GetProperty(field);
                                    string val = prop != null ? Convert.ToString(prop.GetValue(student, null)) : "";
                                    if (!string.IsNullOrEmpty(val))
                                    {
                                        val = val.Replace("\"", "\"\"");
                                    }
                                    dataRow.Add($"\"{val}\"");
                                }
                            }
                            csv.AppendLine(string.Join(",", dataRow));
                        }

                        // Write file to Desktop folder
                        string filePath = Path.Combine(folderPath, fileName + ".csv");

                        // Include UTF-8 BOM so Excel opens it with proper encoding
                        byte[] byteOrderMarkUtf8 = new byte[] { 0xEF, 0xBB, 0xBF };
                        byte[] csvBytes = Encoding.UTF8.GetBytes(csv.ToString());
                        byte[] csvWithBom = byteOrderMarkUtf8.Concat(csvBytes).ToArray();

                        System.IO.File.WriteAllBytes(filePath, csvWithBom);
                        exportCount++;
                    }
                }

                if (exportCount > 0)
                {
                    ObjJsoneData.ErrorCode = Common.ErrorCode.Ok;
                    ObjJsoneData.Message = $"Successfully exported {exportCount} class-wise Excel files to Desktop folder: {folderName}";
                }
                else
                {
                    ObjJsoneData.ErrorCode = Common.ErrorCode.NotFound;
                    ObjJsoneData.Message = "No student details found for the selected classes.";
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("StudentController", "ExportClassWiseDetails", ex.Message);
                }
                ObjJsoneData.ErrorCode = Common.ErrorCode.InternalServerError;
                ObjJsoneData.Message = "Error during export: " + ex.Message;
            }

            return Json(ObjJsoneData, JsonRequestBehavior.AllowGet);
        }
