        public JsonResult BindCourseCompletionCertificate(string sClassId, string sProgramId, string sAcademicYear, string fromdate, string todate, string behave, string sstuname, string sShift, string classyear, string certdate)
        {
            if (string.IsNullOrEmpty(sstuname))
            {
                return Json(new { Message = "Invalid Input" }, JsonRequestBehavior.AllowGet);
            }

            try
            {
                // Initialize the list to store student data
                List<CERTIFICATE_STU_INFO> studentModels = new List<CERTIFICATE_STU_INFO>();

                // Get SQL query and fetch student data
                string sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentInfoForCourseComCertificate)
                    .Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sstuname);
                var liStudent = DapperHandler.FetchAll<STU_PERSONAL_INFO>(sSql, null, sAcademicYear);

                // Populate studentModels list with data
                foreach (var item in liStudent)
                {
                    studentModels.Add(new CERTIFICATE_STU_INFO
                    {
                        FIRST_NAME = item.FIRST_NAME,
                        ROLL_NO = item.ROLL_NO,
                        CLASS_NAME = item.CLASS_NAME,
                        PROGRAMME_NAME = item.PROGRAMME_NAME,
                        ACADEMIC_YEAR = item.ACADEMIC_YEAR,
                        BATCH = item.BATCH,
                        FROM_DATE = item.ADMISSION_DATE,
                        TO_DATE = item.LEAVING_DATE,
                        BEHAVE = behave,
                        GENDER = item.GENDER
                    });
                }

                // Print certificates for all students
                if (studentModels.Count > 0)
                {
                    PrintConductCertificatePrint(studentModels, sAcademicYear, sShift, classyear, certdate);
                    string pdfFileName = $"{studentModels.First().CLASS_NAME}.pdf";

                    return Json(new { Message = "Success", pdfFileName }, JsonRequestBehavior.AllowGet);
                }
                else
                {
                    return Json(new { Message = "No Data Found" }, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
                return Json(new { Message = "Error", Detail = ex.Message }, JsonRequestBehavior.AllowGet);
            }
        }
        private double ConCenterX(XGraphics graph, string text, XFont font, double startX, double availableWidth)
        {
            double textWidth = graph.MeasureString(text, font).Width;
            return startX + (availableWidth - textWidth) / 2; // Centering calculation
        }
        private double CenterX(XGraphics graph, string text, XFont font, double startX, double availableWidth)
        {
            double textWidth = graph.MeasureString(text, font).Width;
            return startX + (availableWidth - textWidth) / 2; // Centering calculation
        }


        private void PrintConductCertificatePrint(List<CERTIFICATE_STU_INFO> studentModels, string sAcademicYear, string sShift, string classyear, string certdate)
        {
            string sRootPath = AppDomain.CurrentDomain.BaseDirectory;

            PdfDocument pdf = new PdfDocument();
            pdf.Info.Title = "Course Completion Certificates";

            const double pageWidth = 1008;
            const double pageHeight = 612;
            const double halfPageHeight = pageHeight / 2;
            var current_date = DateTime.Now.ToString("yyyy-mm-dd_h_m", CultureInfo.InvariantCulture);
            PdfPage pdfPage = null;
            XGraphics graph = null;
            var liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCollegeDetail)).DataSource.Data;

            for (int i = 0; i < studentModels.Count; i++)
            {
                // Add a new page for the first student or every two students
                if (i % 2 == 0)
                {
                    pdfPage = pdf.AddPage();
                    pdfPage.Orientation = PageOrientation.Landscape;
                    pdfPage.Width = pageWidth;
                    pdfPage.Height = pageHeight;
                    graph = XGraphics.FromPdfPage(pdfPage);
                    XPen dashedPen = new XPen(XColors.Gray, 1);
                    dashedPen.DashStyle = XDashStyle.Dash;
                    graph.DrawLine(dashedPen, pageWidth / 2, 0, pageWidth / 2, pageHeight);
                }
                string CertificateDate = !string.IsNullOrEmpty(certdate) ? certdate : DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);

                var student = studentModels[i];
                double yOffset = 0; // Always start at the top
                double xOffset3 = (i % 2 == 0) ? 30 : 535; // Left for even indices, right for odd
                double xOffset2 = (i % 2 == 0) ? 20 : 525; // Left for even indices, right for odd
                double xOffset = (i % 2 == 0) ? 40 : 545; // Left for even indices, right for odd

                // Fonts
                XFont CertificateName = new XFont("Times New Roman", 15, XFontStyle.Bold);
                XFont titleFont = new XFont("Times New Roman", 13, XFontStyle.Bold);
                XFont title = new XFont("Times New Roman", 12, XFontStyle.Bold);
                XFont fontRegularSm = new XFont("Times New Roman", 10, XFontStyle.Regular);
                XFont fontRegular = new XFont("Times New Roman", 13, XFontStyle.Regular);
                XFont fontBold = new XFont("Times New Roman", 12, XFontStyle.Bold);

                var GenderH = student.GENDER == "1" ? "his" : "her";
                // Draw the certificate content

                // Header section (Center aligned for both halves)
                double headerCenterX = xOffset + 240; // Approximate center for each certificate section

                if (liCollegeDetails != null && liCollegeDetails.Count > 0)
                {
                    graph.DrawImage(XImage.FromFile(Path.Combine(sRootPath, "Content", "hcc_img", "College_logo_bg_remove.png")), xOffset + 20, 33 + yOffset, 65, 80);
                    graph.DrawString($"{liCollegeDetails.FirstOrDefault().COLLEGE_NAME}", titleFont, XBrushes.Black, new XPoint(CenterX(graph, $"{liCollegeDetails.FirstOrDefault().COLLEGE_NAME}", titleFont, xOffset, 500), 25 + yOffset));
                    graph.DrawString("(Autonomous)", fontBold, XBrushes.Black, new XPoint(CenterX(graph, "(Autonomous)", fontBold, xOffset, 500), 40 + yOffset));
                    graph.DrawString($"{liCollegeDetails.FirstOrDefault().GRADE}", fontRegularSm, XBrushes.Black, new XPoint(CenterX(graph, $"{liCollegeDetails.FirstOrDefault().GRADE}", fontRegularSm, xOffset, 500), 55 + yOffset));
                    graph.DrawString($"{liCollegeDetails.FirstOrDefault().UNIVERSITY}", fontRegularSm, XBrushes.Black, new XPoint(CenterX(graph, $"{liCollegeDetails.FirstOrDefault().UNIVERSITY}", fontRegularSm, xOffset, 500), 70 + yOffset));
                    graph.DrawString($"{liCollegeDetails.FirstOrDefault().COLLEGE_ADDRESS}", fontRegularSm, XBrushes.Black, new XPoint(CenterX(graph, $"{liCollegeDetails.FirstOrDefault().COLLEGE_ADDRESS}", fontRegularSm, xOffset, 500), 85 + yOffset));
                }
                else
                {
                    graph.DrawImage(XImage.FromFile(Path.Combine(sRootPath, "Content", "hcc_img", "College_logo_bg_remove.png")), xOffset + 20, 33 + yOffset, 65, 80);
                    graph.DrawString("ST. JOSEPH'S COLLEGE OF ARTS AND SCIENCE", titleFont, XBrushes.Black, new XPoint(CenterX(graph, "ST. JOSEPH'S COLLEGE OF ARTS AND SCIENCE", titleFont, xOffset, 500), 25 + yOffset));
                    graph.DrawString("(Autonomous)", fontBold, XBrushes.Black, new XPoint(CenterX(graph, "(Autonomous)", fontBold, xOffset, 500), 40 + yOffset));
                    graph.DrawString("Re-Accredited by NAAC with 'A' Grade (4th Cycle)", fontRegularSm, XBrushes.Black, new XPoint(CenterX(graph, "Re-Accredited by NAAC with 'A' Grade (4th Cycle)", fontRegularSm, xOffset, 500), 55 + yOffset));
                    graph.DrawString("Affiliated to Annamalai University", fontRegularSm, XBrushes.Black, new XPoint(CenterX(graph, "Affiliated to Annamalai University", fontRegularSm, xOffset, 500), 70 + yOffset));
                    graph.DrawString("Cuddalore - 607 001", fontRegularSm, XBrushes.Black, new XPoint(CenterX(graph, "Cuddalore - 607 001", fontRegularSm, xOffset, 500), 85 + yOffset));

                }


                // Certificate Title
                graph.DrawString("COURSE COMPLETION CERTIFICATE", titleFont, XBrushes.Black, new XPoint(CenterX(graph, "COURSE COMPLETION CERTIFICATE", titleFont, xOffset, 500), 130 + yOffset));



                //graph.DrawString("COURSE COMPLETION CERTIFICATE", CertificateName, XBrushes.Black, new XPoint(xOffset + 50, 160 + yOffset));

                string certifyText = "This is to certify that";
                double certifyTextWidth = graph.MeasureString(certifyText, fontRegular).Width;

                graph.DrawString($"{certifyText}", fontRegular, XBrushes.Black, new XPoint(xOffset + 40, 170 + yOffset));
                graph.DrawString($"{student.FIRST_NAME}", fontBold, XBrushes.Black, new XPoint(xOffset + 45 + certifyTextWidth, 169 + yOffset));

                graph.DrawString($"Roll No ................................................................ has completed {GenderH} course in ", fontRegular, XBrushes.Black, new XPoint(xOffset, 200 + yOffset));

