        #region No due Form for student
        public ActionResult FetchNodueCertificateForStudent()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            int totalAbsentCount = 0;
            int DayCount = 0;
            var sPercentageRound = "";
            StudentViewModel objmodel = new StudentViewModel();
            try
            {
                // Initialize the list to store student data

                objmodel.liNodueDefaulters = (List<STU_NODUE_DEFAULTERS>)CMSHandler.FetchData<STU_NODUE_DEFAULTERS>(null, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchNoDueDefaultersForValidation).Replace("?STUDENT_ID", sUserId), sAcademicYear).DataSource.Data;
                if (objmodel.liNodueDefaulters != null && objmodel.liNodueDefaulters.Count > 0)
                {
                    return View(objmodel);
                }
                else
                {
                    List<CERTIFICATE_STU_INFO> studentModels = new List<CERTIFICATE_STU_INFO>();
                    var fetchAcademicsem = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null, SQL.Attendance.AttendanceSQL.GetAttendanceSQL(AttendanceSQLCommands.FetchSemesterEndDate).Replace("?STUDENT_ID", sUserId), sAcademicYear).DataSource.Data;
                    if (fetchAcademicsem != null)
                    {
                        var endDateString = fetchAcademicsem.FirstOrDefault().DATE_TO;

                        var currentDate = DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);
                        var endDate = DateTime.ParseExact(endDateString, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                        var currentDateParsed = DateTime.ParseExact(currentDate, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                        List<ATT_ATTENDANCE_REPORT> AttendanceReport = null;
                        if (endDate > currentDateParsed)
                        {
                            AttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAttendancePercentageForNoDue)
                                    .Replace("?STUDENT_ID", sUserId).Replace("?ENDDATE", "curdate()"), sAcademicYear).DataSource.Data;
                        }
                        else
                        {
                            AttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                    SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAttendancePercentageForNoDue)
                                        .Replace("?STUDENT_ID", sUserId).Replace("?ENDDATE", "ASM.DATE_TO"), sAcademicYear).DataSource.Data;
                        }
                        if (AttendanceReport != null)
                        {
                            totalAbsentCount = Convert.ToInt32(AttendanceReport.FirstOrDefault().ABSENT_COUNT);
                            DayCount = Convert.ToInt32(AttendanceReport.FirstOrDefault().DAYS_COUNT);
                            var sPresentCount = Convert.ToDouble(DayCount) - Convert.ToInt32(totalAbsentCount);
                            var Percentage = Convert.ToDouble(sPresentCount) / Convert.ToDouble(DayCount) * 100;
                            sPercentageRound = Convert.ToString(Math.Round(Percentage, 2));
                        }
                    }
                    string sSql = SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentInfoForNoDUeFormNew)
                        .Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId);
                    var liStudent = DapperHandler.FetchAll<CERTIFICATE_STU_INFO>(sSql, null, sAcademicYear);
                    ViewBag.stuid = liStudent.FirstOrDefault().STUDENT_ID;

                    if (liStudent != null)
                    {
                        foreach (var item in liStudent)
                        {
                            studentModels.Add(new CERTIFICATE_STU_INFO
                            {
                                FIRST_NAME = item.FIRST_NAME,
                                ROLL_NO = item.ROLL_NO,
                                DEPARTMENT = item.DEPARTMENT,
                                ACADEMIC_YEAR = item.ACADEMIC_YEAR,
                                BATCH = item.BATCH,
                                STUDENT_ID = item.STUDENT_ID,
                                COLLEGE_FEE = item.COLLEGE_FEE,
                                HOSTELFEEDUE = item.HOSTELFEEDUE,
                                BUSFEEDUE = item.BUSFEEDUE,
                                EXAMFEEDUE = item.EXAMFEEDUE,
                                ATTPERCENTAGE = sPercentageRound,
                                HOSTEL_ID = item.HOSTEL_ID,

                            });
                        }
                    }
                    PrintNodueForm(studentModels);
                }
            }
            catch (Exception ex)
            {
                return Json(new { Message = "Error", Detail = ex.Message }, JsonRequestBehavior.AllowGet);
            }
            return View(objmodel);
        }
        private double NoDueFormCenterX(XGraphics graph, string text, XFont font, double startX, double availableWidth)
        {
            double textWidth = graph.MeasureString(text, font).Width;
            return startX + (availableWidth - textWidth) / 2; // Centering calculation
        }
        private void PrintNodueForm(List<CERTIFICATE_STU_INFO> studentModels)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;

            string sRootPath = AppDomain.CurrentDomain.BaseDirectory;

            PdfDocument pdf = new PdfDocument();
            pdf.Info.Title = "NO DUES FORM ";
            const double pageWidth = 612;
            const double pageHeight = 908;
            const double halfPageHeight = pageHeight / 2;
            var liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCollegeDetail)).DataSource.Data;

            PdfPage pdfPage = null;
            XGraphics graph = null;

            for (int i = 0; i < studentModels.Count; i++)
            {
                // Add a new page for the first student or every two students
                if (i % 2 == 0)
                {
                    pdfPage = pdf.AddPage();
                    pdfPage.Orientation = PageOrientation.Landscape;
                    pdfPage.Width = pageWidth;
                    pdfPage.Height = pageHeight;
                    graph = XGraphics.FromPdfPage(pdfPage);
                }
                string dte = DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);
                var student = studentModels[i];
                double yOffset = 10; // Always start at the top
                double xOffset3 = (i % 2 == 0) ? 50 : 535; // Left for even indices, right for odd
                double xOffset2 = (i % 2 == 0) ? 40 : 525; // Left for even indices, right for odd
                double xOffset = (i % 2 == 0) ? 60 : 545; // Left for even indices, right for odd
                int collegeFee = 0;
                if (!string.IsNullOrEmpty(student.COLLEGE_FEE))
                {
                    double dVal;
                    if (double.TryParse(student.COLLEGE_FEE, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out dVal))
                    {
                        collegeFee = (int)Math.Round(dVal);
                    }
                }

                int BusFee = 0;
                if (!string.IsNullOrEmpty(student.BUSFEEDUE))
                {
                    double dVal;
                    if (double.TryParse(student.BUSFEEDUE, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out dVal))
                    {
                        BusFee = (int)Math.Round(dVal);
                    }
                }

                int HostelFee = 0;
                if (!string.IsNullOrEmpty(student.HOSTELFEEDUE))
                {
                    double dVal;
                    if (double.TryParse(student.HOSTELFEEDUE, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out dVal))
                    {
                        HostelFee = (int)Math.Round(dVal);
                    }
                }

                int examFee = 0;
                if (!string.IsNullOrEmpty(student.EXAMFEEDUE))
                {
                    double dVal;
                    if (double.TryParse(student.EXAMFEEDUE, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out dVal))
                    {
                        examFee = (int)Math.Round(dVal);
                    }
                }
                string AttPercentage = student.ATTPERCENTAGE;
                string hostelname = string.Empty;
                if (student.HOSTEL_ID == "1")
                {
                    hostelname = "(Boys)";
                }
                else if (student.HOSTEL_ID == "2")
                {
                    hostelname = "(Girls)";
                }
                else
                {
                    hostelname = "";
                }
                // Fonts
                XFont AttendanceName = new XFont("Times New Roman", 15, XFontStyle.Bold);
                XFont titleFont = new XFont("Times New Roman", 18, XFontStyle.Bold);
                XFont title = new XFont("Times New Roman", 12, XFontStyle.Regular);
                XFont titleUnderline = new XFont("Times New Roman", 17, XFontStyle.Bold);
                XFont font = new XFont("Times New Roman", 10, XFontStyle.Regular);
                XFont BodyContent = new XFont("Times New Roman", 14, XFontStyle.Regular);
