        public JsonResult AddRejoinStudent(string sJsonData)
        {
            ResultArgs resultArgs = new ResultArgs();
            var objResultData = new JsonResultData();
            string UserID = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sSemesterType = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_TYPE] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_TYPE].ToString() : string.Empty;
            string filePath = string.Empty;
            string sImagePath = string.Empty;
            string _sDirectorypath = string.Empty;
            var objAccountInfo = new USER_ACCOUNT_INFO();
            try
            {
                if (!string.IsNullOrEmpty(sAcademicYear))
                {
                    var result = JsonConvert.DeserializeObject<STU_REJOIN>(sJsonData);
                    if (result != null)
                    {
                        var checkRollNoExist = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new STU_PERSONAL_INFO() { STUDENT_ID = result.STUDENT_ID, ROLL_NO = result.ROLL_NO }, StudentSQL.GetStudentSQL(StudentSQLCommads.CheckNewRollNoExistorNot), sAcademicYear).DataSource.Data;
                        if (checkRollNoExist == null)
                        {
                            var FetchBatch = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new STU_PERSONAL_INFO() { ROLL_NO = result.OLD_ROLL_NO }, StudentSQL.GetStudentSQL(StudentSQLCommads.CheckRollNoExist), sAcademicYear).DataSource.Data;
                            if (FetchBatch != null)
                            {
                                result.ENTRY_ID = UserID;
                                result.RFID = result.ROLL_NO;
                                result.BIOD_NUMBER = result.ROLL_NO;
                                result.BAR_CODE = result.ROLL_NO;
                                objAccountInfo.USERNAME = result.ROLL_NO.ToUpper();
                                objAccountInfo.PASSWORD = CommonMethods.GetSha256FromString(result.ROLL_NO.ToUpper());
                                objAccountInfo.ROLE = Common.USER_TYPE.STUDENT;
                                objAccountInfo.USER_TYPE = Common.USER_TYPE.STUDENT;
                                objAccountInfo.ROLE_ID = Common.USER_TYPE.STUDENT;
                                objAccountInfo.USER_ID = result.STUDENT_ID;
                                objAccountInfo.NAME = FetchBatch.FirstOrDefault().FIRST_NAME;
                                objAccountInfo.ACADEMIC_YEAR = result.ACADEMIC_YEAR;
                                result.BATCH = FetchBatch.FirstOrDefault().BATCH;
                                if (!string.IsNullOrEmpty(result.STUDENT_ID))
                                {
                                    resultArgs = CMSHandler.SaveOrUpdate(result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuPersonalInfoForLeftStudent), sAcademicYear);
                                    if (resultArgs.Success)
                                    {
                                        var FetchClassId = (List<CP_CLASSES>)CMSHandler.FetchData<CP_CLASSES>(new CP_CLASSES() { CLASS_ID = result.CLASS_ID }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchClassbyClassId), sAcademicYear).DataSource.Data;
                                        if (FetchClassId != null)
                                        {
                                            result.PROGRAMME_GROUP_ID = FetchClassId.FirstOrDefault().PROGRAMME_GROUP_ID;

                                            var saveRejoinStudent = CMSHandler.SaveOrUpdate(result, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveRejoinStudentDetails), sAcademicYear);
                                            if (saveRejoinStudent.Success)
                                            {
                                                var FetchAcademicSemester = (List<ACADEMIC_SEMESTER>)CMSHandler.FetchData<ACADEMIC_SEMESTER>(new ACADEMIC_SEMESTER() { SEMESTER = result.SEMESTER, PROGRAMME_GROUP_ID = result.PROGRAMME_GROUP_ID, ACADEMIC_YEAR = result.ACADEMIC_YEAR, BATCH = result.BATCH }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAcademicSemester), sAcademicYear).DataSource.Data;

                                                if (FetchAcademicSemester == null)
                                                {
                                                    var insertAcademicSemester = CMSHandler.SaveOrUpdate(result, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveAcademicSemester));

                                                }
                                                var fetchStuClass = (List<STU_CLASS>)CMSHandler.FetchData<STU_CLASS>(new STU_CLASS() { STUDENT_ID = result.STUDENT_ID, PROGRAMME_GROUP_ID = result.PROGRAMME_GROUP_ID, ACADEMIC_YEAR = result.ACADEMIC_YEAR, BATCH = result.BATCH }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuClass), sAcademicYear).DataSource.Data;
                                                if (fetchStuClass != null)
                                                {
                                                    result.STU_CLASS_ID = fetchStuClass.FirstOrDefault().STU_CLASS_ID;
                                                    var UpadateStuClass = CMSHandler.SaveOrUpdate(result, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuclass), sAcademicYear);

                                                }
                                                else
                                                {
                                                    var saveStuclass = CMSHandler.SaveOrUpdate(result, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveStuClass), sAcademicYear);

                                                }
                                                objResultData.Message = resultArgs.Success ? Common.Messages.RecordsUpdatedSuccessfully : Common.Messages.FailedToUpdatedRecords;
                                                objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                                                var FetchUserAccount = (List<USER_ACCOUNT>)CMSHandler.FetchData<USER_ACCOUNT>(new USER_ACCOUNT() { USER_ID = result.STUDENT_ID }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchUserAccountDetails), sAcademicYear).DataSource.Data;
                                                if (FetchUserAccount != null && FetchUserAccount.Count > 0)
                                                {
                                                    objAccountInfo.USER_ACCOUNT_ID = FetchUserAccount.FirstOrDefault().USER_ACCOUNT_ID;
                                                    var UpdateUserAccount = CMSHandler.SaveOrUpdate(objAccountInfo, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateUserAccount));
                                                    resultArgs = CMSHandler.SaveOrUpdate(objAccountInfo, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateUserAccount));
                                                    if (UpdateUserAccount.Success)
                                                    {
                                                        var InsertUserRolebyAcYear = CMSHandler.SaveOrUpdate(objAccountInfo, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveUserRoleByAcademicYear));

                                                    }
                                                }
                                                else
                                                {

                                                    var InsertUserAccount = CMSHandler.SaveOrUpdate(objAccountInfo, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveUserAccount));
                                                    if (InsertUserAccount.Success)
                                                    {
                                                        var InsertUserRolebyAcYear = CMSHandler.SaveOrUpdate(objAccountInfo, StudentSQL.GetStudentSQL(StudentSQLCommads.SaveUserRoleByAcademicYear));

                                                    }

                                                }
                                            }
                                        }
                                    }


                                }
                            }
                            else
                            {
                                objResultData.Message = "Check Your Input and Try Again";
                                objResultData.ErrorCode = resultArgs.Success ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                                return Json(objResultData, JsonRequestBehavior.AllowGet);

                            }
                        }
                        else
                        {
                            objResultData.Message = "Given Roll No Already Exist ";
                            objResultData.ErrorCode = Common.ErrorCode.NotAcceptable;
                            return Json(objResultData, JsonRequestBehavior.AllowGet);

                        }
                    }
                }
                else
                {
                    ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("StudentController", "AddRejoinStudent", ex.Message);
                }

                objResultData.Message = ex.Message;
                objResultData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }


            if (string.IsNullOrEmpty(objResultData.Message))
            {
                objResultData.Message = "No Changes Made";
                objResultData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(objResultData, JsonRequestBehavior.AllowGet);
        }
        #endregion

