            {
                var fetchAcademicsem = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null, SQL.Attendance.AttendanceSQL.GetAttendanceSQL(AttendanceSQLCommands.FetchSemesterEndDatebyProgramme).Replace("?PROGRAMME_GROUP_ID", sProgramId), sAcademicYear).DataSource.Data;
                if (fetchAcademicsem != null)
                {
                    var endDateString = fetchAcademicsem.FirstOrDefault().DATE_TO;

                    var currentDate = DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);
                    var endDate = DateTime.ParseExact(endDateString, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                    var currentDateParsed = DateTime.ParseExact(currentDate, "dd/MM/yyyy", CultureInfo.InvariantCulture);

                    if (endDate > currentDateParsed)
                    {
                        objViewModel.liAttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                            SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuAttendanceReportParentMeet).Replace("?ENDDATE", "curdate()").Replace("?CLASS_ID", sClassId), sAcademicYear).DataSource.Data;
                    }
                    else
                    {
                        objViewModel.liAttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuAttendanceReportParentMeet).Replace("?ENDDATE", "ASM.DATE_TO").Replace("?CLASS_ID", sClassId),

                                sAcademicYear
                            ).DataSource.Data;
                    }
                }
                if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
                {
                    // objModel.PROGRAMME_GROUP_ID = sProgrammeGroupId;
                    objModel.CLASS_ID = sClassId;
