                    {
                        objViewModel.liFeeDueReport = (List<FEE_STUDENT_DUE>)CMSHandler.FetchData<FEE_STUDENT_DUE>(objModel, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentFeeDueDetailsForMeet).Replace("?CLASS_ID", sClassId), sAcademicYear).DataSource.Data;
