                    objHandler.WriteError("BindStudentsByAcademicYearAndClassId", "Fee", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("BindStudentsByAcademicYearAndClassId", "Fee", ex.Message);
                }
            }
            return View(objViewModel);
