                sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.Fetchstatsselected).Replace(Common.Delimiter.QUS + Common.CP_PROGRAMME_2017.PROGRAMME_GROUP_ID, sProgramme).Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.CLASS_YEAR, sClassyear).Replace(Common.Delimiter.QUS + Common.CP_CLASSES_2017.SELECTED_FIELD, sfields);
                var EMPFIELD = $"{sfieldname}";
                var liStats = DapperHandler.FetchAll<STATS_MODEL>(sSql, new { IS_LEFT = sincludeleft, EMPTY_FIELD = semptyfields, CLASS_LEVEL = sclasslevel, SELECTED_NAME = EMPFIELD }, sAcademicyear);
                ObjViewModel.liStats = liStats;
            }
            return View(ObjViewModel);
        }

