                        objViewModel.liFeeDueReport = (List<FEE_STUDENT_DUE>)CMSHandler.FetchData<FEE_STUDENT_DUE>(objModel, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentFeeDueDetailsForMeetWithoutNegative).Replace("?CLASS_ID", sClassId), sAcademicYear).DataSource.Data;
