        #region paid and unpaid
        /// <summary>
        /// Attendance percentage and fee due report for parent meet
        /// </summary>
        /// <param name="sClassId"></param>
        /// <param name="sProgramId"></param>
        /// <param name="sAcademicYear"></param>
        /// <returns></returns>
        public ActionResult BindFeePaidUnpaidlist(string sClassId, string sProgramId, string sAcademicYear, string sStatus, string sIncludeAttendance, string sparentSign, string sIncludeLateAttendance = "0")
        {
            if (string.IsNullOrEmpty(sAcademicYear))
            {
                sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            }
            string sSemesterType = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_TYPE] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_TYPE].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            var ObjViewModel = new StudentViewModel();
            var ObjJsoneData = new JsonResultData();
            FeeTransactionViewModel objViewModel = new FeeTransactionViewModel();
            FEE_STRUCTURE objModel = new FEE_STRUCTURE();
            try
            {
                ViewBag.isAttCheked = sIncludeAttendance;
                ViewBag.isParentSign = sparentSign;
                ViewBag.isLateAttChecked = sIncludeLateAttendance;

                if (sIncludeAttendance == "1" || sIncludeLateAttendance == "1")
                {
                    var resSem = CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null, SQL.Attendance.AttendanceSQL.GetAttendanceSQL(AttendanceSQLCommands.FetchSemesterEndDatebyProgramme).Replace("?PROGRAMME_GROUP_ID", sProgramId ?? ""), sAcademicYear);
                    if (resSem != null && resSem.DataSource != null && resSem.DataSource.Data != null)
                    {
                        var fetchAcademicsem = (List<ATT_ATTENDANCE_REPORT>)resSem.DataSource.Data;
                        if (fetchAcademicsem != null && fetchAcademicsem.Count > 0 && !string.IsNullOrEmpty(fetchAcademicsem.FirstOrDefault().DATE_TO))
                        {
                            var endDateString = fetchAcademicsem.FirstOrDefault().DATE_TO;
                            var currentDate = DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);
                            DateTime endDate, currentDateParsed;
                            if (DateTime.TryParseExact(endDateString, "dd/MM/yyyy", CultureInfo.InvariantCulture, DateTimeStyles.None, out endDate) &&
                                DateTime.TryParseExact(currentDate, "dd/MM/yyyy", CultureInfo.InvariantCulture, DateTimeStyles.None, out currentDateParsed))
                            {
                                if (endDate > currentDateParsed)
                                {
                                    var resAtt = CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                        SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuAttendanceReportParentMeet).Replace("?ENDDATE", "curdate()").Replace("?CLASS_ID", sClassId ?? ""), sAcademicYear);
                                    if (resAtt != null && resAtt.DataSource != null && resAtt.DataSource.Data != null)
                                    {
                                        objViewModel.liAttendanceReport = (List<ATT_ATTENDANCE_REPORT>)resAtt.DataSource.Data;
                                    }
                                }
                                else
                                {
                                    var resAtt = CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                        SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuAttendanceReportParentMeet).Replace("?ENDDATE", "ASM.DATE_TO").Replace("?CLASS_ID", sClassId ?? ""), sAcademicYear);
                                    if (resAtt != null && resAtt.DataSource != null && resAtt.DataSource.Data != null)
                                    {
                                        objViewModel.liAttendanceReport = (List<ATT_ATTENDANCE_REPORT>)resAtt.DataSource.Data;
                                    }
                                }
                            }
                        }
                    }
                }

                if (sIncludeLateAttendance == "1")
                {
                    var objLateEntry = new STU_LATE_ENTRY { SEMESTER_TYPE = sSemesterType };
                    string query = FeeSQL.GetFeeSQL(FeeSQLCommands.FetchStudentLateEntryAbsentReport);
                    if (!string.IsNullOrEmpty(sClassId) && sClassId != "null" && sClassId != "0" && sClassId != "undefined")
                    {
                        query = query.Replace("?CLASS_ID_CONDITION", "AND SC.CLASS_ID IN (" + sClassId + ")");
                    }
                    else
                    {
                        query = query.Replace("?CLASS_ID_CONDITION", "");
                    }

                    var resLate = CMSHandler.FetchData<STU_LATE_ENTRY>(objLateEntry, query, sAcademicYear);
                    if (resLate != null && resLate.DataSource != null && resLate.DataSource.Data != null)
                    {
                        objViewModel.liStuLateFee = (List<STU_LATE_ENTRY>)resLate.DataSource.Data;
                    }
                }

                if (!string.IsNullOrEmpty(sAcademicYear))
                {
                    objModel.CLASS_ID = sClassId;
                    objModel.ACADEMIC_YEAR = sAcademicYear;
                    if (!string.IsNullOrEmpty(sClassId) && sClassId != "null")
                    {
                        string sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.PaidUnpaidAttendanceList).Replace("?CLASS_ID", sClassId);
                        if (sStatus == "1")
                        {
                            sSql = sSql.Replace("-- p", "");
                        }
                        else if (sStatus == "2")
                        {
                            sSql = sSql.Replace("-- u", "");
                        }

                        var resFee = CMSHandler.FetchData<FEE_STUDENT_DUE>(objModel, sSql, sAcademicYear);
                        if (resFee != null && resFee.DataSource != null && resFee.DataSource.Data != null)
                        {
                            objViewModel.liFeeDueReport = (List<FEE_STUDENT_DUE>)resFee.DataSource.Data;
                        }
                    }
                }
                else
                {
                    return RedirectToAction("ErrorMessage", "error");
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("BindFeePaidUnpaidlist", "Student", "Err Msg: " + ex.Message);
                }
            }
            return View(objViewModel);
        }
