        #region Hall Ticket for student 

        /// <summary>
        /// Auther : Yesudass
        /// Modify Date: 2025-04-15 
        /// Description : Optional papers are also included in the hall ticket validation, so I will validate only the subjects for which marks have been entered in the CIA.
        /// </summary>
        /// <returns></returns>

        public ActionResult ExamHallTicketForStudent()
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            ExaminationViewModel objViewModel = new ExaminationViewModel();
            int totalAbsentCount = 0;
            int DayCount = 0;
            var sPercentageRound = "";
            try
            {
                List<CERTIFICATE_STU_INFO> studentModels = new List<CERTIFICATE_STU_INFO>();
                var fetchAcademicsem = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null, SQL.Attendance.AttendanceSQL.GetAttendanceSQL(AttendanceSQLCommands.FetchSemesterEndDate).Replace("?STUDENT_ID", sUserId), sAcademicYear).DataSource.Data;
                if (fetchAcademicsem != null)
                {
                    var endDateString = fetchAcademicsem.FirstOrDefault().DATE_TO;
                    var currentDate = DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);
                    var endDate = DateTime.ParseExact(endDateString, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                    var currentDateParsed = DateTime.ParseExact(currentDate, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                    List<ATT_ATTENDANCE_REPORT> AttendanceReport = null;
                    if (endDate > currentDateParsed)
                    {
                        AttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                            SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCommonAttendancePercentage)
                                .Replace("?STUDENT_ID", sUserId).Replace("?ENDDATE", "curdate()"), sAcademicYear).DataSource.Data;
                    }
                    else
                    {
                        AttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCommonAttendancePercentage)
                                    .Replace("?STUDENT_ID", sUserId).Replace("?ENDDATE", "ASM.DATE_TO"), sAcademicYear).DataSource.Data;
                    }
                    if (AttendanceReport != null)
                    {
                        totalAbsentCount = Convert.ToInt32(AttendanceReport.FirstOrDefault().ABSENT_COUNT);
                        DayCount = Convert.ToInt32(AttendanceReport.FirstOrDefault().DAYS_COUNT);
                        var sPresentCount = Convert.ToDouble(DayCount) - Convert.ToInt32(totalAbsentCount);
                        var Percentage = Convert.ToDouble(sPresentCount) / Convert.ToDouble(DayCount) * 100;
                        sPercentageRound = Convert.ToString(Math.Round(Percentage, 2));
                    }
                }
                objViewModel.liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails), sAcademicYear).DataSource.Data;
                var currentCoureList = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCourseListByStudentIdForHTValidation).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId).Replace("?SUP_FEEDBACK_ROLE_ID", Common.FBFEEDBACK_ROLE.STAFF_BY_STUDENT), sAcademicYear).DataSource.Data;
                var feedbackEnteredCourseList = (List<CourseInfo>)CMSHandler.FetchData<CourseInfo>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFeedbackEnteredCourseListForHTValidation).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId), sAcademicYear).DataSource.Data;

                // Fetch Regular Papers.
                //var liRegularCourses = (List<EXAM_REGISTRATION>)CMS.DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sUserId },
                //    SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchCourseListForHTValidation), sAcademicYear).DataSource.Data;

                ////Fetch Optional Papers .
                //var liOptionalCourses = (List<EXAM_REGISTRATION>)DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sUserId },
                //             SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchOptionalCoursesForHTValidation), sAcademicYear).DataSource.Data;

                ////Loop Optional Papers  To Remove Unnecessary Courses...
                //if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                //{
                //    foreach (var item in liOptionalCourses)
                //    {
                //        var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                //        if (IsExist != null && IsExist.Count > 0)
                //        {
                //            liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                //            item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                //            liRegularCourses.Add(item);
                //        }
                //        else
                //        {
                //            liRegularCourses.Add(item);
                //        }
                //    }
                //}
                //var LiCourse = liRegularCourses.ToList();

                var liCIATotal = new List<CIA_TOTAL>();
                // Fetch Regular Papers .
                var liRegularCourses = (List<EXAM_REGISTRATION>)CMS.DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sUserId },
                        SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchStudentegularCourseListbyStudentexamRegitration), sAcademicYear).DataSource.Data;

                // Fetch Optional Papers .
                var liOptionalCourses = (List<EXAM_REGISTRATION>)DAO.CMSHandler.FetchData<EXAM_REGISTRATION>(new STU_CLASS() { STUDENT_ID = sUserId },
                             SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchClassWiseOptionalCourseListbyStudent), sAcademicYear).DataSource.Data;

                // Loop Optional Papers  To Remove Unnecessary Courses...
                if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                {
                    foreach (var item in liOptionalCourses)
                    {
                        var IsExist = liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                        if (IsExist != null && IsExist.Count > 0)
                        {
                            liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                            item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                            liRegularCourses.Add(item);
                        }
                        else
                        {
                            liRegularCourses.Add(item);
                        }
                    }

                    objViewModel.liExamRegistrationList = liRegularCourses;
                }
                else
                {
                    objViewModel.liExamRegistrationList = currentCoureList;
                }

                if (objViewModel.liCourseInfo == null)
                {
                    objViewModel.liCourseInfo = new List<CourseInfo>(); // Initialize the list if it's null
                }
                if (currentCoureList != null && currentCoureList.Count > 0)
                {
                    //foreach (var item in currentCoureList)
                    //{ 
                    foreach (var item in objViewModel.liExamRegistrationList)
                    {
                        if (feedbackEnteredCourseList != null && feedbackEnteredCourseList.Count > 0)
                        {
                            var CheckExist = feedbackEnteredCourseList.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList();
                            if (CheckExist == null || CheckExist.Count == 0)
                            {
                                // Convert EXAM_REGISTRATION to CourseInfo before adding
                                objViewModel.liCourseInfo.Add(new CourseInfo
                                {
                                    // Map properties from item to CourseInfo
                                    COURSE_ROOT_ID = item.COURSE_ROOT_ID,
                                    COURSE_CODE = item.COURSE_CODE,
                                    // Add other necessary property mappings
                                });
                            }
                        }
                        else
                        {
                            // Convert EXAM_REGISTRATION to CourseInfo before adding
                            objViewModel.liCourseInfo.Add(new CourseInfo
                            {
                                // Map properties from item to CourseInfo
                                COURSE_ROOT_ID = item.COURSE_ROOT_ID,
                                COURSE_CODE = item.COURSE_CODE,
                                // Add other necessary property mappings
                            });
                        }
                    }
                }
                objViewModel.liFeedbackList = (List<FBFEEDBACK_SETTINGS>)CMSHandler.FetchData<FBFEEDBACK_SETTINGS>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchFeedbackNotEnterSettingForHTValidation).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId), sAcademicYear).DataSource.Data;
                objViewModel.lihallticketValidation = (List<HALL_TICKET_VALIDATION>)CMSHandler.FetchData<HALL_TICKET_VALIDATION>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchHallTicketValidationActiveSetting).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId), sAcademicYear).DataSource.Data;
                objViewModel.liFeeDueDetails = (List<FEE_STUDENT_DUE>)CMSHandler.FetchData<FEE_STUDENT_DUE>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStuDueDetailsForHallTicket).Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId), sAcademicYear).DataSource.Data;

                double rPercentage = Convert.ToDouble(sPercentageRound);

                Double RoundPercentage = Math.Ceiling(rPercentage);
                if (Convert.ToInt64(RoundPercentage) < 55)
                {
                    ViewBag.HTflag = "Redo";
                    ViewBag.Message = "Due to Lack of Attendance (" + sPercentageRound + "%), you are not eligible to appear for the examination. REDO the course in the next semester.";
                }
                else if (Convert.ToInt64(RoundPercentage) < 65)
                {
                    string sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FtechRegularCourseForLactATTHallTicket)
                                           .Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId);
                    objViewModel.liFetchExamHallTicket = (List<STU_HALL_TICKET>)CMSHandler.FetchData<STU_HALL_TICKET>(null, sSql, sAcademicYear).DataSource.Data;
                    if (objViewModel.liFetchExamHallTicket != null)
                    {
                        var Roll_no = objViewModel.liFetchExamHallTicket.FirstOrDefault().ROLL_NO;
                        var dateofBirth = objViewModel.liFetchExamHallTicket.FirstOrDefault().DATE_OF_BIRTH;
                        var student_name = objViewModel.liFetchExamHallTicket.FirstOrDefault().FIRST_NAME;
                        var ClassName = objViewModel.liFetchExamHallTicket.FirstOrDefault().CLASS_NAME;
                        var content = "Student Name: " + student_name + ", Roll No : " + Roll_no + ", Date of Birth : " + dateofBirth + ", Course Name: " + ClassName + "";
                        objViewModel.QRCodeData = CommonMethods.GetEncodeQRCodeWithLogo(content);
                    }
                    ViewBag.HTflag = "ArrearOnly";
                    ViewBag.Message = "You are not eligible to appear for the Regular  examination due to low attendance (" + sPercentageRound + "%).";
                }
                else
                {

                    string sSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchExamHallTicketByForStudent)
                        .Replace(Common.Delimiter.QUS + Common.STUDENT_INFO.STUDENT_ID, sUserId);
                    objViewModel.liFetchExamHallTicket = (List<STU_HALL_TICKET>)CMSHandler.FetchData<STU_HALL_TICKET>(null, sSql, sAcademicYear).DataSource.Data;
                    if (objViewModel.liFetchExamHallTicket != null)
                    {
                        var Roll_no = objViewModel.liFetchExamHallTicket.FirstOrDefault().ROLL_NO;
                        var dateofBirth = objViewModel.liFetchExamHallTicket.FirstOrDefault().DATE_OF_BIRTH;
                        var student_name = objViewModel.liFetchExamHallTicket.FirstOrDefault().FIRST_NAME;
                        var ClassName = objViewModel.liFetchExamHallTicket.FirstOrDefault().CLASS_NAME;
                        var content = "Student Name: " + student_name + ", Roll No : " + Roll_no + ", Date of Birth : " + dateofBirth + ", Course Name: " + ClassName + "";
                        objViewModel.QRCodeData = CommonMethods.GetEncodeQRCodeWithLogo(content);
                    }
                    else
                    {

                        ViewBag.Message = "";
                    }
                    ViewBag.HTflag = "allAccess";
                }
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    Message = "Error",
                    Detail = ex.Message
                }, JsonRequestBehavior.AllowGet);
            }
            return View(objViewModel);
        }
