        public ActionResult BindDisContinueTCPrintView(string sAcademicYear, string sstuname, string sProgramName, string sShift, string classyear, string IsLeft)
        {
            StudentViewModel objViewModel = new StudentViewModel();
            string sRootPath = AppDomain.CurrentDomain.BaseDirectory;
            if (!string.IsNullOrEmpty(sstuname) && !string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {

                    var ObjStuClass = new STU_CLASS();
                    var objAccountInfo = new USER_ACCOUNT_INFO();
                    var studentInfo = new STU_PERSONAL_INFO();
                    var currentDate = DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture);
                    if (IsLeft == "1")
                    {
                        var roleNO = Common.SupRole.STUDENT;
                        var userType = Common.USER_TYPE.STUDENT;
                        var studentIds = sstuname.Split(',');
                        foreach (var item in studentIds)
                        {
                            objAccountInfo.ROLE = roleNO;
                            objAccountInfo.USER_TYPE = userType;
                            objAccountInfo.USER_ID = item;
                            studentInfo.STUDENT_ID = item;
                            studentInfo.ENTRY_DATE = currentDate;
                            studentInfo.IS_DELETED = Common.DeleteFlag.Deleted;
                            var UpdateStuPersonalInfo = CMSHandler.SaveOrUpdate(studentInfo, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateStuPersonalInfoAddLeft));
                            if (UpdateStuPersonalInfo.Success)
                            {
                                var result = (List<STU_CLASS>)CMSHandler.FetchData<STU_CLASS>(new STU_CLASS() { STUDENT_ID = studentInfo.STUDENT_ID, ACADEMIC_YEAR = sAcademicYear }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuclassByStudentIdAndAcademicYear)).DataSource.Data;
                                if (result != null && result.Count > 0)
                                {
                                    ObjStuClass.IS_DELETED = Common.DeleteFlag.Deleted;

                                    ObjStuClass.STU_CLASS_ID = result.FirstOrDefault().STU_CLASS_ID;
                                    var UpdateStuClass = CMSHandler.SaveOrUpdate(ObjStuClass, StudentSQL.GetStudentSQL(StudentSQLCommads.DeletedStuClassbyStuClassID));
                                    if (UpdateStuClass.Success)
                                    {
                                        objAccountInfo.IS_DELETED = Common.DeleteFlag.Deleted;
                                        var UnSafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.UnSafeUpdateMode), sAcademicYear);
                                        resultArgs = CMSHandler.SaveOrUpdate(objAccountInfo, StudentSQL.GetStudentSQL(StudentSQLCommads.DeletedUserAccountbyUserID));
                                        var SafeMode = CMSHandler.SaveOrUpdate(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.SafeUpdateMode), sAcademicYear);
                                    }
                                }
                            }
                            else
                            {
                                ObjJsonData.Message = Common.ErrorCode.NotAcceptable;
                            }

                        }

                    }

                    string sQl = StudentSQL.GetStudentSQL(StudentSQLCommads.BindStudentDetailsforDisTcPrint);

                    objViewModel.litransfercertificteDetils = (List<STU_TRANSFER_CERTIFICATE>)CMS.DAO.CMSHandler.FetchData<STU_TRANSFER_CERTIFICATE>(null, sQl.Replace(Common.Delimiter.QUS + Common.STU_TRANSFER_CERTIFICATE_2017.STUDENT_ID, sstuname), sAcademicYear).DataSource.Data;
                    PrintDisContinueTC(objViewModel.litransfercertificteDetils, sProgramName, sAcademicYear, sShift, classyear);

                    string programmeName = sProgramName;
                    string pdfFileName = $"{programmeName}_.pdf";

                    if (objViewModel.litransfercertificteDetils.Count > 0)
                    {
                        var response = new { Message = "Success", pdfFileName };
                        return Json(response, JsonRequestBehavior.AllowGet);
                    }
                    else
                    {
                        return Json(new { Message = "Error" }, JsonRequestBehavior.AllowGet);
                    }
                }
                catch (Exception ex)
                {
                    using (ErrorLog objHandler = new ErrorLog())
                    {
                        objHandler.WriteError("StudentController", "BindTCPrintViewForNglNew", "Err MSg: " + ex.Message, "Query is empty!");
                        objHandler.WriteError("StudentController", "BindTCPrintViewForNglNew", ex.Message);
                    }
                    sResult = "Fail To Fetch Record(s) ...!";
                    return Json(sResult, JsonRequestBehavior.AllowGet);
                }
            }
            return View(objViewModel);
        }
        private double DTcCenterX(XGraphics graph, string text, XFont font, double startX, double availableWidth)
        {
            double textWidth = graph.MeasureString(text, font).Width;
            return startX + (availableWidth - textWidth) / 2; // Centering calculation
        }
        private double DOTcCenterX(XGraphics graph, string text, XFont font, double startX, double availableWidth)
        {
            double textWidth = graph.MeasureString(text, font).Width;
            return startX + (availableWidth - textWidth) / 2; // Centering calculation
        }
        private void PrintDisContinueTC(List<STU_TRANSFER_CERTIFICATE> studentModels, string sProgramName, string sAcademicYear, string sShift, string classyear)
        {
            string sRootPath = AppDomain.CurrentDomain.BaseDirectory;

            PdfDocument pdf = new PdfDocument();
            pdf.Info.Title = "Transfer Certificate";

            var liCollegeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchCollegeDetail)).DataSource.Data;


            const double pageWidth = 1008;
            const double pageHeight = 612;
            const double halfPageHeight = pageHeight / 2;
            PdfPage pdfPage = null;
            XGraphics graph = null;

            for (int i = 0; i < studentModels.Count; i++)
            {

                // Add a new page for the first student or every two students
                //if (i % 2 == 0)
                //{
                pdfPage = pdf.AddPage();
                pdfPage.Orientation = PageOrientation.Landscape;
                pdfPage.Width = pageWidth;
                pdfPage.Height = pageHeight;
                graph = XGraphics.FromPdfPage(pdfPage);
                XPen dashedPen = new XPen(XColors.Gray, 1);
                dashedPen.DashStyle = XDashStyle.Dash;
                graph.DrawLine(dashedPen, pageWidth / 2, 0, pageWidth / 2, pageHeight);
                //}
                string CurrentDate = DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);

                var student = studentModels[i];

                XFont boldBodyText = new XFont("Times New Roman", 11, XFontStyle.Bold);
                XFont titleFont = new XFont("Times New Roman", 13, XFontStyle.Bold);
                XFont titleFont2 = new XFont("Times New Roman", 13, XFontStyle.Bold);
                XFont titleFont3 = new XFont("Times New Roman", 14, XFontStyle.Bold);

                XFont footer = new XFont("Times New Roman", 10, XFontStyle.Regular);
                XFont RegularBodytitle = new XFont("Times New Roman", 12, XFontStyle.Regular);

                XStringFormat strFmtLeft = new XStringFormat();
                strFmtLeft.Alignment = XStringAlignment.Near;
                strFmtLeft.LineAlignment = XLineAlignment.Near;
                // Enable text wrapping
                XStringFormat strFmtCenter = new XStringFormat();
                strFmtCenter.Alignment = XStringAlignment.Center;
                strFmtCenter.LineAlignment = XLineAlignment.Center;

                float x = 53;
                float x2 = 295;
                float y = 190;
                double yOffset = 0;
                double xOffset = 40;
                double headerCenterX = xOffset + 240;
