        /// <summary>
        /// Update Active and deactive defaulters 
        /// </summary>
        /// <param name="sSettingId"></param>
        /// <param name="sActive"></param>
        /// <returns></returns>
        public JsonResult UpdateActiveNodueDefaulters(string sSettingId, string sActive)
        {

            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sSemesterType = (Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_TYPE] != null) ? Session[Common.SESSION_VARIABLES.ACTIVE_SEMESTER_TYPE].ToString() : string.Empty;
            var ObjJsonData = new JsonResultData();
            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                var UpateActiveSetting = CMSHandler.SaveOrUpdate(new STU_NODUE_DEFAULTERS() { STU_NODUE_DEFALTER_ID = sSettingId, IS_ACTIVE = sActive },
                      StudentSQL.GetStudentSQL(StudentSQLCommads.ActiveOrDeactiveNodueDefaultersList), sAcademicYear);
                if (UpateActiveSetting.Success)
                {
                    ObjJsonData.Message = Common.Messages.RecordsUpdatedSuccessfully;
                    ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                }
                else
                {
                    ObjJsonData.Message = Common.Messages.FailedToUpdatedRecords;
                    ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }
        /// <summary>
        /// Fetch Nodue Defaulters by ID for block nodue form
        /// </summary>
        /// <param name="sDefaulterId"></param>
        /// <returns></returns>
        public JsonResult FetchNodueDefaulterstById(string sDefaulterId)
        {
            JsonResultData objResultData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sStaffId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

            try
            {
                var linodueDefaulters = (List<STU_NODUE_DEFAULTERS>)CMSHandler.FetchData<STU_NODUE_DEFAULTERS>(new STU_NODUE_DEFAULTERS() { STU_NODUE_DEFALTER_ID = sDefaulterId }, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchNodueDefaulterByID), sAcademicYear).DataSource.Data;
                if (linodueDefaulters != null && linodueDefaulters.Count > 0)
                {

                    return Json(linodueDefaulters, JsonRequestBehavior.AllowGet);
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("WebsiteController", "FetchAchievementsById", ex.Message);
                }
                objResultData.Message = Common.ErrorMessage.InternalServerError;
                objResultData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }

            return Json(objResultData, JsonRequestBehavior.AllowGet);
        }
        /// <summary>
        /// Delete Nodue Defaulters by ID for Release nodue form
        /// </summary>
        /// <param name="sDefaultersId"></param>
        /// <returns></returns>
        public JsonResult DeleteNodueDefaultersByID(string sDefaultersId)
        {
            JsonResultData ObjResult = new JsonResultData();
            if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
            {
                if (!string.IsNullOrEmpty(sDefaultersId))
                {
                    var objModel = new STU_NODUE_DEFAULTERS();
                    string sAcademicYear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                    objModel.STU_NODUE_DEFALTER_ID = sDefaultersId;
                    objModel.IS_DELETED = Common.DeleteFlag.Deleted;
                    var sresultArgs = CMSHandler.SaveOrUpdate(objModel, StudentSQL.GetStudentSQL(StudentSQLCommads.DeleteNodueDefaultersList), sAcademicYear);
                    ObjResult.Message = (sresultArgs.Success) ? Common.Messages.RecordDeletedSuccessfully : Common.Messages.FailedToDeletedTryAgain;
                    ObjResult.ErrorCode = (sresultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.BadRequest;
                }
                else
                {
                    ObjResult.ErrorCode = Common.ErrorCode.BadRequest;
                    ObjResult.Message = Common.ErrorMessage.ExpectationFailed;
                }
            }
            else
            {
                ObjResult.ErrorCode = Common.ErrorCode.RequestTimeout;
                ObjResult.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjResult, JsonRequestBehavior.AllowGet);
        }
        public JsonResult SaveOrUpdateNodueDefaulters(string NodueID, string rollNO, string sSemesterType, string sacYear, string sReason)
        {
            ExaminationViewModel ObjViewModel = new ExaminationViewModel();
            var ObjJsonData = new JsonResultData();
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sStaffId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;

            string sMessage = string.Empty;

            var CurrentDate = DateTime.Now.ToString("yyyy-MM-dd");

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                try
                {
                    var noDueDefaulters = new STU_NODUE_DEFAULTERS();


                    var liStudentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(new STU_PERSONAL_INFO() { ROLL_NO = rollNO }, ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchStudentIdbyRollNo), sAcademicYear).DataSource.Data;
                    if (liStudentList != null && liStudentList.Count > 0)
                    {
                        var student = liStudentList[0].STUDENT_ID;

                        noDueDefaulters.STUDENT_ID = student;
                        noDueDefaulters.STU_NODUE_DEFALTER_ID = NodueID;
                        noDueDefaulters.SEMESTER_TYPE = sSemesterType;
                        noDueDefaulters.REASON = sReason;
                        noDueDefaulters.ACADEMIC_YEAR = sacYear;

                        if (!string.IsNullOrEmpty(NodueID))
                        {

                            noDueDefaulters.IS_ACTIVE = "1";
                            noDueDefaulters.STU_NODUE_DEFALTER_ID = NodueID;
                            var UpdateCIAMalpracticeList = CMSHandler.SaveOrUpdate(noDueDefaulters, StudentSQL.GetStudentSQL(StudentSQLCommads.UpdateNodeuDefaulters));

                            if (UpdateCIAMalpracticeList.Success)
                            {
                                ObjJsonData.Message = Common.Messages.RecordsUpdatedSuccessfully;
                                ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                            }
                            else
                            {
                                ObjJsonData.Message = Common.Messages.FailedToUpdatedRecords;
                                ObjJsonData.ErrorCode = Common.ErrorCode.BadRequest;
                            }
                        }
                        else
                        {
                            var chekcExistorNot = (List<STU_NODUE_DEFAULTERS>)CMSHandler.FetchData<STU_NODUE_DEFAULTERS>(noDueDefaulters, StudentSQL.GetStudentSQL(StudentSQLCommads.CheckNDefaultersAlreadyExistOrNot), sAcademicYear).DataSource.Data;
                            if (chekcExistorNot != null && chekcExistorNot.Count > 0)
                            {
                                sMessage = "A record for the same student already exists.";
                                ObjJsonData.Message = sMessage;
                                ObjJsonData.ErrorCode = Common.ErrorCode.NotFound;
                                return Json(ObjJsonData);
                            }
                            else
                            {
                                noDueDefaulters.IS_ACTIVE = "1";
                                var saveCIAMalpracticeList = CMSHandler.SaveOrUpdate(noDueDefaulters, StudentSQL.GetStudentSQL(StudentSQLCommads.saveNodeuDefaulters));

                                if (saveCIAMalpracticeList.Success)
                                {
                                    ObjJsonData.Message = Common.Messages.RecordsSavedSuccessfully;
                                    ObjJsonData.ErrorCode = Common.ErrorCode.Ok;
                                }
                                else
                                {
                                    ObjJsonData.Message = Common.Messages.FailedToSaveRecords;
                                    ObjJsonData.ErrorCode = Common.ErrorCode.BadRequest;
                                }
                            }

                        }
                    }
                    else
                    {
                        sMessage = "The given roll number does not exist. Please check the roll number.";
                        ObjJsonData.Message = sMessage;
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotFound;
                        return Json(ObjJsonData);
                    }

                }
                catch (Exception ex)
                {
                    sMessage = ex.Message;


                    using (ErrorLog ObjLog = new ErrorLog())
                    {
                        ObjLog.WriteError("Examination", "SaveOrUpdateCIAMalpractice", ex.Message);
                        ObjJsonData.Message = ex.Message;
                        ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;

                        return Json(ObjJsonData);
                    }
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }

            if (string.IsNullOrEmpty(ObjJsonData.Message))
            {
                ObjJsonData.Message = "No Changes Made !";
                ObjJsonData.ErrorCode = Common.ErrorCode.NotAcceptable;
            }
            return Json(ObjJsonData);
        }
