        public ActionResult FetchNoDueFormByRollNO(string sRollNo)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            string sUserId = (Session[Common.SESSION_VARIABLES.USER_ID] != null) ? Session[Common.SESSION_VARIABLES.USER_ID].ToString() : string.Empty;
            int totalAbsentCount = 0;
            int DayCount = 0;
            var sPercentageRound = "";
            StudentViewModel objmodel = new StudentViewModel();
            try
            {
                ViewBag.sAcademicYear = sAcademicYear;

                // Initialize the list to store student data

                objmodel.liNodueDefaulters = (List<STU_NODUE_DEFAULTERS>)CMSHandler.FetchData<STU_NODUE_DEFAULTERS>(new STU_NODUE_DEFAULTERS() { ROLL_NO = sRollNo }, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentIdbyRollNo), sAcademicYear).DataSource.Data;
                if (objmodel.liNodueDefaulters != null && objmodel.liNodueDefaulters.Count > 0)
                {
                    sUserId = objmodel.liNodueDefaulters.FirstOrDefault().STUDENT_ID;
                    var studentAcYear = (List<STU_NODUE_DEFAULTERS>)CMSHandler.FetchData<STU_NODUE_DEFAULTERS>(new STU_NODUE_DEFAULTERS() { STUDENT_ID = sUserId }, SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStudentAcYearbyStudentId), null).DataSource.Data;

                    List<CERTIFICATE_STU_INFO> studentModels = new List<CERTIFICATE_STU_INFO>();
                    var fetchAcademicsem = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null, SQL.Attendance.AttendanceSQL.GetAttendanceSQL(AttendanceSQLCommands.FetchSemesterEndDate).Replace("?STUDENT_ID", sUserId), sAcademicYear).DataSource.Data;
                    if (fetchAcademicsem != null)
                    {
                        var endDateString = fetchAcademicsem.FirstOrDefault().DATE_TO;

                        var currentDate = DateTime.Now.ToString("dd/MM/yyyy", System.Globalization.CultureInfo.InvariantCulture);
                        var endDate = DateTime.ParseExact(endDateString, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                        var currentDateParsed = DateTime.ParseExact(currentDate, "dd/MM/yyyy", CultureInfo.InvariantCulture);
                        List<ATT_ATTENDANCE_REPORT> AttendanceReport = null;
                        if (endDate > currentDateParsed)
                        {
                            AttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAttendancePercentageForNoDue)
                                    .Replace("?STUDENT_ID", sUserId).Replace("?ENDDATE", "curdate()"), sAcademicYear).DataSource.Data;
                        }
                        else
                        {
                            AttendanceReport = (List<ATT_ATTENDANCE_REPORT>)CMSHandler.FetchData<ATT_ATTENDANCE_REPORT>(null,
                                    SQL.Student.StudentSQL.GetStudentSQL(StudentSQLCommads.FetchAttendancePercentageForNoDue)
                                        .Replace("?STUDENT_ID", sUserId).Replace("?ENDDATE", "ASM.DATE_TO"), sAcademicYear).DataSource.Data;
                        }
                        if (AttendanceReport != null)
                        {
                            totalAbsentCount = Convert.ToInt32(AttendanceReport.FirstOrDefault().ABSENT_COUNT);
                            DayCount = Convert.ToInt32(AttendanceReport.FirstOrDefault().DAYS_COUNT);
                            var sPresentCount = Convert.ToDouble(DayCount) - Convert.ToInt32(totalAbsentCount);
                            var Percentage = Convert.ToDouble(sPresentCount) / Convert.ToDouble(DayCount) * 100;
                            sPercentageRound = Convert.ToString(Math.Round(Percentage, 2));
                        }
                    }
                    if (studentAcYear != null && studentAcYear.Count > 0)
                    {
                        string sSql = SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchStudentInfoForNoDUeFormAdmin)
