        #region Consolidate Admission Details Report
        public ActionResult BindConsolidateAdmissionDetails(string sAcYear, string sClassLevel, string sShift, string sClassYear = "")
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var ObjViewModel = new StudentViewModel();
            var ObjJsoneData = new JsonResultData();

            try
            {
                if (string.IsNullOrEmpty(sAcYear) || sAcYear == "-- Select --" || sAcYear == "0")
                {
                    sAcYear = sAcademicYear;
                }

                if (string.IsNullOrEmpty(sClassLevel) || sClassLevel == "-- Select --" || sClassLevel == "null")
                {
                    sClassLevel = "1,2";
                }
                sClassLevel = sClassLevel.TrimStart(',');

                if (string.IsNullOrEmpty(sShift) || sShift == "-- Select --" || sShift == "null")
                {
                    sShift = "1,2";
                }
                sShift = sShift.TrimStart(',');

                if (string.IsNullOrEmpty(sClassYear) || sClassYear == "-- Select --" || sClassYear == "null")
                {
                    sClassYear = "1";
                }
                sClassYear = sClassYear.TrimStart(',');

                var acadmicplusOne = Convert.ToInt64(sAcYear) + 1;
                ViewBag.AcademicYear = sAcYear + "-" + acadmicplusOne;
                ViewBag.AcademicYearShort = sAcYear + "-" + acadmicplusOne.ToString().Substring(2);

                List<string> yearLabels = new List<string>();
                var yearParts = sClassYear.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
                foreach (var yp in yearParts)
                {
                    if (yp.Trim() == "1") yearLabels.Add("I");
                    else if (yp.Trim() == "2") yearLabels.Add("II");
                    else if (yp.Trim() == "3") yearLabels.Add("III");
                    else if (yp.Trim() == "4") yearLabels.Add("IV");
                    else yearLabels.Add(yp.Trim());
                }
                string sYearDisplay = yearLabels.Count > 0 ? (string.Join(" & ", yearLabels) + " Year") : "I Year";
                ViewBag.ClassYearText = sYearDisplay;

                ObjViewModel.liCollgeDetails = (List<CollegeDetails>)CMSHandler.FetchData<CollegeDetails>(null, SQL.Examination.ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchCollegeDetails)).DataSource.Data;

                string query = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchConsolidateAdmissionDetailsReport)
                    .Replace("?CLASS_LEVEL", sClassLevel)
                    .Replace("?SHIFT", sShift)
                    .Replace("?CLASS_YEAR", sClassYear)
                    .Replace("?AC_YEAR", sAcYear);

                var rawList = DapperHandler.FetchAll<ConsolidateAdmissionRawStudentData>(query, null);

                // Fetch dynamic communities from SUP_COMMUNITY
                var liCommunities = DapperHandler.FetchAll<SupCommunity>("SELECT DISTINCT COMMUNITYID, COMMUNITY FROM SUP_COMMUNITY WHERE ISDELETED = 0 ORDER BY COMMUNITYORDER, COMMUNITYID;", null);
                ViewBag.Communities = liCommunities;

                // Helper to map community name from SUP_COMMUNITY to the standard 8 categories
                Func<string, string> mapCategory = (commName) =>
                {
                    if (string.IsNullOrWhiteSpace(commName)) return "OC";
                    string c = commName.Trim().ToUpper();
                    if (c == "BCM") return "BCM";
                    if (c == "MBC") return "MBC";
                    if (c == "DNC") return "DNC";
                    if (c == "SCA") return "SCA";
                    if (c == "ST") return "ST";
                    if (c.StartsWith("SC")) return "SC";
                    if (c == "BC" || c == "OBC" || c == "OB") return "BC";
                    return "OC";
                };

                var reportList = new List<ConsolidateAdmissionReportModel>();

                if (rawList != null && rawList.Count > 0)
                {
                    var progGroups = rawList.GroupBy(x => x.PROGRAMME_GROUP_ID)
                        .OrderBy(g => g.First().CLASSLEVELID)
                        .ThenBy(g => g.First().PROGRAMME_NAME)
                        .ThenBy(g => g.First().SHIFT)
                        .ToList();

                    int sno = 0;
                    foreach (var grp in progGroups)
                    {
                        sno++;
                        var first = grp.First();
                        var item = new ConsolidateAdmissionReportModel();
                        item.SL_NO = sno;
                        item.PROGRAMME_GROUP_ID = grp.Key;
                        item.PROGRAMME_ID = first.PROGRAMME_ID;
                        item.PROGRAMME_CODE = first.PROGRAMME_CODE;
                        item.PROGRAMME_NAME = first.PROGRAMME_NAME;
                        item.SHIFT = first.SHIFT;
                        item.SHIFT_NAME = first.SHIFT == 1 ? "Shift I" : "Shift II";
                        item.CLASSLEVEL = first.CLASSLEVEL;
                        item.CLASSLEVELID = first.CLASSLEVELID;
                        item.MEDIUM = (first.MEDIUM_OF_INSTRACTION == 1 || (first.PROGRAMME_NAME != null && first.PROGRAMME_NAME.ToLower().Contains("tamil"))) ? "TM" : "EM";
                        item.SANCTIONED_INTAKE = first.SANCTIONED_INTAKE;
                        item.ADDITIONAL_INTAKE = 0;

                        item.MALE_COUNT = grp.Where(x => x.GENDER_ID == 1).Sum(x => x.STUDENT_COUNT);
                        item.FEMALE_COUNT = grp.Where(x => x.GENDER_ID == 2).Sum(x => x.STUDENT_COUNT);
                        item.TRANS_COUNT = grp.Where(x => x.GENDER_ID == 3).Sum(x => x.STUDENT_COUNT);

                        item.DIFF_MALE = grp.Where(x => x.GENDER_ID == 1 && x.SPECIALLY_ABLED == 1).Sum(x => x.STUDENT_COUNT);
                        item.DIFF_FEMALE = grp.Where(x => x.GENDER_ID == 2 && x.SPECIALLY_ABLED == 1).Sum(x => x.STUDENT_COUNT);
                        item.DIFF_TRANS = grp.Where(x => x.GENDER_ID == 3 && x.SPECIALLY_ABLED == 1).Sum(x => x.STUDENT_COUNT);

                        item.TOTAL_ADMITTED = item.MALE_COUNT + item.FEMALE_COUNT + item.TRANS_COUNT;
                        item.SEATS_VACANT = Math.Max(0, (item.SANCTIONED_INTAKE + item.ADDITIONAL_INTAKE) - item.TOTAL_ADMITTED);

                        // Male categories
                        item.M_OC = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "OC").Sum(x => x.STUDENT_COUNT);
                        item.M_BC = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "BC").Sum(x => x.STUDENT_COUNT);
                        item.M_BCM = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "BCM").Sum(x => x.STUDENT_COUNT);
                        item.M_DNC = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "DNC").Sum(x => x.STUDENT_COUNT);
                        item.M_MBC = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "MBC").Sum(x => x.STUDENT_COUNT);
                        item.M_SC = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "SC").Sum(x => x.STUDENT_COUNT);
                        item.M_ST = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "ST").Sum(x => x.STUDENT_COUNT);
                        item.M_SCA = grp.Where(x => x.GENDER_ID == 1 && mapCategory(x.COMMUNITY_NAME) == "SCA").Sum(x => x.STUDENT_COUNT);

                        // Female categories
                        item.F_OC = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "OC").Sum(x => x.STUDENT_COUNT);
                        item.F_BC = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "BC").Sum(x => x.STUDENT_COUNT);
                        item.F_BCM = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "BCM").Sum(x => x.STUDENT_COUNT);
                        item.F_DNC = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "DNC").Sum(x => x.STUDENT_COUNT);
                        item.F_MBC = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "MBC").Sum(x => x.STUDENT_COUNT);
                        item.F_SC = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "SC").Sum(x => x.STUDENT_COUNT);
                        item.F_ST = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "ST").Sum(x => x.STUDENT_COUNT);
                        item.F_SCA = grp.Where(x => x.GENDER_ID == 2 && mapCategory(x.COMMUNITY_NAME) == "SCA").Sum(x => x.STUDENT_COUNT);

                        // Transgender categories
                        item.T_OC = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "OC").Sum(x => x.STUDENT_COUNT);
                        item.T_BC = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "BC").Sum(x => x.STUDENT_COUNT);
                        item.T_BCM = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "BCM").Sum(x => x.STUDENT_COUNT);
                        item.T_DNC = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "DNC").Sum(x => x.STUDENT_COUNT);
                        item.T_MBC = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "MBC").Sum(x => x.STUDENT_COUNT);
                        item.T_SC = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "SC").Sum(x => x.STUDENT_COUNT);
                        item.T_ST = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "ST").Sum(x => x.STUDENT_COUNT);
                        item.T_SCA = grp.Where(x => x.GENDER_ID == 3 && mapCategory(x.COMMUNITY_NAME) == "SCA").Sum(x => x.STUDENT_COUNT);

                        reportList.Add(item);
                    }
                }

                ObjViewModel.liConsolidateAdmission = reportList;
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjLog = new ErrorLog())
                {
                    ObjLog.WriteError("StudentController", "BindConsolidateAdmissionDetails", ex.Message);
                }
                ObjJsoneData.ErrorCode = Common.ErrorCode.InternalServerError;
                ObjJsoneData.Message = Common.ErrorMessage.InternalServerError;
                return Json(ObjJsoneData, JsonRequestBehavior.AllowGet);
            }

            return View(ObjViewModel);
        }
