        public ActionResult GetConsolidatedPersonalInfo(string sRollNo)
        {
            var objViewModel = new StudentViewModel();
            ViewBag.RollNo = sRollNo;
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            try
            {
                var sql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchConsolidatedPersonalInfo);
                objViewModel.liStudent = DapperHandler.FetchAll<STU_PERSONAL_INFO>(sql, new { ROLL_NO = sRollNo });

                if (objViewModel.liStudent != null && objViewModel.liStudent.Count > 0)
                {
                    var student = objViewModel.liStudent.First();
                    string studentId = student.STUDENT_ID;

                    // Fetch Left & Rejoin status flags
                    var statusSql = @"SELECT IS_LEFT, IS_REJOIN FROM stu_personal_info WHERE ROLL_NO = @ROLL_NO AND IS_DELETED != 1;";
                    var statusList = DapperHandler.FetchAll<dynamic>(statusSql, new { ROLL_NO = sRollNo });
                    if (statusList != null && statusList.Count > 0)
                    {
                        var dict = statusList.FirstOrDefault() as IDictionary<string, object>;
                        if (dict != null)
                        {
                            ViewBag.IsLeft = dict["IS_LEFT"]?.ToString();
                            ViewBag.IsRejoined = dict["IS_REJOIN"]?.ToString();
                        }
                    }

                    // 1. If left, fetch left reason and details
                    if (ViewBag.IsLeft == "1")
                    {
                        var leftDetailsSql = @"
                            SELECT 
                                slr.REASON AS LeftReason, 
                                spi.REMARKS AS LeftRemarks, 
                                DATE_FORMAT(spi.ENTRY_DATE, '%d/%m/%Y') AS LeftDate
                            FROM
                                stu_personal_info AS spi
                                    LEFT JOIN
                                sup_left_reason AS slr ON slr.REASON_ID = spi.LEFT_REASON 
                            WHERE spi.ROLL_NO = @ROLL_NO AND spi.IS_LEFT = 1;";
                        var leftDetailsList = DapperHandler.FetchAll<dynamic>(leftDetailsSql, new { ROLL_NO = sRollNo });
                        if (leftDetailsList != null && leftDetailsList.Count > 0)
                        {
                            var leftDetails = leftDetailsList.First() as IDictionary<string, object>;
                            if (leftDetails != null)
                            {
                                ViewBag.LeftReason = leftDetails["LeftReason"]?.ToString();
                                ViewBag.LeftRemarks = leftDetails["LeftRemarks"]?.ToString();
                                ViewBag.LeftDate = leftDetails["LeftDate"]?.ToString();
                            }
                        }
                    }
                    // 2. If not left, check if course completed (no active stu_class entry for current academic year)
                    else if (!string.IsNullOrEmpty(sAcademicYear))
                    {
                        var currentClassSql = @"SELECT COUNT(1) FROM stu_class WHERE STUDENT_ID = @STUDENT_ID AND ACADEMIC_YEAR = @AC_YEAR AND IS_DELETED != 1;";
                        var activeClassEntriesList = DapperHandler.FetchAll<int>(currentClassSql, new { STUDENT_ID = studentId, AC_YEAR = sAcademicYear });
                        int activeClassEntries = (activeClassEntriesList != null && activeClassEntriesList.Count > 0) ? activeClassEntriesList.First() : 0;
                        if (activeClassEntries == 0)
                        {
                            ViewBag.IsCourseCompleted = "1";
                        }
                    }

                    // Fetch Rejoin history if student has rejoined
                    if (ViewBag.IsRejoined == "1")
                    {
                        var rejoinSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchRejoinedHistoryByRollNo);
                        ViewBag.RejoinHistory = DapperHandler.FetchAll<RejoinedHistoryRecord>(rejoinSql, new { ROLL_NO = sRollNo });
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "GetConsolidatedPersonalInfo", ex.Message);
                }
            }
            return PartialView("GetConsolidatedPersonalInfo", objViewModel);
        }

        public ActionResult GetConsolidatedAcademicInfo(string sRollNo)
        {
            string sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            var list = new List<ConsolidatedAcademicMark>();
            try
            {
                if (!string.IsNullOrEmpty(sAcademicYear))
                {
                    // 1. Get STUDENT_ID using sRollNo
                    var infoSql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchConsolidatedPersonalInfo);
                    var students = DapperHandler.FetchAll<STU_PERSONAL_INFO>(infoSql, new { ROLL_NO = sRollNo });
                    if (students != null && students.Count > 0)
                    {
                        var student = students.First();
                        string studentId = student.STUDENT_ID;

                        // 2. Fetch Semester IDs to get BEGIN_YEAR and EXPIRED_YEAR
                        var semSql = ExaminationSQL.GetExaminationSQL(ExaminationSQLCommands.FetchSemesterIdsByStudentIdAndAcademicYear);
                        var liSemesterIds = (List<ACADEMIC_SEMESTER>)CMSHandler.FetchData<ACADEMIC_SEMESTER>(
                            new STU_CLASS() { STUDENT_ID = studentId },
                            semSql,
                            sAcademicYear
                        ).DataSource.Data;

                        int beginYear = 0;
                        int endYear = 0;

                        if (liSemesterIds != null && liSemesterIds.Count > 0)
                        {
                            beginYear = Convert.ToInt32(liSemesterIds.First().BEGIN_YEAR);
                            endYear = Convert.ToInt32(liSemesterIds.First().EXPIRED_YEAR);
                        }

                        // Fallback if batch years could not be determined
                        if (beginYear == 0 || endYear == 0)
                        {
                            string startYearStr = sAcademicYear.Split('-')[0].Trim();
                            int parsedYear;
                            if (int.TryParse(startYearStr, out parsedYear))
                            {
                                beginYear = parsedYear - 2;
                                endYear = parsedYear + 2;
                            }
                            else
                            {
                                beginYear = DateTime.Now.Year - 3;
                                endYear = DateTime.Now.Year + 3;
                            }
                        }

                        // 3. Loop through each academic year from beginYear to endYear
                        var markSqlTemplate = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchConsolidatedAcademicMarks);
                        for (int year = beginYear; year <= endYear; year++)
                        {
                            string targetYearStr = year.ToString();
                            try
                            {
                                var sql = markSqlTemplate.Replace("?AC_YEAR", targetYearStr);
                                var marks = (List<ConsolidatedAcademicMark>)CMSHandler.FetchData<ConsolidatedAcademicMark>(
                                    new STU_PERSONAL_INFO() { ROLL_NO = sRollNo },
                                    sql,
                                    targetYearStr
                                ).DataSource.Data;

                                if (marks != null && marks.Count > 0)
                                {
                                    list.AddRange(marks);
                                }
                            }
                            catch (Exception ex)
                            {
                                using (ErrorLog objHandler = new ErrorLog())
                                {
                                    objHandler.WriteError("StudentController", "GetConsolidatedAcademicInfo_Year_" + targetYearStr, ex.Message);
                                }
                            }
                        }

                        // 4. Remove duplicate records and sort by Semester Name
                        if (list != null && list.Count > 0)
                        {
                            list = list
                                .GroupBy(x => new { x.COURSE_CODE, x.SEMESTER_NAME })
                                .Select(g => g.First())
                                .OrderBy(x => x.SEMESTER_NAME)
                                .ThenBy(x => x.COURSE_CODE)
                                .ToList();
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "GetConsolidatedAcademicInfo", ex.Message);
                }
            }
            return PartialView("GetConsolidatedAcademicInfo", list);
        }

