        public ActionResult GetConsolidatedAttendanceInfo(string sRollNo, string semesterId, string academicYear = "")
        {
            try
            {
                if (string.IsNullOrEmpty(semesterId))
                {
                    var sql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchConsolidatedSemesterAttendance);
                    var list = DapperHandler.FetchAll<ConsolidatedSemesterAttendance>(sql, new { ROLL_NO = sRollNo });
                    foreach (var item in list)
                    {
                        item.PRESENT_COUNT = item.DAYS_COUNT - item.ABSENT_COUNT;
                        if (item.PRESENT_COUNT < 0) item.PRESENT_COUNT = 0;
                        item.PERCENTAGE = (item.DAYS_COUNT > 0) ? Math.Round(((double)item.PRESENT_COUNT / item.DAYS_COUNT) * 100, 2) : 0;
                    }
                    ViewBag.IsSummary = true;
                    return PartialView("GetConsolidatedAttendanceInfo", list);
                }
                else
                {
                    var sql = StudentSQL.GetStudentSQL(StudentSQLCommads.FetchConsolidatedAbsentReport);
                    var list = DapperHandler.FetchAll<ConsolidatedAbsentRecord>(sql, new { ROLL_NO = sRollNo, SEMESTER_ID = semesterId, ACADEMIC_YEAR = academicYear ?? "" });
                    ViewBag.IsSummary = false;
                    ViewBag.SemesterId = semesterId;
                    return PartialView("GetConsolidatedAttendanceInfo", list);
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "GetConsolidatedAttendanceInfo", ex.Message);
                }
            }
            return PartialView("GetConsolidatedAttendanceInfo", new List<ConsolidatedSemesterAttendance>());
        }

