        public ActionResult GetConsolidatedCIAMarks(string sRollNo)
        {
            var ObjViewModel = new ExaminationViewModel();
            try
            {
                string sStudentId = string.Empty;
                var studentInfo = DapperHandler.FetchAll<STU_PERSONAL_INFO>("SELECT STUDENT_ID FROM stu_personal_info WHERE ROLL_NO = @ROLL_NO AND IS_DELETED != 1;", new { ROLL_NO = sRollNo });
                if (studentInfo != null && studentInfo.Count > 0)
                {
                    sStudentId = studentInfo.FirstOrDefault().STUDENT_ID;
                }

                if (!string.IsNullOrEmpty(sStudentId))
                {
                    // Fetch Begin Year and Expired Year chronologically
                    var batchSql = @"SELECT DISTINCT B.BEGIN_YEAR, B.EXPIRED_YEAR 
                                     FROM sup_batch_duration AS B
                                     WHERE B.BATCH_ID = (SELECT BATCH FROM stu_class WHERE STUDENT_ID = @STUDENT_ID AND IS_DELETED != 1 ORDER BY ACADEMIC_YEAR DESC LIMIT 1);";
                    var batchDuration = DapperHandler.FetchAll<dynamic>(batchSql, new { STUDENT_ID = sStudentId });
                    
                    if (batchDuration != null && batchDuration.Count > 0)
                    {
                        var dict = batchDuration.FirstOrDefault() as IDictionary<string, object>;
                        if (dict != null && dict["BEGIN_YEAR"] != null && dict["EXPIRED_YEAR"] != null)
                        {
                            int nBeginYear = Convert.ToInt32(dict["BEGIN_YEAR"]);
                            int nExpiredYear = Convert.ToInt32(dict["EXPIRED_YEAR"]);
                            var liCIATotal = new List<CIA_TOTAL>();
                            var liAllRegularCourses = new List<EXAM_REGISTRATION>();

                            for (int i = nBeginYear; i <= nExpiredYear; i++)
                            {
                                string currentYear = i.ToString();

                                // Fetch Regular Papers
                                var liRegularCourses = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(
                                    new STU_CLASS() { STUDENT_ID = sStudentId },
                                    SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchOddAndEvenSemCourseByStudent), 
                                    currentYear
                                ).DataSource.Data;

                                // Fetch Optional Papers
                                var liOptionalCourses = (List<EXAM_REGISTRATION>)CMSHandler.FetchData<EXAM_REGISTRATION>(
                                    new STU_CLASS() { STUDENT_ID = sStudentId },
                                    SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchOddAndEvenSemOptionalCourseByStudent), 
                                    currentYear
                                ).DataSource.Data;

                                // Merge Optional Papers
                                if (liOptionalCourses != null && liOptionalCourses.Count > 0)
                                {
                                    if (liRegularCourses == null) liRegularCourses = new List<EXAM_REGISTRATION>();
                                    foreach (var item in liOptionalCourses)
                                    {
                                        var IsExist = (liRegularCourses != null) ? liRegularCourses.Where(o => o.COURSE_ROOT_ID == item.COURSE_ROOT_ID).ToList() : null;
                                        if (IsExist != null && IsExist.Count > 0)
                                        {
                                            liRegularCourses.RemoveAll(o => o.COURSE_STRUCTURE_ID == IsExist.FirstOrDefault().COURSE_STRUCTURE_ID);
                                            item.COURSE_STRUCTURE_ID = IsExist.FirstOrDefault().COURSE_STRUCTURE_ID;
                                            liRegularCourses.Add(item);
                                        }
                                        else
                                        {
                                            liRegularCourses.Add(item);
                                        }
                                    }
                                }

                                if (liRegularCourses != null && liRegularCourses.Count > 0)
                                {
                                    liAllRegularCourses.AddRange(liRegularCourses);
                                    foreach (var item in liRegularCourses)
                                    {
                                        item.STUDENT_ID = sStudentId;
                                        item.COURSE_ID = item.COURSE_ROOT_ID;
                                        var liCIAMarks = (List<CIA_MARKS_INFO>)CMSHandler.FetchData<CIA_MARKS_INFO>(
                                            item, 
                                            SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchCIAMarksByCourseIdAndStudentId), 
                                            currentYear
                                        ).DataSource.Data;

                                        if (liCIAMarks != null && liCIAMarks.Count > 0)
                                        {
                                            ObjViewModel.liCIA_Marks_Info = (ObjViewModel.liCIA_Marks_Info != null && ObjViewModel.liCIA_Marks_Info.Count > 0) 
                                                ? ObjViewModel.liCIA_Marks_Info.Concat(liCIAMarks).ToList() 
                                                : liCIAMarks;
                                        }

                                        var liCIA_Total = (List<CIA_TOTAL>)CMSHandler.FetchData<CIA_TOTAL>(
                                            item, 
                                            SQL.Examination.ExaminationSQL.GetExaminationSQL(DAO.ExaminationSQLCommands.FetchCIATotalByStudentAndCourseId), 
                                            currentYear
                                        ).DataSource.Data;

                                        if (liCIA_Total != null && liCIA_Total.Count > 0)
                                        {
                                            liCIA_Total.ForEach(o => {
                                                if (o.TOTAL != null)
                                                {
                                                    o.TOTAL = Math.Round(Convert.ToDecimal((o.TOTAL).ToUpper().Equals("A") ? "0" : o.TOTAL), MidpointRounding.AwayFromZero).ToString();
                                                }
                                            });
                                            liCIATotal = (liCIATotal != null && liCIATotal.Count > 0) ? liCIATotal.Concat(liCIA_Total).ToList() : liCIA_Total;
                                        }
                                    }
                                }
                            }
                            ObjViewModel.liExamRegistrationList = liAllRegularCourses;
                            ObjViewModel.liCIA_Total = liCIATotal;
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("StudentController", "GetConsolidatedCIAMarks", ex.Message);
                }
            }
            return PartialView("GetConsolidatedCIAMarks", ObjViewModel);
        }

