                    var liAcYear = (List<ACADEMIC_YEAR>)CMSHandler.FetchData<ACADEMIC_YEAR>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchAcademicYearList)).DataSource.Data;
                    if (liAcYear != null && liAcYear.Count > 0)
                    {
                        obj.AcademicYear = new SelectList(liAcYear, Common.ACADEMIC_YEAR.ACADEMIC_YEAR_ID, Common.ACADEMIC_YEAR.AC_YEAR);
                    }

                    // Class ....
                    var liClasses = (List<cp_Classes_2017>)CMSHandler.FetchData<cp_Classes_2017>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchRegularclass)).DataSource.Data;
                    if (liClasses != null && liClasses.Count > 0)
                    {
                        obj.ClassList = new SelectList(liClasses, Common.CP_CLASSES_2017.CLASS_ID, Common.CP_CLASSES_2017.CLASS_NAME);

                    }
                    var liSemester = (List<SUP_SEMESTER>)CMSHandler.FetchData<SUP_SEMESTER>(null, SupportDataSQL.GetSupportDataSQL(SupportDataSQLCommands.FetchSemester)).DataSource.Data;
                    if (liSemester != null && liSemester.Count > 0)
                    {
                        obj.SemesterList = new SelectList(liSemester, Common.SUP_SEMESTER.SUP_SEMESTER_ID, Common.SUP_SEMESTER.SEMESTER_NAME);

                    }

                    return View(obj);
                }
                catch (Exception ex)
                {
                    using (ErrorLog ObjHandler = new ErrorLog())
                    {
                        ObjHandler.WriteError("StudentController", "StudentOptionalCourseView", "Err MSg: " + ex.Message, "Query is empty!");
                        ObjHandler.WriteError("StudentController", "StudentOptionalCourseView", ex.Message);
                    }
                    return View(obj);
                }
            }
            else
            {
                sResult = Common.ErrorCode.RequestTimeout;
                return Json(sResult, JsonRequestBehavior.AllowGet);
            }
        }
