        public JsonResult SaveBulkStudentOptionalCourse(string sStuCourseInfo, string sSemId, string sClassId, string sCourseId, string sSClassId, string sAcYear)
        {
            Stu_Course_Info objModel = new Stu_Course_Info();
            JsonResultData objResult = new JsonResultData();
            JavaScriptSerializer serializer = new JavaScriptSerializer();
            string sSQL = string.Empty;
            try
            {
                if (sStuCourseInfo != null)
                {
                    if (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null)
                    {
                        var sAcademicyear = Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString();
                        var Result = serializer.Deserialize<JsonStuCourseInfo>(sStuCourseInfo);
                        if (sClassId != sSClassId)
                        {
                            var CourseStaff = (List<CP_CLASS_COURSE_STAFF>)CMSHandler.FetchData<CP_CLASS_COURSE_STAFF>(objModel, StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStaffByOptionalCoursesAndClassId), sAcYear).DataSource.Data;
                            if (CourseStaff != null && CourseStaff.Count > 0)
                            {
                                objModel.STAFF_ID = CourseStaff.FirstOrDefault().STAFF_ID;
                            }
                        }
                        else
                        {
                            objModel.STAFF_ID = "";
                        }
                        if (Result.SelectedStudentList != null && Result.SelectedStudentList.Count > 0)
                        {
                            sSQL = string.Empty;
                            if (objModel.STAFF_ID != null && objModel.STAFF_ID != "")
                            {
                                sSQL = @"INSERT INTO STU_COURSE_INFO
                                (
                                COURSE_ID,
                                CLASS_ID,
                                STUDENT_ID,
                                IS_ACTIVE,
                                S_CLASS_ID,
                                ACADEMIC_YEAR,
                                SEMESTER,
                                STAFF_ID
                                 )VALUES";
                                foreach (var item in Result.SelectedStudentList)
                                {
                                    item.STAFF_ID = objModel.STAFF_ID;
                                    sSQL += "('" + sCourseId + "','" + sClassId + "','" + item.STUDENT_ID + "','1','" + sSClassId + "','" + sAcYear + "','" + sSemId + "','" + item.STAFF_ID + "'),";
                                }
                            }
                            else
                            {
                                sSQL = @"INSERT INTO STU_COURSE_INFO
                                (
                                COURSE_ID,
                                CLASS_ID,
                                STUDENT_ID,
                                IS_ACTIVE,
                                S_CLASS_ID,
                                ACADEMIC_YEAR,
                                SEMESTER
                                 )VALUES";
                                foreach (var item in Result.SelectedStudentList)
                                {

                                    sSQL += "('" + sCourseId + "','" + sClassId + "','" + item.STUDENT_ID + "','1','" + sSClassId + "','" + sAcYear + "','" + sSemId + "'),";
                                }
                            }
                            sSQL = sSQL.TrimEnd(',');
                            var sresultArgs = CMSHandler.SaveOrUpdate(objModel, sSQL, sAcademicyear);
                            objResult.ErrorCode = (sresultArgs.Success) ? Common.ErrorCode.Ok : Common.ErrorCode.ExpectationFailed;
                            objResult.Message = (sresultArgs.Success) ? Common.Messages.RecordsSavedSuccessfully : Common.Messages.FailedToSaveRecords;
                        }


                    }
                    else
                    {
                        objResult.ErrorCode = Common.ErrorCode.RequestTimeout;
                        objResult.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                    }
                }
                else
                {
                    objResult.ErrorCode = Common.ErrorCode.BadRequest;
                    objResult.Message = Common.ErrorMessage.BadRequest;
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog objHandler = new ErrorLog())
                {
                    objHandler.WriteError("SaveBulkStudentOptionalCourse", "Student", "Err MSg: " + ex.Message, "Query is empty!");
                    objHandler.WriteError("SaveBulkStudentOptionalCourse", "Student", ex.Message);
                }
            }
            return Json(objResult, JsonRequestBehavior.AllowGet);
        }

        public JsonResult FetchOptionalCourseListForUpload(string sSemId, string sAcYear)
        {
            JsonResultData ObjJsonData = new JsonResultData();
            string sAcademicYear = sAcYear;
            if (string.IsNullOrEmpty(sAcademicYear))
            {
                sAcademicYear = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;
            }

            if (!string.IsNullOrEmpty(sAcademicYear))
            {
                string sSQL = @"SELECT 
                                    COURSE_ROOT_ID,
                                    CONCAT(COURSE_CODE, ' - ', COURSE_TITLE) AS COURSE_TITLE
                                FROM
                                    CP_COURSE_ROOT AS CR 
                                    inner join
                                    cp_course_pattern as cp on cp.COURSE_ID =COURSE_ROOT_ID
                                WHERE
                                     SEMESTER_ID=?SEMESTER_ID AND CP.ACADEMIC_YEAR =?AC_YEAR
                                     group by COURSE_ROOT_ID;";
                
                var dummyObj = new CP_COURSE_ROOT { SEMESTER_ID = sSemId };
                var OCourseList = (List<CP_COURSE_ROOT>)CMSHandler.FetchData<CP_COURSE_ROOT>(dummyObj, sSQL, sAcademicYear).DataSource.Data;
                if (OCourseList != null && OCourseList.Count > 0)
                {
                    foreach (var OptionalClass in OCourseList)
                        ObjJsonData.sResult += "<option value='" + OptionalClass.COURSE_ROOT_ID + "'>" + OptionalClass.COURSE_TITLE + "</option>";
                }
            }
            else
            {
                ObjJsonData.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
            }
            return Json(ObjJsonData, JsonRequestBehavior.AllowGet);
        }

