        public ActionResult DownloadOptionalCourseTemplate()
        {
            try
            {
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
                using (ExcelPackage package = new ExcelPackage())
                {
                    ExcelWorksheet ws = package.Workbook.Worksheets.Add("Optional Course Template");

                    ws.Cells[1, 1].Value = "S.no";
                    ws.Cells[1, 2].Value = "Name";
                    ws.Cells[1, 3].Value = "ROLL_NO";

                    using (var range = ws.Cells[1, 1, 1, 3])
                    {
                        range.Style.Font.Bold = true;
                    }

                    ws.Cells[2, 1].Value = 1;
                    ws.Cells[2, 2].Value = "test";
                    ws.Cells[2, 3].Value = "A26ACD100";

                    ws.Cells[3, 1].Value = 2;
                    ws.Cells[3, 2].Value = "test";
                    ws.Cells[3, 3].Value = "A26BCD90";

                    ws.Cells.AutoFitColumns();

                    using (var stream = new MemoryStream())
                    {
                        package.SaveAs(stream);
                        string fileName = "Student_Optional_Course_Template.xlsx";
                        string contentType = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
                        return File(stream.ToArray(), contentType, fileName);
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjHandler = new ErrorLog())
                {
                    ObjHandler.WriteError("StudentController", "DownloadOptionalCourseTemplate", ex.Message);
                }
                return RedirectToAction("ErrorMessage", "Error");
            }
        }

        [HttpPost]
        public JsonResult UploadOptionalCourseExcel(HttpPostedFileBase excelFile, string sAcYear, string sSemId, string sCourseId, string sSClassId, string sStaffId)
        {
            JsonResultData objResult = new JsonResultData();
            string sAcademicYearSession = (Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR] != null) ? Session[Common.SESSION_VARIABLES.ACADEMIC_YEAR].ToString() : string.Empty;

            if (string.IsNullOrEmpty(sAcademicYearSession))
            {
                objResult.ErrorCode = Common.ErrorCode.RequestTimeout;
                objResult.Message = Common.Messages.SessionIsExpiredPleaseLoginAgain;
                return Json(objResult);
            }

            if (excelFile == null || excelFile.ContentLength == 0)
            {
                objResult.ErrorCode = Common.ErrorCode.BadRequest;
                objResult.Message = "Please select a valid excel file.";
                return Json(objResult);
            }

            try
            {
                ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
                using (var package = new OfficeOpenXml.ExcelPackage(excelFile.InputStream))
                {
                    var ws = package.Workbook.Worksheets.FirstOrDefault();
                    if (ws == null)
                    {
                        objResult.ErrorCode = Common.ErrorCode.BadRequest;
                        objResult.Message = "Excel sheet is empty.";
                        return Json(objResult);
                    }

                    int rowCount = ws.Dimension.Rows;
                    int successCount = 0;
                    int failedCount = 0;
                    string errorList = "";

                    int rollNoCol = 3;
                    for (int col = 1; col <= ws.Dimension.Columns; col++)
                    {
                        string header = Convert.ToString(ws.Cells[1, col].Value).Trim().ToUpper();
                        if (header == "ROLL_NO" || header == "ROLLNO")
                        {
                            rollNoCol = col;
                            break;
                        }
                    }

                    List<string> rollNumbers = new List<string>();
                    for (int row = 2; row <= rowCount; row++)
                    {
                        string rollNo = Convert.ToString(ws.Cells[row, rollNoCol].Value).Trim();
                        if (!string.IsNullOrEmpty(rollNo))
                        {
                            rollNumbers.Add(rollNo);
                        }
                    }

                    if (rollNumbers.Count == 0)
                    {
                        objResult.ErrorCode = Common.ErrorCode.BadRequest;
                        objResult.Message = "No student roll numbers found in the excel.";
                        return Json(objResult);
                    }

                    foreach (var rollNo in rollNumbers)
                    {
                        var studentObj = new STU_PERSONAL_INFO { ROLL_NO = rollNo };
                        var studentList = (List<STU_PERSONAL_INFO>)CMSHandler.FetchData<STU_PERSONAL_INFO>(
                            studentObj, 
                            StudentSQL.GetStudentSQL(StudentSQLCommads.AcadamicIfExits)
                        ).DataSource.Data;

                        if (studentList == null || studentList.Count == 0)
                        {
                            failedCount++;
                            errorList += "- " + rollNo + " (Roll number not found)\n";
                            continue;
                        }

                        string studentId = studentList.FirstOrDefault().STUDENT_ID;

                        var stuClassObj = new StudentPromotionList { STUDENT_ID = studentId, ACADEMIC_YEAR = sAcYear };
                        var classInfoList = (List<StudentPromotionList>)CMSHandler.FetchData<StudentPromotionList>(
                            stuClassObj, 
                            StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuclassInfoByStudentIdAndAcademicYear)
                        ).DataSource.Data;

                        if (classInfoList == null || classInfoList.Count == 0)
                        {
                            failedCount++;
                            errorList += "- " + rollNo + " (No active class assignment for year " + sAcYear + ")\n";
                            continue;
                        }

                        string classId = classInfoList.FirstOrDefault().CLASS_ID;

                        Stu_Course_Info objModel = new Stu_Course_Info
                        {
                            STUDENT_ID = studentId,
                            COURSE_ID = sCourseId,
                            S_CLASS_ID = sSClassId,
                            CLASS_ID = classId,
                            SEMESTER = sSemId,
                            STAFF_ID = sStaffId
                        };

                        var IsExistAlready = (List<Stu_Course_Info>)CMSHandler.FetchData<Stu_Course_Info>(
                            objModel, 
                            StudentSQL.GetStudentSQL(StudentSQLCommads.FetchStuOptionalCourseFromStuCourseToCheck), 
                            sAcYear
                        ).DataSource.Data;

                        if (IsExistAlready != null && IsExistAlready.Count > 0)
                        {
                            successCount++;
                            continue;
                        }

                        var result = CMSHandler.SaveOrUpdate(objModel, StudentSQL.GetStudentSQL(StudentSQLCommads.InsertStuCourseInfo), sAcYear);
                        if (result.Success && result.RowsAffected != 0)
                        {
                            successCount++;
                        }
                        else
                        {
                            failedCount++;
                            errorList += "- " + rollNo + " (Database save failed)\n";
                        }
                    }

                    if (failedCount == 0)
                    {
                        objResult.ErrorCode = Common.ErrorCode.Ok;
                        objResult.Message = successCount + " student records uploaded successfully!";
                    }
                    else
                    {
                        objResult.ErrorCode = Common.ErrorCode.PartialContent;
                        objResult.Message = successCount + " student records uploaded successfully.\n\nFailed Roll Numbers:\n" + errorList.TrimEnd('\n');
                    }
                }
            }
            catch (Exception ex)
            {
                using (ErrorLog ObjHandler = new ErrorLog())
                {
                    ObjHandler.WriteError("StudentController", "UploadOptionalCourseExcel", ex.Message);
                }
                objResult.ErrorCode = Common.ErrorCode.ExpectationFailed;
                objResult.Message = "An error occurred while uploading. Details logged.";
            }

            return Json(objResult);
        }
